    private val vanillaArmorMaterialConstants = setOf(
        "LEATHER",
        "CHAIN",
        "IRON",
        "GOLD",
        "DIAMOND",
        "TURTLE",
        "NETHERITE",
        "ARMADILLO"
    )

    private fun migrateLegacyArmorMaterialsHolderSource(source: String): String {
        if (!source.contains("ArmorMaterials")) return source
        var result = source
        var needsBuiltInRegistriesImport = false
        var needsHolderImport = false
        var needsArmorMaterialImport = false
        if (result.contains("ArmorMaterials.CODEC")) {
            result = result.replace("ArmorMaterials.CODEC", "BuiltInRegistries.ARMOR_MATERIAL.holderByNameCodec()")
            needsBuiltInRegistriesImport = true
        }
        result = migrateLegacyArmorMaterialInstanceofPatterns(result)
        result = Regex("""\bArmorMaterials\s+([A-Za-z_$][\w$]*)""")
            .replace(result) {
                needsHolderImport = true
                needsArmorMaterialImport = true
                "Holder<ArmorMaterial> ${it.groupValues[1]}"
            }
        result = Regex("""\bMap\s*<\s*ArmorMaterials\s*,\s*String\s*>""")
            .replace(result) {
                needsHolderImport = true
                needsArmorMaterialImport = true
                "Map<Holder<ArmorMaterial>, String>"
            }
        val switchMigrated = migrateLegacyArmorMaterialSwitches(result)
        if (switchMigrated != result) {
            result = switchMigrated
            needsHolderImport = true
            needsArmorMaterialImport = true
        }
        if (result.contains("Holder<ArmorMaterial>")) {
            needsHolderImport = true
            needsArmorMaterialImport = true
        }
        if (needsHolderImport) {
            result = addImportIfMissing(result, "net.minecraft.core.Holder")
        }
        if (needsBuiltInRegistriesImport) {
            result = addImportIfMissing(result, "net.minecraft.core.registries.BuiltInRegistries")
        }
        if (needsArmorMaterialImport) {
            result = addImportIfMissing(result, "net.minecraft.world.item.ArmorMaterial")
        }
        return result
    }

    private fun migrateLegacyArmorMaterialInstanceofPatterns(source: String): String {
        if (!source.contains("instanceof ArmorMaterials")) return source
        val pattern = Regex("""if\s*\(\s*([^\r\n{};]+?)\s+instanceof\s+ArmorMaterials\s+([A-Za-z_$][\w$]*)\s*\)\s*\{""")
        var result = source
        var cursor = 0
        while (true) {
            val match = pattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last)
            if (openBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val indentStart = result.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
            val indent = result.substring(indentStart, match.range.first).takeWhile { it == ' ' || it == '\t' }
            val materialExpression = match.groupValues[1].trim()
            val variable = match.groupValues[2]
            val body = result.substring(openBrace + 1, closeBrace)
            val vanillaGuard = vanillaArmorMaterialConstants.joinToString(" || ") {
                "$variable.is(ArmorMaterials.$it)"
            }
            val replacement = "{\n" +
                "$indent    Holder<ArmorMaterial> $variable = $materialExpression;\n" +
                "$indent    if ($vanillaGuard) {$body\n" +
                "$indent    }\n" +
                "$indent}"
            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private data class ArmorMaterialSwitchCase(
        val constants: List<String>,
        val body: String
    )

    private fun migrateLegacyArmorMaterialSwitches(source: String): String {
        if (!source.contains("switch") || !source.contains("Holder<ArmorMaterial>")) return source
        var result = source
        var cursor = 0
        val switchPattern = Regex("""switch\s*\(\s*([A-Za-z_$][\w$]*)\s*\)\s*\{""")
        while (true) {
            val match = switchPattern.find(result, cursor) ?: break
            val variable = match.groupValues[1]
            if (!holderArmorMaterialVariables(result).contains(variable)) {
                cursor = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', match.range.last)
            if (openBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val switchBody = result.substring(openBrace + 1, closeBrace)
            val cases = parseArmorMaterialSwitchCases(switchBody)
            if (cases == null) {
                cursor = closeBrace + 1
                continue
            }
            val indentStart = result.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
            val indent = result.substring(indentStart, match.range.first).takeWhile { it == ' ' || it == '\t' }
            val replacement = buildString {
                cases.forEachIndexed { index, case ->
                    if (index > 0) append(" else ")
                    append("if")
                    append(" (")
                    append(case.constants.joinToString(" || ") { "$variable.is(ArmorMaterials.$it)" })
                    append(") {")
                    append(case.body.trimEnd())
                    append("\n")
                    append(indent)
                    append("}")
                }
            }
            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private fun holderArmorMaterialVariables(source: String): Set<String> =
        Regex("""\bHolder\s*<\s*ArmorMaterial\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()

    private fun parseArmorMaterialSwitchCases(body: String): List<ArmorMaterialSwitchCase>? {
        val cases = mutableListOf<ArmorMaterialSwitchCase>()
        var cursor = 0
        while (true) {
            while (cursor < body.length && body[cursor].isWhitespace()) cursor++
            if (cursor >= body.length) break
            val match = Regex("""case\s+([A-Z0-9_,.\s]+?)\s*->""").find(body, cursor)
                ?: return null
            if (match.range.first != cursor) return null
            val constants = match.groupValues[1]
                .split(',')
                .map { it.trim().removePrefix("ArmorMaterials.") }
                .filter { it.isNotEmpty() }
            if (constants.isEmpty() || constants.any { it !in vanillaArmorMaterialConstants }) return null
            cursor = match.range.last + 1
            while (cursor < body.length && body[cursor].isWhitespace()) cursor++
            val caseBody = if (cursor < body.length && body[cursor] == '{') {
                val closeBrace = findMatchingBrace(body, cursor)
                if (closeBrace < 0) return null
                val text = body.substring(cursor + 1, closeBrace)
                cursor = closeBrace + 1
                text
            } else {
                val semicolon = body.indexOf(';', cursor)
                if (semicolon < 0) return null
                val text = body.substring(cursor, semicolon + 1)
                cursor = semicolon + 1
                "\n$text"
            }
            cases += ArmorMaterialSwitchCase(constants, caseBody)
        }
        return cases.takeIf { it.isNotEmpty() }
    }

    private fun migrateTextColorParseColorLiteralSource(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("TextColor.parseColor(")) return source
        val literalColor = Regex(""""#([0-9A-Fa-f]{6})"""")
        return rewriteExecutableJavaCall(source, "parseColor") { receiver, args ->
            if (receiver != "TextColor" || args.size != 1) return@rewriteExecutableJavaCall null
            val color = literalColor.matchEntire(args[0].trim()) ?: return@rewriteExecutableJavaCall null
            "TextColor.fromRgb(0x${color.groupValues[1].uppercase()})"
        }
    }

    private fun migrateGameProfileDisplayNameComponents(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("ComponentUtils.getDisplayName(")) return source

        var result = rewriteExecutableJavaCall(source, "getDisplayName") { receiver, args ->
            if (receiver != "ComponentUtils" || args.size != 1) return@rewriteExecutableJavaCall null
            val profile = args[0].trim()
            "Component.literal($profile.getName())"
        }
        if (result == source) return source

        result = addImportIfMissing(result, "net.minecraft.network.chat.Component")
        val withoutComponentUtils = removeImport(result, "net.minecraft.network.chat.ComponentUtils")
        if (!Regex("""\bComponentUtils\b""").containsMatchIn(maskJavaCommentsAndLiterals(withoutComponentUtils))) {
            result = withoutComponentUtils
        }
        return result
    }

    private fun migrateLegacyBlockEntityRenderBoundingBoxOverride(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("getRenderBoundingBox(") ||
            collectJavaClassDeclarations(executableCode).none { javaClassExtendsAny(it, javaBlockEntityBaseTypes(), javaInheritanceIndex) }) {
            return source
        }
        return replaceExecutableRegex(
            source,
            Regex("""(?m)^([ \t]*)@Override\s*\r?\n(?=\1(?:@[\w.]+(?:\([^)]*\))?\s*\r?\n\1)*public\s+(?:AABB|net\.minecraft\.world\.phys\.AABB)\s+getRenderBoundingBox\s*\()""")
        ) { "" }
    }

    private fun migrateRegistryAccessEmptyFallbacks(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val qualifiedEmpty = "net.minecraft.core.RegistryAccess.EMPTY"
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(qualifiedEmpty)) return source
        val edits = mutableListOf<Pair<IntRange, String>>()
        var cursor = 0
        while (cursor < executableCode.length) {
            val index = executableCode.indexOf(qualifiedEmpty, cursor)
            if (index < 0) break
            val replacement = registryAccessExpressionAt(source, index, javaInheritanceIndex)
            if (replacement == null || replacement == qualifiedEmpty) {
                cursor = index + qualifiedEmpty.length
                continue
            }
            edits += index until index + qualifiedEmpty.length to replacement
            cursor = index + qualifiedEmpty.length
        }
        return applyStringEdits(source, edits)
    }

    private fun migrateFluidTankNbtProviderCalls(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if ((!executableCode.contains(".writeToNBT(") && !executableCode.contains(".readFromNBT(")) ||
            !executableCode.contains("FluidTank")) {
            return source
        }
        val fluidTankType = """(?:FluidTank|net\.neoforged\.neoforge\.fluids\.capability\.templates\.FluidTank)"""
        val declaredTankVariables = Regex("""\b$fluidTankType\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(executableCode)
            .map { it.groupValues[1] }
            .toSet()
        val lazyOptionalTankVariables = Regex(
            """\bLazyOptional\s*<\s*$fluidTankType\s*>\s+[A-Za-z_$][\w$]*[\s\S]*?\.ifPresent\s*\(\s*([A-Za-z_$][\w$]*)\s*->"""
        ).findAll(executableCode)
            .map { it.groupValues[1] }
            .toSet()
        val tankVariables = declaredTankVariables + lazyOptionalTankVariables
        if (tankVariables.isEmpty()) return source

        var result = source
        for (tank in tankVariables) {
            result = replaceExecutableRegex(
                result,
                Regex("""\b${Regex.escape(tank)}\.writeToNBT\(\s*(?![^)]*,)([^;\r\n]+?)\s*\)""")
            ) { match ->
                val provider = registryAccessExpressionAt(result, match.range.first, javaInheritanceIndex)
                    ?: return@replaceExecutableRegex match.value
                "$tank.writeToNBT($provider, ${match.groupValues[1].trim()})"
            }
            result = replaceExecutableRegex(
                result,
                Regex("""\b${Regex.escape(tank)}\.readFromNBT\(\s*(?![^)]*,)([^;\r\n]+?)\s*\)""")
            ) { match ->
                val provider = registryAccessExpressionAt(result, match.range.first, javaInheritanceIndex)
                    ?: return@replaceExecutableRegex match.value
                "$tank.readFromNBT($provider, ${match.groupValues[1].trim()})"
            }
        }
        return result
    }

    private fun migrateFluidStackNbtProviderCalls(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("FluidStack") ||
            !executableCode.contains(".writeToNBT(") &&
            !executableCode.contains("FluidStack.loadFluidStackFromNBT(")
        ) {
            return source
        }
        val fluidStackType = """(?:FluidStack|net\.neoforged\.neoforge\.fluids\.FluidStack)"""
        val fluidStackVariables = Regex("""\b$fluidStackType\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(executableCode)
            .map { it.groupValues[1] }
            .toSet()

        var result = source
        for (fluidStack in fluidStackVariables) {
            result = rewriteExecutableJavaCallWithOffset(result, "writeToNBT") { receiver, args, offset ->
                if (receiver.trim() != fluidStack || args.size != 1) {
                    return@rewriteExecutableJavaCallWithOffset null
                }
                val provider = registryAccessExpressionAt(result, offset, javaInheritanceIndex)
                    ?: return@rewriteExecutableJavaCallWithOffset null
                "(CompoundTag) $receiver.save($provider, ${args[0].trim()})"
            }
        }
        result = rewriteExecutableJavaCallWithOffset(result, "loadFluidStackFromNBT") { receiver, args, offset ->
            if (receiver.trim() != "FluidStack" || args.size != 1) {
                return@rewriteExecutableJavaCallWithOffset null
            }
            val provider = registryAccessExpressionAt(result, offset, javaInheritanceIndex)
                ?: return@rewriteExecutableJavaCallWithOffset null
            "FluidStack.parseOptional($provider, ${args[0].trim()})"
        }
        return result
    }

    private fun migrateLegacyFluidStackDeprecations(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("FluidStack") &&
            !executableCode.contains(".getDisplayName()") &&
            !executableCode.contains(".getTranslationKey()") &&
            !executableCode.contains(".isFluidEqual(")
        ) {
            return source
        }
        val fluidStackVariables = Regex("""\b(?:net\.neoforged\.neoforge\.fluids\.)?FluidStack\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(executableCode)
            .map { it.groupValues[1] }
            .toSet()
        var result = source
        fluidStackVariables.forEach { variable ->
            result = replaceExecutableJavaRegex(result, Regex("""\b${Regex.escape(variable)}\.getDisplayName\(\)""")) {
                "$variable.getHoverName()"
            }
            result = replaceExecutableJavaRegex(result, Regex("""\b${Regex.escape(variable)}\.getTranslationKey\(\)""")) {
                "$variable.getDescriptionId()"
            }
        }
        result = rewriteExecutableJavaCallWithOffset(result, "getDisplayName") { receiver, args, _ ->
            if (args.isNotEmpty()) return@rewriteExecutableJavaCallWithOffset null
            val trimmed = receiver.trim()
            if (trimmed.startsWith("new FluidStack(") || trimmed.startsWith("new net.neoforged.neoforge.fluids.FluidStack(")) {
                "$trimmed.getHoverName()"
            } else {
                null
            }
        }
        result = rewriteExecutableJavaCallWithOffset(result, "getTranslationKey") { receiver, args, _ ->
            if (args.isNotEmpty()) return@rewriteExecutableJavaCallWithOffset null
            val trimmed = receiver.trim()
            if (trimmed.startsWith("new FluidStack(") || trimmed.startsWith("new net.neoforged.neoforge.fluids.FluidStack(")) {
                "$trimmed.getDescriptionId()"
            } else {
                null
            }
        }
        result = replaceFluidStackConstructorNoArgCall(result, "getDisplayName", "getHoverName")
        result = replaceFluidStackConstructorNoArgCall(result, "getTranslationKey", "getDescriptionId")
        result = rewriteExecutableJavaCallWithOffset(result, "isFluidEqual") { receiver, args, _ ->
            if (args.size != 1) return@rewriteExecutableJavaCallWithOffset null
            val trimmed = receiver.trim()
            val supportedReceiver = trimmed in fluidStackVariables ||
                trimmed.endsWith(".getFluid()") ||
                trimmed.startsWith("new FluidStack(") ||
                trimmed.startsWith("new net.neoforged.neoforge.fluids.FluidStack(")
            if (!supportedReceiver) return@rewriteExecutableJavaCallWithOffset null
            "FluidStack.isSameFluidSameComponents($trimmed, ${args[0].trim()})"
        }
        return result
    }

    private fun replaceFluidStackConstructorNoArgCall(source: String, oldMethod: String, newMethod: String): String {
        var result = source
        var cursor = 0
        while (cursor < result.length) {
            val executable = maskJavaCommentsAndLiterals(result)
            val match = Regex("""new\s+(?:net\.neoforged\.neoforge\.fluids\.)?FluidStack\s*\(""").find(executable, cursor) ?: break
            val openParen = executable.indexOf('(', match.range.last)
            if (openParen < 0) break
            val closeParen = findMatchingParen(executable, openParen)
            if (closeParen < 0) break
            val after = Regex("""^\s*\.\s*${Regex.escape(oldMethod)}\s*\(\s*\)""")
                .find(executable.substring(closeParen + 1))
            if (after == null) {
                cursor = closeParen + 1
                continue
            }
            val methodNameStart = closeParen + 1 + after.value.indexOf(oldMethod)
            result = result.substring(0, methodNameStart) + newMethod + result.substring(methodNameStart + oldMethod.length)
            cursor = methodNameStart + newMethod.length
        }
        return result
    }

    private fun migrateXlintCleanApiDeprecations(
        source: String,
        mobEffectDeferredHolderFields: Set<String>,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        var result = source
        result = migrateLegacyFoodEffectSuppliers(result)
        result = migrateDeprecatedTextureAtlasLocationConstants(result)
        result = migrateDeprecatedBlockStateLiquidChecks(result)
        result = migrateDeprecatedMobEffectHolderComparisons(result, mobEffectDeferredHolderFields)
        result = migrateWeightedEntryWrapperArraysToLists(result)
        result = migrateLegacyBlockCloneItemStackOverrides(result, javaInheritanceIndex)
        result = migrateDeprecatedStructureProcessorProcessBlockOverrides(result)
        result = migrateDeprecatedBlockRenderDispatcherSingleBlockCalls(result)
        result = migrateDeprecatedBakedModelGetQuadsCallSites(result)
        result = migrateDeprecatedItemTransformsConstructors(result)
        result = migrateDeprecatedStructureGenerationHelpers(result)
        result = migrateDeprecatedRenderSystemRunAsFancy(result)
        result = markRequiredDeprecatedOverrides(result)
        return result
    }

    private fun migrateLegacyFoodEffectSuppliers(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".effect(") || !executableCode.contains("MobEffectInstance")) return source
        var result = source
        var cursor = 0
        while (true) {
            val executable = maskJavaCommentsAndLiterals(result)
            val tokenIndex = executable.indexOf(".effect(", cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".effect".length
            val closeParen = findMatchingParen(executable, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + ".effect(".length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 2) {
                cursor = closeParen + 1
                continue
            }
            val effect = args[0].trim()
            if (!effect.startsWith("new MobEffectInstance(") &&
                !effect.startsWith("new net.minecraft.world.effect.MobEffectInstance(")) {
                cursor = closeParen + 1
                continue
            }
            val replacementArgs = "() -> $effect, ${args[1].trim()}"
            result = result.substring(0, openParen + 1) + replacementArgs + result.substring(closeParen)
            cursor = openParen + 1 + replacementArgs.length
        }
        return result
    }

    private fun migrateDeprecatedTextureAtlasLocationConstants(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("LOCATION_BLOCKS")) return source
        var result = replaceExecutableJavaRegex(
            source,
            Regex("""\bnet\.minecraft\.client\.renderer\.texture\.TextureAtlas\.LOCATION_BLOCKS\b""")
        ) {
            "net.minecraft.world.inventory.InventoryMenu.BLOCK_ATLAS"
        }
        result = replaceExecutableJavaRegex(result, Regex("""\bTextureAtlas\.LOCATION_BLOCKS\b""")) {
            "InventoryMenu.BLOCK_ATLAS"
        }
        if (result == source) return source
        if (maskJavaCommentsAndLiterals(result).contains("InventoryMenu.BLOCK_ATLAS")) {
            result = addExecutableImportIfMissing(result, "net.minecraft.world.inventory.InventoryMenu")
        }
        val withoutTextureAtlas = removeExecutableImport(result, "net.minecraft.client.renderer.texture.TextureAtlas")
        result = if (!Regex("""(?<![\w$.])TextureAtlas(?![\w$])""").containsMatchIn(maskJavaCommentsAndLiterals(withoutTextureAtlas))) {
            withoutTextureAtlas
        } else {
            result
        }
        return result
    }

    private fun migrateDeprecatedBlockStateLiquidChecks(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".liquid()")) return source
        var result = replaceExecutableJavaRegex(
            source,
            Regex("""!\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.liquid\s*\(\s*\)""")
        ) { match ->
            "${match.groupValues[1]}.getFluidState().isEmpty()"
        }
        result = rewriteExecutableJavaCall(result, "liquid") { receiver, args ->
            if (args.isNotEmpty()) return@rewriteExecutableJavaCall null
            "!${receiver.trim()}.getFluidState().isEmpty()"
        }
        return result
    }

    private fun migrateDeprecatedMobEffectHolderComparisons(
        source: String,
        mobEffectDeferredHolderFields: Set<String>
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".is(") ||
            !executableCode.contains("MobEffects.") &&
            mobEffectDeferredHolderFields.none { executableCode.contains(it.substringAfterLast('.', missingDelimiterValue = it)) }) {
            return source
        }

        val deferredHolderExpressions = mobEffectDeferredHolderFields
            .flatMap { field ->
                val parts = field.split('.')
                when {
                    parts.size >= 2 -> listOf(field, parts.takeLast(2).joinToString("."))
                    else -> listOf(field)
                }
            }
            .distinct()
            .sortedByDescending { it.length }

        fun holderKeyExpression(argument: String): String? {
            val trimmed = argument.trim()
            if (Regex("""MobEffects\.[A-Z0-9_]+""").matches(trimmed)) {
                return "$trimmed.unwrapKey().orElseThrow()"
            }
            if (trimmed in deferredHolderExpressions) {
                return "$trimmed.getKey()"
            }
            return null
        }

        return rewriteExecutableJavaCall(source, "is") { receiver, args ->
            if (args.size != 1) return@rewriteExecutableJavaCall null
            val key = holderKeyExpression(args[0]) ?: return@rewriteExecutableJavaCall null
            "${receiver.trim()}.is($key)"
        }
    }

    private fun migrateWeightedEntryWrapperArraysToLists(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("WeightedEntry.Wrapper") ||
            !executableCode.contains(".toArray(WeightedEntry.Wrapper[]::new)")) {
            return source
        }
        var changed = false
        var result = replaceExecutableJavaRegex(
            source,
            Regex("""(?ms)^([ \t]*)WeightedEntry\.Wrapper\s*<\s*([^>\r\n]+)\s*>\s*\[\]\s+([A-Za-z_$][\w$]*)\s*=\s*(.*?)\.toArray\s*\(\s*WeightedEntry\.Wrapper\[\]::new\s*\)\s*;""")
        ) { match ->
            changed = true
            val indent = match.groupValues[1]
            val type = match.groupValues[2].trim()
            val name = match.groupValues[3]
            val streamExpression = match.groupValues[4].trim()
            "${indent}List<WeightedEntry.Wrapper<$type>> $name = $streamExpression.toList();"
        }
        if (!changed) return source
        result = addExecutableImportIfMissing(result, "java.util.List")
        return result
    }

    private fun migrateLegacyBlockCloneItemStackOverrides(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("getCloneItemStack(") ||
            !executableCode.contains("LevelReader") ||
            !executableCode.contains("BlockPos") ||
            !executableCode.contains("BlockState")) {
            return source
        }

        val signaturePattern = Regex(
            """(?s)(public\s+(?:@[A-Za-z_$][\w$.]*(?:\([^)]*\))?\s+)*ItemStack\s+)getCloneItemStack\s*\(\s*LevelReader\s+([A-Za-z_$][\w$]*)\s*,\s*BlockPos\s+([A-Za-z_$][\w$]*)\s*,\s*BlockState\s+([A-Za-z_$][\w$]*)\s*\)"""
        )
        var result = source
        val edits = mutableListOf<Pair<IntRange, String>>()
        signaturePattern.findAll(executableCode).forEach { signature ->
                val openBrace = executableCode.indexOf('{', signature.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(executableCode, openBrace) else -1
                if (openBrace < 0 || closeBrace < 0) return@forEach
                val methodRange = signature.range.first..closeBrace
                val methodText = result.substring(methodRange)
                val levelName = signature.groupValues[2]
                val posName = signature.groupValues[3]
                val stateName = signature.groupValues[4]
                val classDeclaration = enclosingJavaClassDeclaration(executableCode, methodRange.first)
                val directlyExtendsBlock = classDeclaration?.directSuper?.substringAfterLast('.') == "Block"
                if (methodText.contains("super.getCloneItemStack(") && !directlyExtendsBlock) {
                    return@forEach
                }

                var migratedMethod = signaturePattern.replaceFirst(
                    methodText,
                    "${signature.groupValues[1]}getCloneItemStack(BlockState $stateName, HitResult target, LevelReader $levelName, BlockPos $posName, Player player)"
                )
                if (directlyExtendsBlock) {
                    migratedMethod = replaceExecutableJavaRegex(
                        migratedMethod,
                        Regex("""if\s*\(\s*true\s*\)\s*return\s+super\.getCloneItemStack\s*\(\s*${Regex.escape(levelName)}\s*,\s*${Regex.escape(posName)}\s*,\s*${Regex.escape(stateName)}\s*\)\s*;\s*""")
                    ) { "" }
                    migratedMethod = replaceExecutableJavaRegex(
                        migratedMethod,
                        Regex("""super\.getCloneItemStack\s*\(\s*${Regex.escape(levelName)}\s*,\s*${Regex.escape(posName)}\s*,\s*${Regex.escape(stateName)}\s*\)""")
                    ) { "new ItemStack(this)" }
                }
                if (migratedMethod != methodText) {
                    edits += methodRange to migratedMethod
                }
            }
        if (edits.isEmpty()) return source

        result = applyStringEdits(source, edits)
        result = addExecutableImportIfMissing(result, "net.minecraft.world.entity.player.Player")
        result = addExecutableImportIfMissing(result, "net.minecraft.world.phys.HitResult")
        return result
    }

    private fun migrateDeprecatedStructureProcessorProcessBlockOverrides(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("processBlock(") ||
            !executableCode.contains("StructureTemplate.StructureBlockInfo") ||
            !executableCode.contains("StructurePlaceSettings")) {
            return source
        }
        var result = source
        val edits = mutableListOf<Pair<IntRange, String>>()
        for (method in javaMethodRangesIncludingDefault(executableCode)) {
            if (method.name != "processBlock") continue
            val methodText = result.substring(method.range)
            val methodExecutable = executableCode.substring(method.range)
            if (!Regex("""\bLevelReader\s+[A-Za-z_$][\w$]*""").containsMatchIn(methodExecutable) ||
                !Regex("""\bStructurePlaceSettings\s+[A-Za-z_$][\w$]*""").containsMatchIn(methodExecutable) ||
                !Regex("""\bStructureTemplate\.StructureBlockInfo\s+[A-Za-z_$][\w$]*""").containsMatchIn(methodExecutable)) {
                continue
            }
            val tokenIndex = methodExecutable.indexOf("processBlock")
            if (tokenIndex < 0) continue
            val openParen = methodExecutable.indexOf('(', tokenIndex)
            val closeParen = if (openParen >= 0) findMatchingParen(methodExecutable, openParen) else -1
            if (openParen < 0 || closeParen < 0) continue
            val params = splitTopLevelJavaArgs(methodText.substring(openParen + 1, closeParen))
            if (params.size != 6) continue
            val templateName = uniqueJavaIdentifier("structureTemplate", javaIdentifierTokens(methodText))
            val signatureMigrated = methodText.substring(0, tokenIndex) +
                "process" +
                methodText.substring(tokenIndex + "processBlock".length, closeParen) +
                ", @Nullable StructureTemplate $templateName" +
                methodText.substring(closeParen)
            val migratedMethod = rewriteExecutableJavaCall(signatureMigrated, "processBlock") { receiver, args ->
                if (receiver.trim() == "super" && args.size == 6) {
                    "super.process(${args.joinToString(", ") { it.trim() }}, $templateName)"
                } else {
                    null
                }
            }
            if (migratedMethod != methodText) {
                edits += method.range to migratedMethod
            }
        }
        if (edits.isEmpty()) return source
        result = applyStringEdits(source, edits)
        val executableResult = maskJavaCommentsAndLiterals(result)
        if (Regex("""(?<![\w$])@Nullable(?![\w$])""").containsMatchIn(executableResult) &&
            !executableResult.contains("import org.jetbrains.annotations.Nullable;") &&
            !executableResult.contains("import javax.annotation.Nullable;")) {
            result = addExecutableImportIfMissing(result, "javax.annotation.Nullable")
        }
        return result
    }

    private fun migrateDeprecatedBlockRenderDispatcherSingleBlockCalls(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".renderSingleBlock(")) return source
        val dispatcherVariables = javaVariablesOfType(executableCode, "BlockRenderDispatcher")
        var changed = false
        var result = rewriteExecutableJavaCall(source, "renderSingleBlock") { receiver, args ->
            if (args.size != 5 || !isBlockRenderDispatcherExpression(receiver, dispatcherVariables)) {
                return@rewriteExecutableJavaCall null
            }
            changed = true
            "${receiver.trim()}.renderSingleBlock(${args.joinToString(", ") { it.trim() }}, ModelData.EMPTY, null)"
        }
        if (changed) {
            result = addExecutableImportIfMissing(result, "net.neoforged.neoforge.client.model.data.ModelData")
        }
        return result
    }

    private fun isBlockRenderDispatcherExpression(receiver: String, dispatcherVariables: Set<String>): Boolean {
        val normalized = receiver.trim()
        if (normalized in dispatcherVariables) return true
        return normalized.endsWith(".getBlockRenderer()") ||
            normalized == "Minecraft.getInstance().getBlockRenderer()" ||
            normalized.endsWith(".blockRenderer") && normalized.substringAfterLast('.') in dispatcherVariables
    }

    private fun migrateDeprecatedBakedModelGetQuadsCallSites(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".getQuads(")) return source
        val bakedModelVariables = javaVariablesOfType(executableCode, "BakedModel")
        var changed = false
        var result = rewriteExecutableJavaCall(source, "getQuads") { receiver, args ->
            if (args.size != 3 || !isBakedModelExpression(receiver, bakedModelVariables)) {
                return@rewriteExecutableJavaCall null
            }
            changed = true
            "${receiver.trim()}.getQuads(${args.joinToString(", ") { it.trim() }}, ModelData.EMPTY, null)"
        }
        if (changed) {
            result = addExecutableImportIfMissing(result, "net.neoforged.neoforge.client.model.data.ModelData")
        }
        return result
    }

    private fun isBakedModelExpression(receiver: String, bakedModelVariables: Set<String>): Boolean {
        val normalized = receiver.trim()
        if (normalized in bakedModelVariables) return true
        return normalized.contains(".getBlockModel(") ||
            normalized.contains(".getModel(")
    }

    private fun migrateDeprecatedItemTransformsConstructors(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("new ItemTransforms(") &&
            !executableCode.contains("new net.minecraft.client.renderer.block.model.ItemTransforms(")) {
            return source
        }
        var result = source
        var cursor = 0
        while (cursor < result.length) {
            val executable = maskJavaCommentsAndLiterals(result)
            val match = Regex("""new\s+(?:net\.minecraft\.client\.renderer\.block\.model\.)?ItemTransforms\s*\(""")
                .find(executable, cursor)
                ?: break
            val openParen = executable.indexOf('(', match.range.last)
            val closeParen = if (openParen >= 0) findMatchingParen(executable, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 8) {
                cursor = closeParen + 1
                continue
            }
            val replacement = args.joinToString(", ") { it.trim() } + ", com.google.common.collect.ImmutableMap.of()"
            result = result.substring(0, openParen + 1) + replacement + result.substring(closeParen)
            cursor = openParen + 1 + replacement.length
        }
        return result
    }

    private fun javaVariablesOfType(source: String, simpleType: String): Set<String> {
        val id = """[A-Za-z_$][\w$]*"""
        val type = """(?:[A-Za-z_$][\w$]*\.)*${Regex.escape(simpleType)}"""
        return Regex("""(?<![\w$])(?:final\s+)?$type\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
    }

    private fun migrateDeprecatedLevelReaderHasChunksAtCalls(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        var compatPackageCache: String? = null
        fun compatPackage(): String {
            val existing = compatPackageCache
            if (existing != null) return existing
            val detected = detectRequiredGeneratedCompatPackage(projectDir, "LevelReader hasChunksAt compatibility helper")
            compatPackageCache = detected
            return detected
        }

        val changes = mutableListOf<Change>()
        var helperNeeded = false
        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            val executableCode = maskJavaCommentsAndLiterals(original)
            if (!executableCode.contains(".hasChunksAt(")) return@forEach
            val levelReaderVariables = javaVariablesOfLevelReaderType(executableCode)
            var changed = false
            var migrated = rewriteExecutableJavaCall(original, "hasChunksAt") { receiver, args ->
                if (args.size != 2 || !isLevelReaderExpression(receiver, levelReaderVariables)) {
                    return@rewriteExecutableJavaCall null
                }
                changed = true
                helperNeeded = true
                "LevelReaderCompat.hasChunksAt(${receiver.trim()}, ${args[0].trim()}, ${args[1].trim()})"
            }
            if (!changed) return@forEach
            migrated = addExecutableImportIfMissing(migrated, "${compatPackage()}.LevelReaderCompat")
            if (!dryRun) javaFile.writeText(migrated)
            changes.add(Change(
                file = javaFile,
                line = 0,
                description = "Replace deprecated LevelReader.hasChunksAt(BlockPos, BlockPos) with non-deprecated chunk-range helper",
                before = "level.hasChunksAt(from, to)",
                after = "LevelReaderCompat.hasChunksAt(level, from, to)",
                confidence = Confidence.HIGH,
                ruleId = "struct-levelreader-haschunksat-helper"
            ))
        }

        if (helperNeeded) {
            val packageName = compatPackage()
            val helperFile = srcDir.resolve(packageName.replace('.', '/')).resolve("LevelReaderCompat.java")
            val helperSource = generatedLevelReaderCompatSource(packageName)
            val previous = if (helperFile.exists()) helperFile.readText() else null
            if (previous != helperSource) {
                if (!dryRun) {
                    helperFile.parent.createDirectories()
                    helperFile.writeText(helperSource)
                }
                changes.add(Change(
                    file = helperFile,
                    line = 0,
                    description = "Generate LevelReader chunk-range helper using non-deprecated hasChunk calls",
                    before = "deprecated LevelReader.hasChunksAt overloads",
                    after = "LevelReaderCompat.hasChunksAt(LevelReader, BlockPos, BlockPos)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-levelreader-haschunksat-helper"
                ))
            }
        }
        return changes
    }

    private fun javaVariablesOfLevelReaderType(source: String): Set<String> {
        val id = """[A-Za-z_$][\w$]*"""
        val type = """(?:[A-Za-z_$][\w$]*\.)*(?:LevelReader|LevelAccessor|ServerLevelAccessor|Level|ServerLevel|ClientLevel)"""
        return Regex("""(?<![\w$])(?:final\s+)?$type\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
    }

    private fun isLevelReaderExpression(receiver: String, levelReaderVariables: Set<String>): Boolean {
        val normalized = receiver.trim()
        if (normalized in levelReaderVariables) return true
        return normalized == "level()" ||
            normalized == "this.level()" ||
            normalized.endsWith(".level()") ||
            normalized.endsWith(".getCommandSenderWorld()")
    }

    private fun generatedLevelReaderCompatSource(packageName: String): String =
        """
package $packageName;

import net.minecraft.core.BlockPos;
import net.minecraft.core.SectionPos;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.chunk.status.ChunkStatus;

public final class LevelReaderCompat {
    private LevelReaderCompat() {
    }

    public static boolean hasChunksAt(LevelReader level, BlockPos from, BlockPos to) {
        if (to.getY() < level.getMinBuildHeight() || from.getY() >= level.getMaxBuildHeight()) {
            return false;
        }
        int fromChunkX = SectionPos.blockToSectionCoord(from.getX());
        int toChunkX = SectionPos.blockToSectionCoord(to.getX());
        int fromChunkZ = SectionPos.blockToSectionCoord(from.getZ());
        int toChunkZ = SectionPos.blockToSectionCoord(to.getZ());
        for (int chunkX = fromChunkX; chunkX <= toChunkX; chunkX++) {
            for (int chunkZ = fromChunkZ; chunkZ <= toChunkZ; chunkZ++) {
                if (level.getChunk(chunkX, chunkZ, ChunkStatus.FULL, false) == null) {
                    return false;
                }
            }
        }
        return true;
    }
}
""".trimStart()

    private data class EntityRendererRegistration(
        val entityTypeKey: String,
        val rendererSimpleName: String,
        val rendererFqn: String
    )

    private data class EntityRendererMigrationResult(
        val source: String,
        val changed: Boolean,
        val requiredImports: Set<String>
    )

    private fun migrateXlintCleanApiBridges(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .filter { file ->
                !srcDir.relativize(file).toString().replace('\\', '/')
                    .startsWith("com/modporter/generated/")
            }
            .toList()
        if (javaFiles.isEmpty()) return emptyList()

        var compatPackageCache: String? = null
        fun compatPackage(): String {
            val existing = compatPackageCache
            if (existing != null) return existing
            val detected = detectRequiredGeneratedCompatPackage(projectDir, "Xlint-clean API bridge helpers")
            compatPackageCache = detected
            return detected
        }

        val types = collectJavaSourceTypes(javaFiles)
        val rendererRegistrations = collectEntityRendererRegistrations(types)
        val rendererTargets = collectConcreteEntityRendererTargets(types)
        val changes = mutableListOf<Change>()
        var needsDatagenCompat = false
        var needsDefaultAttributesCompat = false

        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            var migrated = original

            val rendererMigrated = migrateRendererMapCastsToConcreteRenderersSource(
                migrated,
                rendererRegistrations,
                rendererTargets
            )
            if (rendererMigrated.changed) {
                migrated = rendererMigrated.source
                rendererMigrated.requiredImports.forEach { importName ->
                    migrated = addExecutableImportIfMissing(migrated, importName)
                }
                migrated = removeUnusedSimpleImport(
                    migrated,
                    "net.minecraft.client.renderer.entity.EntityRenderer",
                    "EntityRenderer"
                )
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Replace unchecked EntityRenderDispatcher renderer-map cast with source-registered concrete renderer type",
                    before = "(EntityRenderer<T>) dispatcher.renderers.get(entityType)",
                    after = "(ConcreteRenderer) dispatcher.renderers.get(entityType)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-xlint-concrete-entity-renderer-cast"
                ))
            }

            val datagenMigrated = migrateDeprecatedDatagenCodecConstructorsSource(migrated) { compatPackage() }
            if (datagenMigrated.first != migrated) {
                migrated = datagenMigrated.first
                needsDatagenCompat = needsDatagenCompat || datagenMigrated.second
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Construct deprecated datagen-only placement and loot functions through their official codecs",
                    before = "deprecated 1.21 datagen builder calls",
                    after = "DatagenCompat codec-backed builders",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-xlint-datagen-codec-bridges"
                ))
            }

            val defaultAttributesMigrated = migrateDefaultAttributesSupplierCastsSource(migrated) { compatPackage() }
            if (defaultAttributesMigrated.first != migrated) {
                migrated = defaultAttributesMigrated.first
                needsDefaultAttributesCompat = needsDefaultAttributesCompat || defaultAttributesMigrated.second
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Replace unchecked DefaultAttributes.getSupplier EntityType cast with AT-backed helper",
                    before = "DefaultAttributes.getSupplier((EntityType<? extends LivingEntity>) type)",
                    after = "DefaultAttributesCompat.getSupplier(type)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-xlint-defaultattributes-helper"
                ))
            }

            if (migrated != original && !dryRun) {
                javaFile.writeText(migrated)
            }
        }

        if (needsDatagenCompat) {
            changes.addAll(ensureGeneratedCompatJavaSource(
                srcDir = srcDir,
                packageName = compatPackage(),
                className = "DatagenCompat",
                source = generatedDatagenCompatSource(compatPackage()),
                dryRun = dryRun,
                description = "Generate codec-backed datagen helper for deprecated 1.21 builders",
                before = "deprecated datagen builder APIs",
                after = "DatagenCompat",
                ruleId = "struct-xlint-datagen-codec-bridges"
            ))
        }
        if (needsDefaultAttributesCompat) {
            changes.addAll(ensureGeneratedCompatJavaSource(
                srcDir = srcDir,
                packageName = compatPackage(),
                className = "DefaultAttributesCompat",
                source = generatedDefaultAttributesCompatSource(compatPackage()),
                dryRun = dryRun,
                description = "Generate AT-backed DefaultAttributes supplier helper",
                before = "unchecked EntityType<? extends LivingEntity> cast",
                after = "DefaultAttributesCompat.getSupplier(EntityType<?>)",
                ruleId = "struct-xlint-defaultattributes-helper"
            ))
        }

        return changes
    }

    private fun ensureGeneratedCompatJavaSource(
        srcDir: Path,
        packageName: String,
        className: String,
        source: String,
        dryRun: Boolean,
        description: String,
        before: String,
        after: String,
        ruleId: String
    ): List<Change> {
        val helperFile = srcDir.resolve(packageName.replace('.', '/')).resolve("$className.java")
        val previous = if (helperFile.exists()) helperFile.readText() else null
        if (previous == source) return emptyList()
        if (!dryRun) {
            helperFile.parent.createDirectories()
            helperFile.writeText(source)
        }
        return listOf(Change(
            file = helperFile,
            line = 0,
            description = description,
            before = before,
            after = after,
            confidence = Confidence.HIGH,
            ruleId = ruleId
        ))
    }

    private fun collectEntityRendererRegistrations(types: List<JavaSourceType>): Map<String, EntityRendererRegistration> {
        val byEntityType = linkedMapOf<String, EntityRendererRegistration>()
        val typesBySimpleName = types.groupBy { it.className }
        types.forEach { type ->
            val imports = javaImportMap(type.source)
            val executableCode = maskJavaCommentsAndLiterals(type.source)
            var cursor = 0
            while (true) {
                val tokenIndex = executableCode.indexOf(".registerEntityRenderer(", cursor)
                if (tokenIndex < 0) break
                val openParen = tokenIndex + ".registerEntityRenderer".length
                val closeParen = findMatchingParen(executableCode, openParen)
                if (closeParen < 0) {
                    cursor = tokenIndex + ".registerEntityRenderer(".length
                    continue
                }
                val args = splitTopLevelJavaArgs(type.source.substring(openParen + 1, closeParen))
                if (args.size >= 2) {
                    val rendererRef = Regex("""^\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*::\s*new\s*$""")
                        .find(args[1])
                        ?.groupValues
                        ?.get(1)
                    val rendererFqn = rendererRef?.let {
                        resolveProjectJavaTypeReference(it, type.packageName, imports, typesBySimpleName)
                    }
                    if (rendererRef != null && rendererFqn != null) {
                        val registration = EntityRendererRegistration(
                            entityTypeKey = normalizedJavaExpressionKey(args[0]),
                            rendererSimpleName = rendererRef.substringAfterLast('.'),
                            rendererFqn = rendererFqn
                        )
                        byEntityType.putIfAbsent(registration.entityTypeKey, registration)
                    }
                }
                cursor = closeParen + 1
            }
        }
        return byEntityType
    }

    private fun collectConcreteEntityRendererTargets(types: List<JavaSourceType>): Map<String, String> {
        val targets = linkedMapOf<String, String>()
        val knownRendererBases = setOf(
            "EntityRenderer",
            "LivingEntityRenderer",
            "MobRenderer",
            "AgeableMobRenderer",
            "HumanoidMobRenderer"
        )
        types.forEach { type ->
            val executableCode = maskJavaCommentsAndLiterals(type.source)
            val classMatch = Regex(
                """(?m)\bclass\s+${Regex.escape(type.className)}(?:\s*<[^>{}]+>)?\s+extends\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*<\s*([^,>]+)"""
            ).find(executableCode) ?: return@forEach
            val superSimpleName = classMatch.groupValues[1].substringAfterLast('.')
            if (superSimpleName !in knownRendererBases) return@forEach
            targets[type.fqn] = normalizedJavaTypeKey(classMatch.groupValues[2])
        }
        return targets
    }

    private fun migrateRendererMapCastsToConcreteRenderersSource(
        source: String,
        registrations: Map<String, EntityRendererRegistration>,
        rendererTargets: Map<String, String>
    ): EntityRendererMigrationResult {
        if (registrations.isEmpty() || !source.contains("renderers.get(") || !source.contains("EntityRenderer<")) {
            return EntityRendererMigrationResult(source, changed = false, requiredImports = emptySet())
        }
        val packageName = packageNameOf(source)
        val executableCode = maskJavaCommentsAndLiterals(source)
        val id = """[A-Za-z_$][\w$]*"""
        val declarationPattern = Regex(
            """(?m)^([ \t]*)(final\s+)?(?:net\.minecraft\.client\.renderer\.entity\.)?EntityRenderer\s*<\s*([^>\r\n;]+?)\s*>\s+($id)\s*=\s*\(\s*(?:net\.minecraft\.client\.renderer\.entity\.)?EntityRenderer\s*<\s*([^>\r\n;]+?)\s*>\s*\)\s*"""
        )
        val edits = mutableListOf<Pair<IntRange, String>>()
        val imports = linkedSetOf<String>()
        for (match in declarationPattern.findAll(executableCode)) {
            val expressionStart = match.range.last + 1
            val semicolon = findJavaStatementSemicolon(executableCode, expressionStart)
            if (semicolon < 0) continue
            val renderersGetIndex = executableCode.indexOf(".renderers.get(", expressionStart)
                .takeIf { it >= 0 && it < semicolon }
                ?: continue
            val openParen = renderersGetIndex + ".renderers.get".length
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0 || closeParen > semicolon) continue
            val entityTypeKey = normalizedJavaExpressionKey(source.substring(openParen + 1, closeParen))
            val registration = registrations[entityTypeKey] ?: continue
            val expectedTarget = normalizedJavaTypeKey(match.groupValues[3])
            val castTarget = normalizedJavaTypeKey(match.groupValues[5])
            if (expectedTarget != castTarget) continue
            val rendererTarget = rendererTargets[registration.rendererFqn] ?: continue
            if (rendererTarget != expectedTarget) continue

            val rendererPackage = registration.rendererFqn.substringBeforeLast('.', "")
            val rendererReference = registration.rendererSimpleName
            if (rendererPackage.isNotBlank() && rendererPackage != packageName) {
                imports += registration.rendererFqn
            }
            val expression = source.substring(expressionStart, semicolon).trim()
            val replacement = buildString {
                append(match.groupValues[1])
                append(match.groupValues[2])
                append(rendererReference)
                append(' ')
                append(match.groupValues[4])
                append(" = (")
                append(rendererReference)
                append(") ")
                append(expression)
                append(';')
            }
            edits += match.range.first..semicolon to replacement
        }
        if (edits.isEmpty()) return EntityRendererMigrationResult(source, changed = false, requiredImports = emptySet())
        var result = source
        for ((range, replacement) in edits.asReversed()) {
            result = result.substring(0, range.first) + replacement + result.substring(range.last + 1)
        }
        return EntityRendererMigrationResult(result, changed = true, requiredImports = imports)
    }

    private fun migrateDeprecatedDatagenCodecConstructorsSource(
        source: String,
        generatedCompatPackage: () -> String
    ): Pair<String, Boolean> {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("CopyCustomDataFunction.copyData(") &&
            !executableCode.contains("SetCustomDataFunction.setCustomData(") &&
            !executableCode.contains("CountOnEveryLayerPlacement.of(")) {
            return source to false
        }

        var result = source
        var helperNeeded = false
        val copyDataMigrated = migrateCopyCustomDataBuilderChains(result)
        result = copyDataMigrated.first
        helperNeeded = helperNeeded || copyDataMigrated.second
        val countOnEveryLayerMigrated = migrateCountOnEveryLayerPlacementCalls(result)
        result = countOnEveryLayerMigrated.first
        helperNeeded = helperNeeded || countOnEveryLayerMigrated.second
        result = rewriteExecutableJavaCall(result, "copy") { receiver, args ->
            if (args.size != 3 || !isBlockEntityCopyCustomDataBuilder(receiver)) return@rewriteExecutableJavaCall null
            val strategy = copyCustomDataMergeStrategyName(args[2]) ?: return@rewriteExecutableJavaCall null
            helperNeeded = true
            "DatagenCompat.copyBlockEntityCustomData(${args[0].trim()}, ${args[1].trim()}, \"$strategy\")"
        }
        result = rewriteExecutableJavaCall(result, "setCustomData") { receiver, args ->
            if (args.size != 1 || !receiver.trim().endsWith("SetCustomDataFunction")) return@rewriteExecutableJavaCall null
            helperNeeded = true
            "DatagenCompat.setCustomData(${args[0].trim()})"
        }
        result = rewriteExecutableJavaCall(result, "of") { receiver, args ->
            if (args.size != 1 || !receiver.trim().endsWith("CountOnEveryLayerPlacement")) return@rewriteExecutableJavaCall null
            helperNeeded = true
            "DatagenCompat.countOnEveryLayer(${args[0].trim()})"
        }

        if (!helperNeeded) return source to false
        result = addExecutableImportIfMissing(result, "${generatedCompatPackage()}.DatagenCompat")
        result = removeUnusedSimpleImport(
            result,
            "net.minecraft.world.level.storage.loot.providers.nbt.ContextNbtProvider",
            "ContextNbtProvider"
        )
        result = removeUnusedSimpleImport(
            result,
            "net.minecraft.world.level.storage.loot.functions.CopyCustomDataFunction",
            "CopyCustomDataFunction"
        )
        result = removeUnusedSimpleImport(
            result,
            "net.minecraft.world.level.storage.loot.functions.SetCustomDataFunction",
            "SetCustomDataFunction"
        )
        result = removeUnusedSimpleImport(
            result,
            "net.minecraft.world.level.levelgen.placement.CountOnEveryLayerPlacement",
            "CountOnEveryLayerPlacement"
        )
        return result to true
    }

    private fun migrateCopyCustomDataBuilderChains(source: String): Pair<String, Boolean> {
        var result = source
        var changed = false
        var cursor = 0
        val tokens = listOf(
            "CopyCustomDataFunction.copyData(",
            "net.minecraft.world.level.storage.loot.functions.CopyCustomDataFunction.copyData("
        )
        while (cursor < result.length) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val tokenMatch = tokens.mapNotNull { token ->
                val index = executableCode.indexOf(token, cursor)
                if (index >= 0) index to token else null
            }.minByOrNull { it.first } ?: break
            val tokenIndex = tokenMatch.first
            val token = tokenMatch.second
            val copyDataOpen = tokenIndex + token.removeSuffix("(").length
            val copyDataClose = findMatchingParen(executableCode, copyDataOpen)
            if (copyDataClose < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val providerArgs = splitTopLevelJavaArgs(result.substring(copyDataOpen + 1, copyDataClose))
            if (providerArgs.size != 1 ||
                providerArgs[0].trim() !in setOf(
                    "ContextNbtProvider.BLOCK_ENTITY",
                    "net.minecraft.world.level.storage.loot.providers.nbt.ContextNbtProvider.BLOCK_ENTITY"
                )) {
                cursor = copyDataClose + 1
                continue
            }
            var copyTokenIndex = copyDataClose + 1
            while (copyTokenIndex < executableCode.length && executableCode[copyTokenIndex].isWhitespace()) copyTokenIndex++
            if (!executableCode.startsWith(".copy(", copyTokenIndex)) {
                cursor = copyDataClose + 1
                continue
            }
            val copyOpen = copyTokenIndex + ".copy".length
            val copyClose = findMatchingParen(executableCode, copyOpen)
            if (copyClose < 0) {
                cursor = copyTokenIndex + ".copy(".length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(copyOpen + 1, copyClose))
            if (args.size != 3) {
                cursor = copyClose + 1
                continue
            }
            val strategy = copyCustomDataMergeStrategyName(args[2])
            if (strategy == null) {
                cursor = copyClose + 1
                continue
            }
            val replacement = "DatagenCompat.copyBlockEntityCustomData(${args[0].trim()}, ${args[1].trim()}, \"$strategy\")"
            result = result.substring(0, tokenIndex) + replacement + result.substring(copyClose + 1)
            cursor = tokenIndex + replacement.length
            changed = true
        }
        return result to changed
    }

    private fun migrateCountOnEveryLayerPlacementCalls(source: String): Pair<String, Boolean> {
        var result = source
        var changed = false
        var cursor = 0
        val tokens = listOf(
            "CountOnEveryLayerPlacement.of(",
            "net.minecraft.world.level.levelgen.placement.CountOnEveryLayerPlacement.of("
        )
        while (cursor < result.length) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val tokenMatch = tokens.mapNotNull { token ->
                val index = executableCode.indexOf(token, cursor)
                if (index >= 0) index to token else null
            }.minByOrNull { it.first } ?: break
            val tokenIndex = tokenMatch.first
            val token = tokenMatch.second
            val openParen = tokenIndex + token.removeSuffix("(").length
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 1) {
                cursor = closeParen + 1
                continue
            }
            val replacement = "DatagenCompat.countOnEveryLayer(${args[0].trim()})"
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
            changed = true
        }
        return result to changed
    }

    private fun isBlockEntityCopyCustomDataBuilder(receiver: String): Boolean {
        val trimmed = receiver.trim()
        if (!trimmed.startsWith("CopyCustomDataFunction.copyData(") &&
            !trimmed.startsWith("net.minecraft.world.level.storage.loot.functions.CopyCustomDataFunction.copyData(")) {
            return false
        }
        val openParen = trimmed.indexOf("copyData(").takeIf { it >= 0 }?.let { it + "copyData".length } ?: return false
        val closeParen = findMatchingParen(trimmed, openParen)
        if (closeParen < 0 || trimmed.substring(closeParen + 1).isNotBlank()) return false
        val args = splitTopLevelJavaArgs(trimmed.substring(openParen + 1, closeParen))
        if (args.size != 1) return false
        val sourceProvider = args[0].trim()
        return sourceProvider == "ContextNbtProvider.BLOCK_ENTITY" ||
            sourceProvider == "net.minecraft.world.level.storage.loot.providers.nbt.ContextNbtProvider.BLOCK_ENTITY"
    }

    private fun copyCustomDataMergeStrategyName(argument: String): String? {
        val trimmed = argument.trim()
        val match = Regex("""^(?:net\.minecraft\.world\.level\.storage\.loot\.functions\.)?CopyCustomDataFunction\.MergeStrategy\.([A-Z_]+)$""")
            .find(trimmed)
            ?: return null
        return match.groupValues[1].lowercase()
    }

    private fun migrateDefaultAttributesSupplierCastsSource(
        source: String,
        generatedCompatPackage: () -> String
    ): Pair<String, Boolean> {
        if (!source.contains("DefaultAttributes.getSupplier(")) return source to false
        var helperNeeded = false
        var result = rewriteExecutableJavaCall(source, "getSupplier") { receiver, args ->
            if (args.size != 1 || !receiver.trim().endsWith("DefaultAttributes")) return@rewriteExecutableJavaCall null
            val entityTypeExpression = entityTypeExtendsLivingEntityCastArgument(args[0])
                ?: return@rewriteExecutableJavaCall null
            helperNeeded = true
            "DefaultAttributesCompat.getSupplier($entityTypeExpression)"
        }
        if (!helperNeeded) return source to false
        result = addExecutableImportIfMissing(result, "${generatedCompatPackage()}.DefaultAttributesCompat")
        result = removeUnusedSimpleImport(
            result,
            "net.minecraft.world.entity.ai.attributes.DefaultAttributes",
            "DefaultAttributes"
        )
        return result to true
    }

    private fun entityTypeExtendsLivingEntityCastArgument(argument: String): String? =
        Regex(
            """^\s*\(\s*(?:net\.minecraft\.world\.entity\.)?EntityType\s*<\s*\?\s+extends\s+(?:net\.minecraft\.world\.entity\.)?LivingEntity\s*>\s*\)\s*(.+?)\s*$""",
            RegexOption.DOT_MATCHES_ALL
        ).find(argument)
            ?.groupValues
            ?.get(1)
            ?.trim()

    private fun generatedDatagenCompatSource(packageName: String): String =
        """
package $packageName;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.mojang.serialization.JsonOps;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.levelgen.placement.PlacementModifier;
import net.minecraft.world.level.storage.loot.functions.LootItemFunction;
import net.minecraft.world.level.storage.loot.functions.LootItemFunctions;

public final class DatagenCompat {
    private DatagenCompat() {
    }

    public static PlacementModifier countOnEveryLayer(int count) {
        JsonObject json = new JsonObject();
        json.addProperty("type", "minecraft:count_on_every_layer");
        json.addProperty("count", count);
        return PlacementModifier.CODEC.parse(JsonOps.INSTANCE, json).getOrThrow();
    }

    public static LootItemFunction.Builder copyBlockEntityCustomData(String sourcePath, String targetPath, String mergeStrategy) {
        return () -> {
            JsonObject operation = new JsonObject();
            operation.addProperty("source", sourcePath);
            operation.addProperty("target", targetPath);
            operation.addProperty("op", mergeStrategy);
            JsonArray operations = new JsonArray();
            operations.add(operation);
            JsonObject json = new JsonObject();
            json.addProperty("function", "minecraft:copy_custom_data");
            json.addProperty("source", "block_entity");
            json.add("ops", operations);
            return LootItemFunctions.TYPED_CODEC.parse(JsonOps.INSTANCE, json).getOrThrow();
        };
    }

    public static LootItemFunction.Builder setCustomData(CompoundTag tag) {
        return () -> {
            JsonObject json = new JsonObject();
            json.addProperty("function", "minecraft:set_custom_data");
            json.addProperty("tag", tag.toString());
            return LootItemFunctions.TYPED_CODEC.parse(JsonOps.INSTANCE, json).getOrThrow();
        };
    }
}
""".trimStart()

    private fun generatedDefaultAttributesCompatSource(packageName: String): String =
        """
package $packageName;

import java.util.Map;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.DefaultAttributes;
import net.neoforged.neoforge.common.CommonHooks;

public final class DefaultAttributesCompat {
    private DefaultAttributesCompat() {
    }

    public static AttributeSupplier getSupplier(EntityType<?> entityType) {
        AttributeSupplier supplier = forgeAttributes().get(entityType);
        return supplier != null ? supplier : DefaultAttributes.SUPPLIERS.get(entityType);
    }

    @Deprecated
    private static Map<EntityType<? extends LivingEntity>, AttributeSupplier> forgeAttributes() {
        return CommonHooks.getAttributesView();
    }
}
""".trimStart()

    private fun javaImportMap(source: String): Map<String, String> {
        val imports = linkedMapOf<String, String>()
        Regex("""(?m)^[ \t]*import\s+(?!static\b)([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*;""")
            .findAll(maskJavaCommentsAndLiterals(source))
            .forEach { match ->
                val fqn = match.groupValues[1]
                imports[fqn.substringAfterLast('.')] = fqn
            }
        return imports
    }

    private fun resolveProjectJavaTypeReference(
        reference: String,
        packageName: String,
        imports: Map<String, String>,
        typesBySimpleName: Map<String, List<JavaSourceType>>
    ): String? {
        val trimmed = reference.trim()
        if (trimmed.isBlank()) return null
        if (trimmed.contains('.')) {
            val firstSegment = trimmed.substringBefore('.')
            imports[firstSegment]?.let { imported ->
                return imported + "." + trimmed.substringAfter('.')
            }
            if (firstSegment.firstOrNull()?.isLowerCase() == true) return trimmed
            val samePackage = if (packageName.isBlank()) trimmed else "$packageName.$trimmed"
            if (typesBySimpleName[trimmed.substringAfterLast('.')]?.any { it.fqn == samePackage } == true) {
                return samePackage
            }
            return null
        }
        imports[trimmed]?.let { return it }
        val samePackage = if (packageName.isBlank()) trimmed else "$packageName.$trimmed"
        if (typesBySimpleName[trimmed]?.any { it.fqn == samePackage } == true) return samePackage
        return typesBySimpleName[trimmed]?.singleOrNull()?.fqn
    }

    private fun normalizedJavaExpressionKey(expression: String): String =
        expression.replace(Regex("""\s+"""), "")

    private fun normalizedJavaTypeKey(type: String): String =
        type.trim()
            .removePrefix("? extends ")
            .removePrefix("? super ")
            .substringBefore('<')
            .substringAfterLast('.')
            .replace(Regex("""\s+"""), "")

    private fun migrateDeprecatedStructureGenerationHelpers(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("getLowestYIn5by5BoxOffset7Blocks(") &&
            !executableCode.contains(".moveInsideHeights(")) {
            return source
        }
        var result = source
        var needsLowestHelper = false
        var needsMoveInsideHelper = false
        if (maskJavaCommentsAndLiterals(result).contains("getLowestYIn5by5BoxOffset7Blocks(")) {
            result = rewriteExecutableJavaCall(result, "getLowestYIn5by5BoxOffset7Blocks") { receiver, args ->
                if (args.size != 2 || receiver.trim() !in setOf("this", "super")) {
                    return@rewriteExecutableJavaCall null
                }
                needsLowestHelper = true
                "modporter${'$'}getLowestYIn5by5BoxOffset7Blocks(${args[0].trim()}, ${args[1].trim()})"
            }
        }
        if (maskJavaCommentsAndLiterals(result).contains(".moveInsideHeights(")) {
            val builderVariables = javaVariablesOfType(maskJavaCommentsAndLiterals(result), "StructurePiecesBuilder")
            result = rewriteExecutableJavaCall(result, "moveInsideHeights") { receiver, args ->
                if (args.size != 3 || receiver.trim() !in builderVariables) {
                    return@rewriteExecutableJavaCall null
                }
                needsMoveInsideHelper = true
                "modporter${'$'}moveInsideHeights(${receiver.trim()}, ${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()})"
            }
        }
        if (needsLowestHelper && !maskJavaCommentsAndLiterals(result).contains("modporter${'$'}getLowestYIn5by5BoxOffset7Blocks(Structure.GenerationContext")) {
            result = insertBeforeLastClassBrace(result, generatedLowestYIn5By5Helper())
            result = addExecutableImportIfMissing(result, "net.minecraft.world.level.ChunkPos")
        }
        if (needsMoveInsideHelper && !maskJavaCommentsAndLiterals(result).contains("modporter${'$'}moveInsideHeights(StructurePiecesBuilder")) {
            result = insertBeforeLastClassBrace(result, generatedMoveInsideHeightsHelper())
            result = addExecutableImportIfMissing(result, "net.minecraft.util.RandomSource")
            result = addExecutableImportIfMissing(result, "net.minecraft.world.level.levelgen.structure.BoundingBox")
            result = addExecutableImportIfMissing(result, "net.minecraft.world.level.levelgen.structure.StructurePiece")
            result = addExecutableImportIfMissing(result, "net.minecraft.world.level.levelgen.structure.pieces.StructurePiecesBuilder")
        }
        return result
    }

    private fun generatedLowestYIn5By5Helper(): String =
        """

    private static BlockPos modporter${'$'}getLowestYIn5by5BoxOffset7Blocks(Structure.GenerationContext context, Rotation rotation) {
        int xOffset = 5;
        int zOffset = 5;
        if (rotation == Rotation.CLOCKWISE_90) {
            xOffset = -5;
        } else if (rotation == Rotation.CLOCKWISE_180) {
            xOffset = -5;
            zOffset = -5;
        } else if (rotation == Rotation.COUNTERCLOCKWISE_90) {
            zOffset = -5;
        }

        ChunkPos chunkPos = context.chunkPos();
        int x = chunkPos.getBlockX(7);
        int z = chunkPos.getBlockZ(7);
        return new BlockPos(x, getLowestY(context, x, z, xOffset, zOffset), z);
    }
""".trimEnd()

    private fun generatedMoveInsideHeightsHelper(): String =
        """

    private static void modporter${'$'}moveInsideHeights(StructurePiecesBuilder builder, RandomSource random, int minY, int maxY) {
        BoundingBox boundingBox = builder.getBoundingBox();
        int availableHeight = maxY - minY + 1 - boundingBox.getYSpan();
        int targetY;
        if (availableHeight > 1) {
            targetY = minY + random.nextInt(availableHeight);
        } else {
            targetY = minY;
        }

        int offset = targetY - boundingBox.minY();
        for (StructurePiece piece : builder.build().pieces()) {
            piece.move(0, offset, 0);
        }
    }
""".trimEnd()

    private fun migrateDeprecatedRenderSystemRunAsFancy(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".runAsFancy(")) return source
        var needsHelper = false
        var result = rewriteExecutableJavaCall(source, "runAsFancy") { receiver, args ->
            val target = receiver.trim()
            if (args.size != 1 ||
                target != "RenderSystem" &&
                target != "com.mojang.blaze3d.systems.RenderSystem") {
                return@rewriteExecutableJavaCall null
            }
            needsHelper = true
            "modporter${'$'}runAsFancy(${args[0].trim()})"
        }
        if (!needsHelper) return source
        if (!maskJavaCommentsAndLiterals(result).contains("modporter${'$'}runAsFancy(Runnable")) {
            result = insertBeforeLastClassBrace(result, generatedRunAsFancyHelper())
        }
        result = addExecutableImportIfMissing(result, "net.minecraft.client.GraphicsStatus")
        result = addExecutableImportIfMissing(result, "net.minecraft.client.Minecraft")
        result = addExecutableImportIfMissing(result, "net.minecraft.client.OptionInstance")
        result = removeSimpleImportIfUnused(result, "com.mojang.blaze3d.systems.RenderSystem", "RenderSystem")
        return result
    }

    private fun generatedRunAsFancyHelper(): String =
        """

    private static void modporter${'$'}runAsFancy(Runnable fancyRunnable) {
        boolean shaderTransparency = Minecraft.useShaderTransparency();
        if (!shaderTransparency) {
            fancyRunnable.run();
        } else {
            OptionInstance<GraphicsStatus> graphicsMode = Minecraft.getInstance().options.graphicsMode();
            GraphicsStatus previousGraphicsStatus = graphicsMode.get();
            graphicsMode.set(GraphicsStatus.FANCY);
            fancyRunnable.run();
            graphicsMode.set(previousGraphicsStatus);
        }
    }
""".trimEnd()

    private fun markRequiredDeprecatedOverrides(source: String): String {
        var result = markFinalizeSpawnRequiredDeprecatedOverride(source)
        val executableCode = maskJavaCommentsAndLiterals(result)
        if (!executableCode.contains("@Override") ||
            !executableCode.contains("getParticleIcon(") &&
            !executableCode.contains("getTransforms(") &&
            !executableCode.contains("finalizeSpawn(")) {
            return result
        }
        val insertions = mutableListOf<Pair<Int, String>>()
        for (method in javaMethodRangesIncludingDefault(executableCode)) {
            if (Regex("""(?m)^[ \t]*@(?:java\.lang\.)?Deprecated\b""").containsMatchIn(method.header)) {
                continue
            }
            val requiredDeprecatedOverride = when (method.name) {
                "getParticleIcon" -> method.header.contains("@Override") && method.header.contains("TextureAtlasSprite") && method.header.contains("()")
                "getTransforms" -> method.header.contains("@Override") && method.header.contains("ItemTransforms") && method.header.contains("()")
                "finalizeSpawn" -> method.header.contains("SpawnGroupData") &&
                    method.header.contains("ServerLevelAccessor") &&
                    method.header.contains("DifficultyInstance") &&
                    method.header.contains("MobSpawnType")
                else -> false
            }
            if (!requiredDeprecatedOverride) continue
            val methodText = result.substring(method.range)
            val insertionMatch = Regex("""(?m)^([ \t]*)@Override\b""").find(methodText)
                ?: Regex("""(?m)^([ \t]*)(?:public|protected|private)\s+""").find(methodText)
                ?: continue
            val indent = insertionMatch.groupValues[1]
            insertions += method.range.first + insertionMatch.range.first to "${indent}@Deprecated\n"
        }
        if (insertions.isEmpty()) return result
        insertions.sortedByDescending { it.first }.forEach { (offset, text) ->
            result = result.substring(0, offset) + text + result.substring(offset)
        }
        return result
    }

    private fun markFinalizeSpawnRequiredDeprecatedOverride(source: String): String {
        if (!source.contains("finalizeSpawn(") ||
            !source.contains("ServerLevelAccessor") ||
            !source.contains("DifficultyInstance") ||
            !source.contains("MobSpawnType") ||
            !source.contains("SpawnGroupData")) {
            return source
        }
        val pattern = Regex(
            """(?m)^([ \t]*)((?:@[A-Za-z_$][\w$.]*(?:\([^)]*\))?\s*\r?\n\1)*)(public\s+SpawnGroupData\s+finalizeSpawn\s*\([^{};]*ServerLevelAccessor[^{};]*DifficultyInstance[^{};]*MobSpawnType[^{};]*SpawnGroupData[^{};]*\)\s*\{)"""
        )
        return pattern.replace(source) { match ->
            val annotations = match.groupValues[2]
            if (Regex("""(?m)^[ \t]*@(?:java\.lang\.)?Deprecated\b""").containsMatchIn(annotations)) {
                match.value
            } else {
                "${match.groupValues[1]}${annotations}${match.groupValues[1]}@Deprecated\n${match.groupValues[1]}${match.groupValues[3]}"
            }
        }
    }

    private data class ClientColorAliasDeclaration(val alias: String, val range: IntRange)
    private data class ClientColorRegistrationStatement(val range: IntRange, val replacement: String)
    private data class ClientColorMigration(
        val source: String,
        val blockRegistrations: List<String>,
        val itemRegistrations: List<String>,
        val firstEditOffset: Int
    )

    private fun migrateDeprecatedClientColorRegistrations(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val mainFile = detectModMainClass(projectDir) ?: return emptyList()
        var mainText = mainFile.readText()
        val modBusVar = detectModBusVariable(mainText) ?: return emptyList()
        val mainPackage = packageNameOf(mainText)
        val changes = mutableListOf<Change>()

        fun methodFor(methodName: String, eventType: String, registrations: List<String>): String =
            """

    public static void $methodName($eventType event) {
${registrations.joinToString("\n") { "        $it" }}
    }
""".trimEnd()

        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .filter { it != mainFile }
            .toList()
            .forEach { javaFile ->
                val original = javaFile.readText()
                val executableCode = maskJavaCommentsAndLiterals(original)
                if (!executableCode.contains(".register(") ||
                    !executableCode.contains("getBlockColors()") &&
                    !executableCode.contains("getItemColors()")) {
                    return@forEach
                }
                if (executableCode.contains("RegisterColorHandlersEvent.Block") ||
                    executableCode.contains("RegisterColorHandlersEvent.Item")) {
                    return@forEach
                }

                val ownerName = classNameOfJavaSource(executableCode) ?: return@forEach
                val owner = javaTypeBlocks(original, executableCode).firstOrNull { it.name == ownerName } ?: return@forEach
                val sourcePackage = packageNameOf(original)
                val listenerClassName = javaListenerTypeReferenceExpression(sourcePackage, mainPackage, owner) ?: return@forEach
                val migration = migrateDeprecatedClientColorRegistrationSource(original) ?: return@forEach

                var migrated = migration.source
                if (migration.blockRegistrations.isNotEmpty()) {
                    migrated = insertBeforeLastClassBrace(
                        migrated,
                        methodFor(
                            "registerBlockColors",
                            "RegisterColorHandlersEvent.Block",
                            migration.blockRegistrations
                        )
                    )
                }
                if (migration.itemRegistrations.isNotEmpty()) {
                    migrated = insertBeforeLastClassBrace(
                        migrated,
                        methodFor(
                            "registerItemColors",
                            "RegisterColorHandlersEvent.Item",
                            migration.itemRegistrations
                        )
                    )
                }
                migrated = addExecutableImportIfMissing(migrated, "net.neoforged.neoforge.client.event.RegisterColorHandlersEvent")
                migrated = removeSimpleImportIfUnused(migrated, "net.minecraft.client.color.block.BlockColors", "BlockColors")
                migrated = removeSimpleImportIfUnused(migrated, "net.minecraft.client.color.item.ItemColors", "ItemColors")
                migrated = removeSimpleImportIfUnused(migrated, "net.minecraft.client.Minecraft", "Minecraft")

                var mainChanged = false
                listOf(
                    "registerBlockColors" to migration.blockRegistrations,
                    "registerItemColors" to migration.itemRegistrations
                ).forEach { (methodName, registrations) ->
                    if (registrations.isEmpty()) return@forEach
                    val listener = "$modBusVar.addListener($listenerClassName::$methodName);"
                    if (!mainText.contains(listener)) {
                        val indent = mainConstructorIndent(mainText, modBusVar)
                        val registration = "${indent}if (net.neoforged.fml.loading.FMLLoader.getDist() == net.neoforged.api.distmarker.Dist.CLIENT) {\n" +
                            "$indent    $listener\n" +
                            "$indent}"
                        mainText = insertModBusListener(mainText, modBusVar, registration, owner.name)
                        mainChanged = true
                    }
                }

                changes.add(Change(
                    file = javaFile,
                    line = lineNumberAt(original, migration.firstEditOffset),
                    description = "Migrate deprecated client color registrations to RegisterColorHandlersEvent",
                    before = "Minecraft.getInstance().getBlockColors()/getItemColors().register(...)",
                    after = "RegisterColorHandlersEvent.Block/Item event.register(...)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-client-color-handler-events"
                ))
                if (mainChanged) {
                    changes.add(Change(
                        file = mainFile,
                        line = 1,
                        description = "Register migrated client color handlers on the mod event bus",
                        before = "direct color registration during another client setup event",
                        after = "mod event bus listeners for RegisterColorHandlersEvent",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-client-color-handler-events"
                    ))
                }
                if (!dryRun) {
                    javaFile.writeText(migrated)
                }
            }

        if (!dryRun && mainText != mainFile.readText()) {
            mainFile.writeText(mainText)
        }

        return changes
    }

    private fun migrateDeprecatedClientColorRegistrationSource(source: String): ClientColorMigration? {
        val executableCode = maskJavaCommentsAndLiterals(source)
        val id = """[A-Za-z_$][\w$]*"""
        fun aliases(typeName: String, methodName: String): List<ClientColorAliasDeclaration> =
            Regex(
                """(?m)^[ \t]*(?:final[ \t]+)?(?:${Regex.escape(typeName)}|${Regex.escape(typeName.substringAfterLast('.'))})[ \t]+($id)[ \t]*=[ \t]*(?:net\.minecraft\.client\.)?Minecraft\.getInstance[ \t]*\([ \t]*\)[ \t]*\.[ \t]*${Regex.escape(methodName)}[ \t]*\([ \t]*\)[ \t]*;[ \t]*(?:\r?\n)?"""
            ).findAll(executableCode)
                .map { ClientColorAliasDeclaration(it.groupValues[1], it.range) }
                .toList()

        fun statementEnd(openParen: Int): Int {
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) return -1
            var cursor = closeParen + 1
            while (cursor < executableCode.length && executableCode[cursor].isWhitespace()) cursor++
            return if (cursor < executableCode.length && executableCode[cursor] == ';') cursor else -1
        }

        fun statementRange(callStart: Int, semicolon: Int): IntRange {
            val start = source.lastIndexOf('\n', callStart).let { if (it < 0) 0 else it + 1 }
            var end = semicolon
            if (end + 1 < source.length && source[end + 1] == '\r') end++
            if (end + 1 < source.length && source[end + 1] == '\n') end++
            return start..end
        }

        fun collect(aliasDeclarations: List<ClientColorAliasDeclaration>): List<ClientColorRegistrationStatement> {
            val statements = mutableListOf<ClientColorRegistrationStatement>()
            aliasDeclarations.forEach { declaration ->
                var cursor = 0
                while (cursor < executableCode.length) {
                    val token = "${declaration.alias}.register"
                    val callStart = executableCode.indexOf(token, cursor)
                    if (callStart < 0) break
                    val openParen = executableCode.indexOf('(', callStart + token.length)
                    if (openParen < 0) break
                    val semicolon = statementEnd(openParen)
                    if (semicolon < 0) {
                        cursor = openParen + 1
                        continue
                    }
                    val closeParen = findMatchingParen(executableCode, openParen)
                    val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
                    if (args.size >= 2) {
                        statements += ClientColorRegistrationStatement(
                            statementRange(callStart, semicolon),
                            "event.register(${args.joinToString(", ") { it.trim() }});"
                        )
                    }
                    cursor = semicolon + 1
                }
            }
            return statements
        }

        val blockAliases = aliases("net.minecraft.client.color.block.BlockColors", "getBlockColors")
        val itemAliases = aliases("net.minecraft.client.color.item.ItemColors", "getItemColors")
        val blockStatements = collect(blockAliases)
        val itemStatements = collect(itemAliases)
        val allStatements = blockStatements + itemStatements
        if (allStatements.isEmpty()) return null

        fun rangeContains(range: IntRange, offset: Int): Boolean = offset >= range.first && offset <= range.last
        fun aliasOnlyUsedInRemovedStatements(declaration: ClientColorAliasDeclaration): Boolean =
            Regex("""\b${Regex.escape(declaration.alias)}\b""").findAll(executableCode).all { match ->
                rangeContains(declaration.range, match.range.first) ||
                    allStatements.any { rangeContains(it.range, match.range.first) }
            }

        val edits = mutableListOf<Pair<IntRange, String>>()
        allStatements.forEach { edits += it.range to "" }
        (blockAliases + itemAliases)
            .filter(::aliasOnlyUsedInRemovedStatements)
            .forEach { edits += it.range to "" }

        val migrated = applyStringEdits(source, edits)
        return ClientColorMigration(
            source = migrated,
            blockRegistrations = blockStatements.map { it.replacement },
            itemRegistrations = itemStatements.map { it.replacement },
            firstEditOffset = edits.minOf { it.first.first }
        )
    }

    private fun removeSimpleImportIfUnused(source: String, importName: String, simpleName: String): String {
        val without = removeExecutableImport(source, importName)
        return if (!hasSimpleTypeReference(maskJavaCommentsAndLiterals(without), simpleName)) without else source
    }

    private data class RenderLayerCall(
        val range: IntRange,
        val ownerName: String?,
        val fieldName: String,
        val renderType: String?,
        val allowedRenderTypes: Set<String>
    )

    private data class RenderLayerModelMigration(val element: JsonObject, val changed: Boolean)

    private fun migrateDeprecatedRenderLayerRegistrations(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val blockIds = collectRegisteredBlockIds(javaFiles)
        if (blockIds.isEmpty()) return emptyList()
        val resourceRoots = listOf(
            projectDir.resolve("src/main/resources"),
            projectDir.resolve("src/generated/resources")
        ).filter { it.exists() }
        if (resourceRoots.isEmpty()) return emptyList()

        val changes = mutableListOf<Change>()
        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            if (!original.contains("ItemBlockRenderTypes.setRenderLayer")) return@forEach
            val calls = collectDirectRenderLayerCalls(original)
            if (calls.isEmpty()) return@forEach

            val removable = mutableListOf<RenderLayerCall>()
            calls.forEach { call ->
                val blockId = resolveRegisteredBlockId(blockIds, call.ownerName, call.fieldName) ?: return@forEach
                val modelFiles = modelFilesForBlockResource(resourceRoots, blockId)
                if (modelFiles.isEmpty()) return@forEach
                if (!ensureModelRenderTypes(modelFiles, call.renderType, call.allowedRenderTypes, dryRun, changes)) return@forEach
                removable += call
            }

            if (removable.isEmpty()) return@forEach
            var migrated = applyStringEdits(original, removable.map { it.range to "" })
            migrated = removeSimpleImportIfUnused(migrated, "net.minecraft.client.renderer.ItemBlockRenderTypes", "ItemBlockRenderTypes")
            migrated = removeSimpleImportIfUnused(migrated, "net.minecraft.client.renderer.RenderType", "RenderType")
            changes.add(Change(
                file = javaFile,
                line = lineNumberAt(original, removable.minOf { it.range.first }),
                description = "Migrate deprecated block render-layer calls to model render_type resources",
                before = "ItemBlockRenderTypes.setRenderLayer(block, RenderType.*())",
                after = "block model JSON render_type",
                confidence = Confidence.HIGH,
                ruleId = "struct-render-layer-model-render-type"
            ))
            if (!dryRun) {
                javaFile.writeText(migrated)
            }
        }
        return changes
    }

    private fun collectDirectRenderLayerCalls(source: String): List<RenderLayerCall> {
        val executableCode = maskJavaCommentsAndLiterals(source)
        val calls = mutableListOf<RenderLayerCall>()
        var cursor = 0
        val token = "ItemBlockRenderTypes.setRenderLayer"
        while (cursor < executableCode.length) {
            val callStart = executableCode.indexOf(token, cursor)
            if (callStart < 0) break
            val openParen = executableCode.indexOf('(', callStart + token.length)
            if (openParen < 0) break
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = openParen + 1
                continue
            }
            var semicolon = closeParen + 1
            while (semicolon < executableCode.length && executableCode[semicolon].isWhitespace()) semicolon++
            if (semicolon >= executableCode.length || executableCode[semicolon] != ';') {
                cursor = closeParen + 1
                continue
            }
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size == 2) {
                val target = Regex("""^(?:(\w+)\.)?(\w+)\s*\.\s*get\s*\(\s*\)$""")
                    .matchEntire(args[0].trim())
                val renderLayer = renderLayerCallSemantics(args[1].trim())
                if (target != null && renderLayer != null) {
                    val start = source.lastIndexOf('\n', callStart).let { if (it < 0) 0 else it + 1 }
                    var end = semicolon
                    if (end + 1 < source.length && source[end + 1] == '\r') end++
                    if (end + 1 < source.length && source[end + 1] == '\n') end++
                    calls += RenderLayerCall(
                        range = start..end,
                        ownerName = target.groupValues[1].takeIf { it.isNotBlank() },
                        fieldName = target.groupValues[2],
                        renderType = renderLayer.first,
                        allowedRenderTypes = renderLayer.second
                    )
                }
            }
            cursor = semicolon + 1
        }
        return calls
    }

    private fun renderLayerCallSemantics(expression: String): Pair<String?, Set<String>>? {
        directModelRenderType(expression)?.let { return it to setOf(it) }
        if ("->" !in expression) return null
        val renderTypes = Regex("""(?:net\.minecraft\.client\.renderer\.)?RenderType\.(\w+)\s*\(""")
            .findAll(expression)
            .mapNotNull { directModelRenderType("RenderType.${it.groupValues[1]}()") }
            .toSet()
        val solidAndTranslucent = setOf("minecraft:solid", "minecraft:translucent")
        return if (renderTypes == solidAndTranslucent) null to renderTypes else null
    }

    private fun directModelRenderType(expression: String): String? {
        val match = Regex("""^(?:net\.minecraft\.client\.renderer\.)?RenderType\.(\w+)\s*\(\s*\)$""")
            .matchEntire(expression)
            ?: return null
        return when (match.groupValues[1]) {
            "solid" -> "minecraft:solid"
            "cutout" -> "minecraft:cutout"
            "cutoutMipped" -> "minecraft:cutout_mipped"
            "translucent" -> "minecraft:translucent"
            "tripwire" -> "minecraft:tripwire"
            else -> null
        }
    }

    private fun collectRegisteredBlockIds(javaFiles: List<Path>): Map<String, String> {
        val qualified = linkedMapOf<String, String>()
        val byField = linkedMapOf<String, MutableSet<String>>()
        val id = """[A-Za-z_$][\w$]*"""
        val fieldPattern = Regex(
            """(?s)\bpublic\s+static\s+final\s+[^=;]*(?:\bBlock\b|DeferredHolder\s*<\s*Block\b)[^=;]*\s+($id)\s*=\s*[^;]*?\.register\s*\(\s*"([^"]+)"""
        )
        javaFiles.forEach { file ->
            val source = file.readText()
            val code = maskJavaComments(source)
            val executableCode = maskJavaCommentsAndLiterals(source)
            val className = classNameOfJavaSource(executableCode) ?: return@forEach
            fieldPattern.findAll(code).forEach { match ->
                val fieldName = match.groupValues[1]
                val blockId = match.groupValues[2]
                qualified["$className.$fieldName"] = blockId
                byField.getOrPut(fieldName) { linkedSetOf() } += blockId
            }
        }
        byField.forEach { (fieldName, ids) ->
            if (ids.size == 1) {
                qualified[fieldName] = ids.single()
            }
        }
        return qualified
    }

    private fun resolveRegisteredBlockId(blockIds: Map<String, String>, ownerName: String?, fieldName: String): String? =
        ownerName?.let { blockIds["$it.$fieldName"] } ?: blockIds[fieldName]

    private fun modelFilesForBlockResource(resourceRoots: List<Path>, blockId: String): Set<Path> {
        val blockstateFiles = resourceRoots.flatMap { root ->
            val assets = root.resolve("assets")
            if (!assets.exists()) {
                emptyList()
            } else {
                Files.list(assets).use { namespaces ->
                    namespaces
                        .filter { it.isDirectory() }
                        .map { it.resolve("blockstates/$blockId.json") }
                        .filter { it.exists() }
                        .toList()
                }
            }
        }
        if (blockstateFiles.isEmpty()) return emptySet()

        val modelIds = linkedSetOf<String>()
        blockstateFiles.forEach { blockstateFile ->
            val root = parseStructuralResourceJson(blockstateFile.readText()) ?: return@forEach
            val namespace = blockstateFile.parent?.parent?.fileName?.toString() ?: return@forEach
            collectModelIds(root, modelIds, namespace)
        }
        if (modelIds.isEmpty()) return emptySet()

        val modelFiles = linkedSetOf<Path>()
        modelIds.forEach { modelId ->
            val namespace = modelId.substringBefore(':')
            val path = modelId.substringAfter(':', modelId)
            resourceRoots
                .map { it.resolve("assets/$namespace/models/$path.json") }
                .firstOrNull { it.exists() }
                ?.let { modelFiles.add(it) }
                ?: return emptySet()
        }
        return modelFiles
    }

    private fun collectModelIds(element: JsonElement, output: MutableSet<String>, defaultNamespace: String) {
        when (element) {
            is JsonObject -> element.forEach { (key, value) ->
                if (key == "model" && value is JsonPrimitive && value.isString) {
                    val modelId = value.content
                    output += if (':' in modelId) modelId else "$defaultNamespace:$modelId"
                } else {
                    collectModelIds(value, output, defaultNamespace)
                }
            }
            is JsonArray -> element.forEach { collectModelIds(it, output, defaultNamespace) }
            else -> {}
        }
    }

    private fun ensureModelRenderTypes(
        modelFiles: Set<Path>,
        renderType: String?,
        allowedRenderTypes: Set<String>,
        dryRun: Boolean,
        changes: MutableList<Change>
    ): Boolean {
        val migrated = linkedMapOf<Path, JsonObject>()
        modelFiles.forEach { modelFile ->
            val root = parseStructuralResourceJson(modelFile.readText()) as? JsonObject ?: return false
            val migration = ensureModelRenderType(root, renderType, allowedRenderTypes) ?: return false
            if (migration.changed) {
                migrated[modelFile] = migration.element
            }
        }
        migrated.forEach { (modelFile, element) ->
            changes.add(Change(
                file = modelFile,
                line = 0,
                description = "Write model render_type for migrated render-layer registration",
                before = "(missing model render_type)",
                after = renderType ?: allowedRenderTypes.sorted().joinToString("|"),
                confidence = Confidence.HIGH,
                ruleId = "struct-render-layer-model-render-type"
            ))
            if (!dryRun) {
                modelFile.writeText(STRUCTURAL_RESOURCE_JSON.encodeToString(JsonElement.serializer(), element) + "\n")
            }
        }
        return true
    }

    private fun ensureModelRenderType(
        root: JsonObject,
        renderType: String?,
        allowedRenderTypes: Set<String>
    ): RenderLayerModelMigration? {
        val fallbackRenderType = renderType ?: "minecraft:solid".takeIf { it in allowedRenderTypes }
        val existing = root["render_type"] as? JsonPrimitive
        if (existing != null) {
            return if (existing.isString && existing.content in allowedRenderTypes) {
                RenderLayerModelMigration(root, changed = false)
            } else {
                null
            }
        }

        val loader = (root["loader"] as? JsonPrimitive)?.takeIf { it.isString }?.content
        if (loader == "neoforge:composite") {
            val children = root["children"] as? JsonObject ?: return RenderLayerModelMigration(root, changed = false)
            var changed = false
            val migratedChildren = linkedMapOf<String, JsonElement>()
            children.forEach { (name, child) ->
                val childObject = child as? JsonObject ?: return null
                val childExisting = childObject["render_type"] as? JsonPrimitive
                if (childExisting != null) {
                    if (!childExisting.isString || childExisting.content !in allowedRenderTypes) return null
                    migratedChildren[name] = childObject
                } else {
                    val childRenderType = fallbackRenderType ?: return null
                    val entries = linkedMapOf<String, JsonElement>()
                    childObject.forEach { (key, value) -> entries[key] = value }
                    entries["render_type"] = JsonPrimitive(childRenderType)
                    migratedChildren[name] = JsonObject(entries)
                    changed = true
                }
            }
            if (!changed) return RenderLayerModelMigration(root, changed = false)
            val entries = linkedMapOf<String, JsonElement>()
            root.forEach { (key, value) ->
                entries[key] = if (key == "children") JsonObject(migratedChildren) else value
            }
            return RenderLayerModelMigration(JsonObject(entries), changed = true)
        }

        val modelRenderType = fallbackRenderType ?: return null

        val entries = linkedMapOf<String, JsonElement>()
        var inserted = false
        root.forEach { (key, value) ->
            if (!inserted && key == "parent") {
                entries[key] = value
                entries["render_type"] = JsonPrimitive(modelRenderType)
                inserted = true
            } else {
                entries[key] = value
            }
        }
        if (!inserted) {
            entries["render_type"] = JsonPrimitive(modelRenderType)
        }
        return RenderLayerModelMigration(JsonObject(entries), changed = true)
    }

    private fun migrateLegacyItemHandlerHelperStackComparisons(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("ItemHandlerHelper.canItemStacksStack(")) return source
        var result = rewriteExecutableJavaCall(source, "canItemStacksStack") { receiver, args ->
            if (receiver != "ItemHandlerHelper" || args.size != 2) return@rewriteExecutableJavaCall null
            "net.minecraft.world.item.ItemStack.isSameItemSameComponents(${args[0].trim()}, ${args[1].trim()})"
        }
        val withoutImport = removeImport(result, "net.neoforged.neoforge.items.ItemHandlerHelper")
        result = if (!Regex("""\bItemHandlerHelper\b""").containsMatchIn(maskJavaCommentsAndLiterals(withoutImport))) {
            withoutImport
        } else {
            result
        }
        return result
    }

    private data class HolderLookupProviderThreadTarget(
        val owner: String,
        val name: String,
        val isConstructor: Boolean,
        val arity: Int
    )

    private data class ProjectHolderLookupProviderTarget(
        val ownerSimple: String,
        val ownerQualified: String,
        val name: String,
        val isConstructor: Boolean,
        val arity: Int
    )

    private data class ProjectHolderLookupForwarderTarget(
        val ownerSimple: String,
        val ownerQualified: String,
        val methodName: String,
        val arity: Int,
        val dataParameterIndex: Int,
        val dataParameterName: String,
        val dataType: String,
        val forwardedMethods: Set<String>
    )

    private fun migrateProjectNestedHolderLookupProviderCallSites(
        javaFiles: List<Path>,
        javaInheritanceIndex: JavaInheritanceIndex
    ): List<Change> {
        val targets = collectProjectNestedHolderLookupProviderTargets(javaFiles)
        if (targets.isEmpty()) return emptyList()
        val changes = mutableListOf<Change>()
        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            var migrated = original
            targets.forEach { target ->
                migrated = if (target.isConstructor) {
                    addHolderLookupProviderToConstructorCalls(migrated, target, javaInheritanceIndex)
                } else {
                    addHolderLookupProviderToMethodCalls(migrated, target, javaInheritanceIndex)
                }
            }
            if (migrated != original) {
                javaFile.writeText(migrated)
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Thread HolderLookup.Provider through provider-aware nested helper call sites",
                    before = "nested helper call without provider",
                    after = "nested helper call with proven HolderLookup.Provider",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-nested-holderlookup-call-sites"
                ))
            }
        }
        return changes
    }

    private fun migrateProjectHolderLookupForwarderMethods(
        javaFiles: List<Path>,
        holderLookupMethods: Set<HolderLookupNbtMethod>,
        javaInheritanceIndex: JavaInheritanceIndex
    ): List<Change> {
        val effectiveHolderLookupMethods = holderLookupMethods + collectExistingHolderLookupNbtMethods(javaFiles)
        if (effectiveHolderLookupMethods.isEmpty()) return emptyList()
        val targets = collectProjectHolderLookupForwarderTargets(javaFiles, effectiveHolderLookupMethods)
        if (targets.isEmpty()) return emptyList()
        val changes = mutableListOf<Change>()
        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            var migrated = original
            targets.forEach { target ->
                migrated = migrateHolderLookupForwarderDefinition(migrated, target, effectiveHolderLookupMethods)
            }
            if (migrated != original) {
                javaFile.writeText(migrated)
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Thread HolderLookup.Provider through provider-aware NBT forwarding helper definitions",
                    before = "helper calls provider-aware NBT method without provider",
                    after = "helper accepts HolderLookup.Provider and forwards it",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-holderlookup-forwarder-definition"
                ))
            }
        }

        javaFiles.forEach { javaFile ->
            val original = javaFile.readText()
            var migrated = original
            targets.forEach { target ->
                migrated = addHolderLookupProviderToForwarderCalls(migrated, target, javaInheritanceIndex)
            }
            if (migrated != original) {
                javaFile.writeText(migrated)
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Thread HolderLookup.Provider through provider-aware NBT forwarding helper call sites",
                    before = "forwarding helper call without provider",
                    after = "forwarding helper call with provider proven from data source",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-holderlookup-forwarder-call-sites"
                ))
            }
        }
        return changes
    }

    private fun collectProjectHolderLookupForwarderTargets(
        javaFiles: List<Path>,
        holderLookupMethods: Set<HolderLookupNbtMethod>
    ): Set<ProjectHolderLookupForwarderTarget> {
        val methodsByOwner = holderLookupMethods.groupBy { it.owner }
        if (methodsByOwner.isEmpty()) return emptySet()
        val ownerNames = methodsByOwner.keys
        val targets = linkedSetOf<ProjectHolderLookupForwarderTarget>()
        javaFiles.forEach { javaFile ->
            val source = javaFile.readText()
            if (!source.contains("CompoundTag")) return@forEach
            val packageName = packageNameOf(source)
            val topLevel = classNameOfJavaSource(source) ?: return@forEach
            val executableCode = maskJavaCommentsAndLiterals(source)
            val typeBlocks = javaTypeBlocks(source, executableCode)
            val topLevelBlock = typeBlocks.firstOrNull { it.name == topLevel } ?: return@forEach
            javaMethodRangesIncludingDefault(source).forEach { method ->
                if (method.range.first !in topLevelBlock.bodyStart..topLevelBlock.end) return@forEach
                val params = callableParameters(source, method.range)
                if (params.any { isHolderLookupProviderParameter(it) }) return@forEach
                val parsedParams = params.mapNotNull(::parseJavaParameter)
                val dataParam = parsedParams.withIndex().firstOrNull { (_, param) ->
                    param.first.substringAfterLast('.') in ownerNames
                } ?: return@forEach
                val dataType = dataParam.value.first.substringAfterLast('.')
                val dataName = dataParam.value.second
                val forwardedMethods = linkedSetOf<String>()
                val methodExecutable = executableCode.substring(method.range)
                methodsByOwner[dataType].orEmpty().forEach { targetMethod ->
                    val token = ".${targetMethod.methodName}("
                    var cursor = 0
                    while (true) {
                        val tokenIndex = methodExecutable.indexOf(token, cursor)
                        if (tokenIndex < 0) break
                        val absoluteToken = method.range.first + tokenIndex
                        val receiverStart = findExpressionReceiverStart(executableCode, absoluteToken)
                        if (receiverStart >= 0 && receiverStart < absoluteToken) {
                            val receiver = source.substring(receiverStart, absoluteToken).trim()
                            if (receiver == dataName) {
                                val openParen = absoluteToken + targetMethod.methodName.length + 1
                                val closeParen = findMatchingParen(executableCode, openParen)
                                if (closeParen >= 0) {
                                    val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
                                    if ((targetMethod.parameterCount == null || targetMethod.parameterCount == args.size) &&
                                        args.none { isHolderLookupProviderExpression(it, holderLookupProviderNamesAt(source, absoluteToken)) }
                                    ) {
                                        forwardedMethods += targetMethod.methodName
                                    }
                                }
                            }
                        }
                        cursor = tokenIndex + token.length
                    }
                }
                if (forwardedMethods.isNotEmpty()) {
                    targets += ProjectHolderLookupForwarderTarget(
                        ownerSimple = topLevel,
                        ownerQualified = if (packageName.isBlank()) topLevel else "$packageName.$topLevel",
                        methodName = method.name,
                        arity = params.size,
                        dataParameterIndex = dataParam.index,
                        dataParameterName = dataName,
                        dataType = dataType,
                        forwardedMethods = forwardedMethods
                    )
                }
            }
        }
        return targets
    }

    private fun collectExistingHolderLookupNbtMethods(javaFiles: List<Path>): Set<HolderLookupNbtMethod> {
        val result = linkedSetOf<HolderLookupNbtMethod>()
        javaFiles.forEach { javaFile ->
            val source = javaFile.readText()
            if (!source.contains("HolderLookup.Provider") && !source.contains("net.minecraft.core.HolderLookup.Provider")) {
                return@forEach
            }
            if (!source.contains("CompoundTag")) return@forEach
            val executableCode = maskJavaCommentsAndLiterals(source)
            val typeBlocks = javaTypeBlocks(source, executableCode)
            if (typeBlocks.isEmpty()) return@forEach
            javaMethodRangesIncludingDefault(source).forEach { method ->
                if (!method.header.contains("CompoundTag") ||
                    (!method.header.contains("HolderLookup.Provider") && !method.header.contains("net.minecraft.core.HolderLookup.Provider"))
                ) {
                    return@forEach
                }
                val params = callableParameters(source, method.range)
                if (params.lastOrNull()?.let(::isHolderLookupProviderParameter) != true) return@forEach
                val owner = typeBlocks.lastOrNull { method.range.first in it.bodyStart..it.end } ?: return@forEach
                result += HolderLookupNbtMethod(owner.name, method.name, params.size - 1)
            }
        }
        return result
    }

    private fun migrateHolderLookupForwarderDefinition(
        source: String,
        target: ProjectHolderLookupForwarderTarget,
        holderLookupMethods: Set<HolderLookupNbtMethod>
    ): String {
        if (!source.contains(target.methodName) || !source.contains(target.dataParameterName)) return source
        val ownerName = classNameOfJavaSource(source) ?: return source
        if (ownerName != target.ownerSimple) return source
        var result = source
        val methodsByName = holderLookupMethods
            .filter { it.owner == target.dataType && it.methodName in target.forwardedMethods }
            .groupBy { it.methodName }
        val providerName = uniqueJavaLocalName(result, "modporterRegistries")

        result = rewriteExecutableJavaCallsInForwarder(result, target) { methodName, receiver, args ->
            val methodTargets = methodsByName[methodName].orEmpty()
            if (receiver != target.dataParameterName ||
                methodTargets.none { it.parameterCount == null || it.parameterCount == args.size } ||
                args.any { isHolderLookupProviderExpression(it, setOf(providerName)) }
            ) {
                null
            } else {
                "$receiver.$methodName(${(args.map { it.trim() } + providerName).joinToString(", ")})"
            }
        }

        javaMethodRangesIncludingDefault(result).forEach { method ->
            if (method.name != target.methodName) return@forEach
            val params = callableParameters(result, method.range)
            if (params.size != target.arity || params.any { isHolderLookupProviderParameter(it) }) return@forEach
            val parsedParams = params.mapNotNull(::parseJavaParameter)
            if (parsedParams.getOrNull(target.dataParameterIndex)?.second != target.dataParameterName) return@forEach
            val span = callableParameterSpan(result, method.range) ?: return@forEach
            val insertion = if (params.isEmpty()) {
                "net.minecraft.core.HolderLookup.Provider $providerName"
            } else {
                ", net.minecraft.core.HolderLookup.Provider $providerName"
            }
            result = result.substring(0, span.second) + insertion + result.substring(span.second)
            return result
        }
        return result
    }

    private fun rewriteExecutableJavaCallsInForwarder(
        source: String,
        target: ProjectHolderLookupForwarderTarget,
        replacement: (methodName: String, receiver: String, args: List<String>) -> String?
    ): String {
        var result = source
        target.forwardedMethods.forEach { methodName ->
            result = rewriteExecutableJavaCallWithOffset(result, methodName) { receiver, args, offset ->
                val method = javaMethodRangesIncludingDefault(result)
                    .firstOrNull { it.name == target.methodName && offset in it.range }
                    ?: return@rewriteExecutableJavaCallWithOffset null
                val params = callableParameters(result, method.range)
                if (params.size != target.arity) return@rewriteExecutableJavaCallWithOffset null
                replacement(methodName, receiver, args)
            }
        }
        return result
    }

    private fun addHolderLookupProviderToForwarderCalls(
        source: String,
        target: ProjectHolderLookupForwarderTarget,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        if (!source.contains("${target.methodName}(")) return source
        var result = source
        do {
            val before = result
            result = rewriteExecutableJavaCallWithOffset(result, target.methodName) { receiver, args, offset ->
                if (!matchesForwarderOwner(receiver, target) || args.size != target.arity) {
                    return@rewriteExecutableJavaCallWithOffset null
                }
                val provider = holderLookupProviderForForwardedArgument(
                    result,
                    offset,
                    args[target.dataParameterIndex],
                    target.dataType,
                    javaInheritanceIndex
                ) ?: return@rewriteExecutableJavaCallWithOffset null
                "$receiver.${target.methodName}(${(args.map { it.trim() } + holderLookupProviderArgumentExpression(provider)).joinToString(", ")})"
            }
        } while (result != before)
        return result
    }

    private fun matchesForwarderOwner(receiver: String, target: ProjectHolderLookupForwarderTarget): Boolean {
        val normalized = receiver.trim()
        return normalized == target.ownerSimple ||
            normalized == target.ownerQualified ||
            normalized.endsWith(".${target.ownerSimple}") ||
            normalized.endsWith(".${target.ownerQualified}")
    }

    private fun holderLookupProviderForForwardedArgument(
        source: String,
        offset: Int,
        argument: String,
        dataType: String,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String? {
        providerFromSavedDataExpression(argument)?.let { return it }
        val variable = argument.trim().takeIf { Regex("""^[A-Za-z_$][\w$]*$""").matches(it) } ?: return registryAccessExpressionAt(source, offset, javaInheritanceIndex)
        val method = javaMethodRangesIncludingDefault(source).firstOrNull { offset in it.range }
            ?: return registryAccessExpressionAt(source, offset, javaInheritanceIndex)
        val beforeCall = source.substring(method.range.first, offset)
        val typePattern = """(?:[A-Za-z_$][\w$]*\.)*${Regex.escape(dataType)}"""
        val declaration = Regex("""\b$typePattern\s+${Regex.escape(variable)}\s*=\s*([^;\r\n]+);""")
            .findAll(maskJavaCommentsAndLiterals(beforeCall))
            .lastOrNull()
        if (declaration != null) {
            val initializer = beforeCall.substring(declaration.groups[1]!!.range).trim()
            providerFromSavedDataExpression(initializer)?.let { return it }
        }
        return registryAccessExpressionAt(source, offset, javaInheritanceIndex)
    }

    private fun providerFromSavedDataExpression(expression: String): String? {
        val normalized = expression.trim()
        Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*\(\))*)\.getDataStorage\(\)""")
            .find(normalized)
            ?.let { return "${it.groupValues[1]}.registryAccess()" }
        Regex("""\bgetInstance\(\s*([^()]+(?:\([^()]*\))?)\s*\)""")
            .find(normalized)
            ?.let { match ->
                val level = match.groupValues[1].trim()
                return "$level.registryAccess()"
            }
        return null
    }

    private fun collectProjectNestedHolderLookupProviderTargets(javaFiles: List<Path>): Set<ProjectHolderLookupProviderTarget> {
        val targets = linkedSetOf<ProjectHolderLookupProviderTarget>()
        javaFiles.forEach { javaFile ->
            val source = javaFile.readText()
            if (!source.contains("HolderLookup.Provider")) return@forEach
            val executableCode = maskJavaCommentsAndLiterals(source)
            val typeBlocks = javaTypeBlocks(source, executableCode)
            val nestedBlocks = typeBlocks.mapNotNull { inner ->
                val parent = typeBlocks
                    .filter { outer -> outer != inner && inner.declarationStart > outer.bodyStart && inner.end < outer.end }
                    .minByOrNull { outer -> outer.end - outer.bodyStart }
                parent?.let { inner to it }
            }
            nestedBlocks.forEach { (inner, parent) ->
                val qualifiedOwner = "${parent.name}.${inner.name}"
                javaConstructorRangesIncludingPackagePrivate(source, inner.name)
                    .filter { it.range.first > inner.bodyStart && it.range.last < inner.end }
                    .forEach { constructor ->
                        val params = callableParameters(source, constructor.range)
                        if (params.lastOrNull()?.let(::isHolderLookupProviderParameter) == true) {
                            targets += ProjectHolderLookupProviderTarget(
                                ownerSimple = inner.name,
                                ownerQualified = qualifiedOwner,
                                name = inner.name,
                                isConstructor = true,
                                arity = params.size - 1
                            )
                        }
                    }
                javaMethodRangesIncludingDefault(source)
                    .filter { it.range.first > inner.bodyStart && it.range.last < inner.end }
                    .forEach { method ->
                        val params = callableParameters(source, method.range)
                        if (params.lastOrNull()?.let(::isHolderLookupProviderParameter) == true) {
                            targets += ProjectHolderLookupProviderTarget(
                                ownerSimple = inner.name,
                                ownerQualified = qualifiedOwner,
                                name = method.name,
                                isConstructor = false,
                                arity = params.size - 1
                            )
                        }
                    }
            }
        }
        return targets
    }

    private fun migrateNestedHolderLookupProviderAccess(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val legacyAccess = "this.getLevel().registryAccess()"
        if (!source.contains(legacyAccess)) return source

        val providerType = "net.minecraft.core.HolderLookup.Provider"
        val executableCode = maskJavaCommentsAndLiterals(source)
        val typeBlocks = javaTypeBlocks(source, executableCode)
        val nestedBlocks = typeBlocks.filter { inner ->
            typeBlocks.any { outer ->
                outer != inner && inner.declarationStart > outer.bodyStart && inner.end < outer.end
            }
        }
        if (nestedBlocks.isEmpty()) return source

        val signatureAndBodyEdits = mutableListOf<Pair<IntRange, String>>()
        val targets = linkedSetOf<HolderLookupProviderThreadTarget>()

        fun addCallableTarget(owner: String, callable: JavaMethodRange, isConstructor: Boolean) {
            val callableText = source.substring(callable.range)
            if (!callableText.contains(legacyAccess)) return
            val span = callableParameterSpan(source, callable.range) ?: return
            val params = splitTopLevelJavaArgs(source.substring(span.first + 1, span.second))
            if (params.any { isHolderLookupProviderParameter(it) }) return

            val providerName = uniqueJavaLocalName(callableText, "modporterRegistries")
            val insertion = if (params.isEmpty()) {
                "$providerType $providerName"
            } else {
                ", $providerType $providerName"
            }
            signatureAndBodyEdits += span.second until span.second to insertion

            Regex(Regex.escape(legacyAccess))
                .findAll(executableCode, callable.range.first)
                .takeWhile { it.range.last <= callable.range.last }
                .forEach { signatureAndBodyEdits += it.range to providerName }

            targets += HolderLookupProviderThreadTarget(
                owner = owner,
                name = if (isConstructor) owner else callable.name,
                isConstructor = isConstructor,
                arity = params.size
            )
        }

        for (block in nestedBlocks) {
            javaConstructorRangesIncludingPackagePrivate(source, block.name)
                .filter { it.range.first > block.bodyStart && it.range.last < block.end }
                .forEach { addCallableTarget(block.name, it, isConstructor = true) }

            javaMethodRangesIncludingDefault(source)
                .filter { it.range.first > block.bodyStart && it.range.last < block.end }
                .forEach { addCallableTarget(block.name, it, isConstructor = false) }
        }

        if (targets.isEmpty()) return source
        var result = applyStringEdits(source, signatureAndBodyEdits)
        for (target in targets) {
            result = if (target.isConstructor) {
                addHolderLookupProviderToConstructorCalls(result, target, javaInheritanceIndex)
            } else {
                addHolderLookupProviderToMethodCalls(result, target, javaInheritanceIndex)
            }
        }
        return result
    }

    private fun addHolderLookupProviderToConstructorCalls(
        source: String,
        target: ProjectHolderLookupProviderTarget,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        var result = source
        var cursor = 0
        val constructorPattern = Regex("""\bnew\s+((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(target.ownerSimple)})\s*(?:<[^>()]+>\s*)?\(""")
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val match = constructorPattern.find(executableCode, cursor) ?: break
            val ownerExpression = match.groupValues[1]
            if (!matchesProviderTargetOwner(ownerExpression, target)) {
                cursor = match.range.last + 1
                continue
            }
            val openParen = executableCode.indexOf('(', match.range.last - 1)
            val closeParen = if (openParen >= 0) findMatchingParen(executableCode, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != target.arity) {
                cursor = closeParen + 1
                continue
            }
            val provider = registryAccessExpressionAt(result, match.range.first, javaInheritanceIndex)
            if (provider == null) {
                cursor = closeParen + 1
                continue
            }
            val providerArgument = holderLookupProviderArgumentExpression(provider)
            val insertion = if (args.isEmpty()) providerArgument else ", $providerArgument"
            result = result.substring(0, closeParen) + insertion + result.substring(closeParen)
            cursor = closeParen + insertion.length + 1
        }
        return result
    }

    private fun addHolderLookupProviderToMethodCalls(
        source: String,
        target: ProjectHolderLookupProviderTarget,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        var result = source
        val receivers = collectJavaVariablesOfType(source, target.ownerSimple, target.ownerQualified)
        if (receivers.isEmpty()) return result
        var cursor = 0
        val token = ".${target.name}("
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val tokenIndex = executableCode.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + target.name.length + 1
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(executableCode, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = result.substring(receiverStart, tokenIndex).trim()
            val receiverName = receiver.substringAfterLast('.')
            if (receiverName !in receivers) {
                cursor = closeParen + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != target.arity) {
                cursor = closeParen + 1
                continue
            }
            val provider = registryAccessExpressionAt(result, tokenIndex, javaInheritanceIndex)
            if (provider == null) {
                cursor = closeParen + 1
                continue
            }
            val providerArgument = holderLookupProviderArgumentExpression(provider)
            val insertion = if (args.isEmpty()) providerArgument else ", $providerArgument"
            result = result.substring(0, closeParen) + insertion + result.substring(closeParen)
            cursor = closeParen + insertion.length + 1
        }
        return result
    }

    private fun javaConstructorRangesIncludingPackagePrivate(source: String, className: String): List<JavaMethodRange> {
        val pattern = Regex(
            """(?m)^[ \t]*(?:@\w+(?:\([^)]*\))?\s*\r?\n[ \t]*)*(?:(?:public|protected|private)\s+)?${Regex.escape(className)}\s*\([^;{}]*\)\s*(?:throws\s+[^{;]+)?\{"""
        )
        return pattern.findAll(source).mapNotNull { match ->
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) return@mapNotNull null
            JavaMethodRange(className, match.value, match.range.first..closeBrace)
        }.toList()
    }

    private fun callableParameters(source: String, range: IntRange): List<String> {
        val span = callableParameterSpan(source, range) ?: return emptyList()
        return splitTopLevelJavaArgs(source.substring(span.first + 1, span.second))
    }

    private fun callableParameterSpan(source: String, range: IntRange): Pair<Int, Int>? {
        val executableCode = maskJavaCommentsAndLiterals(source)
        val openParen = executableCode.indexOf('(', range.first).takeIf { it >= 0 && it <= range.last } ?: return null
        val closeParen = findMatchingParen(executableCode, openParen).takeIf { it >= 0 && it <= range.last } ?: return null
        return openParen to closeParen
    }

    private fun isHolderLookupProviderParameter(parameter: String): Boolean {
        val cleaned = parameter.trim()
            .replace(Regex("""@\w+(?:\([^)]*\))?\s*"""), "")
            .removePrefix("final ")
            .trim()
        return Regex("""(?:^|\s)(?:net\.minecraft\.core\.)?HolderLookup\.Provider\s+[A-Za-z_$][\w$]*$""")
            .containsMatchIn(cleaned)
    }

    private fun addHolderLookupProviderToConstructorCalls(
        source: String,
        target: HolderLookupProviderThreadTarget,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        var result = source
        var cursor = 0
        val constructorPattern = Regex("""\bnew\s+${Regex.escape(target.owner)}\s*(?:<[^>()]+>\s*)?\(""")
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val match = constructorPattern.find(executableCode, cursor) ?: break
            val openParen = executableCode.indexOf('(', match.range.last - 1)
            val closeParen = if (openParen >= 0) findMatchingParen(executableCode, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != target.arity) {
                cursor = closeParen + 1
                continue
            }
            val provider = registryAccessExpressionAt(result, match.range.first, javaInheritanceIndex)
            if (provider == null) {
                cursor = closeParen + 1
                continue
            }
            val providerArgument = holderLookupProviderArgumentExpression(provider)
            val insertion = if (args.isEmpty()) providerArgument else ", $providerArgument"
            result = result.substring(0, closeParen) + insertion + result.substring(closeParen)
            cursor = closeParen + insertion.length + 1
        }
        return result
    }

    private fun addHolderLookupProviderToMethodCalls(
        source: String,
        target: HolderLookupProviderThreadTarget,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        var result = source
        val receivers = collectJavaVariablesOfType(source, target.owner)
        if (receivers.isEmpty()) return result
        var cursor = 0
        val token = ".${target.name}("
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val tokenIndex = executableCode.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + target.name.length + 1
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(executableCode, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = result.substring(receiverStart, tokenIndex).trim()
            val receiverName = receiver.substringAfterLast('.')
            if (receiverName !in receivers) {
                cursor = closeParen + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != target.arity) {
                cursor = closeParen + 1
                continue
            }
            val provider = registryAccessExpressionAt(result, tokenIndex, javaInheritanceIndex)
            if (provider == null) {
                cursor = closeParen + 1
                continue
            }
            val providerArgument = holderLookupProviderArgumentExpression(provider)
            val insertion = if (args.isEmpty()) providerArgument else ", $providerArgument"
            result = result.substring(0, closeParen) + insertion + result.substring(closeParen)
            cursor = closeParen + insertion.length + 1
        }
        return result
    }

    private fun collectJavaVariablesOfType(source: String, typeName: String): Set<String> {
        return collectJavaVariablesOfType(source, typeName, typeName)
    }

    private fun collectJavaVariablesOfType(source: String, simpleTypeName: String, qualifiedTypeName: String): Set<String> {
        val executableCode = maskJavaCommentsAndLiterals(source)
        val id = """[A-Za-z_$][\w$]*"""
        val variables = linkedSetOf<String>()
        val typeExpression = """(?:${Regex.escape(qualifiedTypeName)}|${Regex.escape(simpleTypeName)})"""
        Regex("""\b$typeExpression(?:\s*<[^;{}()]+>)?\s+($id)\b""")
            .findAll(executableCode)
            .forEach { variables += it.groupValues[1] }
        Regex("""\b$typeExpression(?:\s*<[^;{}()]+>)?\s+($id)\s*:""")
            .findAll(executableCode)
            .forEach { variables += it.groupValues[1] }
        return variables
    }

    private fun matchesProviderTargetOwner(ownerExpression: String, target: ProjectHolderLookupProviderTarget): Boolean {
        val normalized = ownerExpression.trim()
        return normalized == target.ownerSimple ||
            normalized == target.ownerQualified ||
            normalized.endsWith(".${target.ownerQualified}")
    }

    private fun isRegistryAccessEmptyExpression(expression: String): Boolean =
        expression.trim() == "net.minecraft.core.RegistryAccess.EMPTY" || expression.trim() == "RegistryAccess.EMPTY"

    private fun isHolderLookupProviderExpression(
        expression: String,
        providerNames: Set<String> = emptySet()
    ): Boolean {
        val normalized = expression.trim()
        return normalized in providerNames ||
            normalized == "registries" ||
            normalized.endsWith(".registryAccess()") ||
            normalized == "this.registryAccess()" ||
            normalized == "this.getLevel().registryAccess()" ||
            normalized.contains("HolderLookup.Provider")
    }

    private fun migrateLegacyGameEventListenerSource(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("GameEventListener") || !executableCode.contains("handleGameEvent(")) return source
        var result = source
        var changed = false
        result = replaceExecutableRegex(result, Regex(
            """boolean\s+handleGameEvent\s*\(\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*,\s*GameEvent\s+([A-Za-z_$][\w$]*)\s*,\s*GameEvent\.Context\s+([A-Za-z_$][\w$]*)\s*,\s*Vec3\s+([A-Za-z_$][\w$]*)\s*\)"""
        )) { match ->
            changed = true
            "boolean handleGameEvent(ServerLevel ${match.groupValues[1]}, Holder<GameEvent> ${match.groupValues[2]}, GameEvent.Context ${match.groupValues[3]}, Vec3 ${match.groupValues[4]})"
        }

        val holderEventVariables = Regex("""\bHolder\s*<\s*GameEvent\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(maskJavaCommentsAndLiterals(result))
            .map { it.groupValues[1] }
            .toSet()
        if (holderEventVariables.isEmpty()) return if (changed) addImportIfMissing(result, "net.minecraft.core.Holder") else result

        val eventConstant = """((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$][A-Za-z0-9_$]*(?:\.get\(\))?)"""
        for (eventVariable in holderEventVariables) {
            result = replaceExecutableRegex(result, Regex("""\b${Regex.escape(eventVariable)}\s*==\s*$eventConstant""")) { match ->
                changed = true
                "${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
            }
            result = replaceExecutableRegex(result, Regex("""$eventConstant\s*==\s*\b${Regex.escape(eventVariable)}\b""")) { match ->
                changed = true
                "${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
            }
            result = replaceExecutableRegex(result, Regex("""\b${Regex.escape(eventVariable)}\s*!=\s*$eventConstant""")) { match ->
                changed = true
                "!${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
            }
            result = replaceExecutableRegex(result, Regex("""$eventConstant\s*!=\s*\b${Regex.escape(eventVariable)}\b""")) { match ->
                changed = true
                "!${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
            }
        }

        return if (changed) addImportIfMissing(result, "net.minecraft.core.Holder") else result
    }

    private fun normaliseGameEventHolderComparison(expression: String): String =
        expression.trim().removeSuffix(".get()")

    private fun migrateRequiredMapCodecConstants(
        source: String,
        mapCodecRequiredOwners: Set<String> = emptySet()
    ): String {
        if (!source.contains("Codec<") || !source.contains("CODEC")) return source
        val mapCodecTypes = mutableSetOf<String>()
        val topLevelClassName = classNameOfJavaSource(source)
        val mapCodecBasePattern = """(?:[A-Za-z_$][\w$]*\.)*(?:BiomeSource|PlacementModifier|Structure|StructureProcessor|StructurePlacement)"""
        if (topLevelClassName != null &&
            (Regex("""\bextends\s+$mapCodecBasePattern\b""").containsMatchIn(source) ||
                topLevelClassName in mapCodecRequiredOwners)
        ) {
            mapCodecTypes += topLevelClassName
        }
        Regex("""\b(?:class|record)\s+([A-Za-z_$][\w$]*)\b[^{;]*\bextends\s+$mapCodecBasePattern\b""")
            .findAll(source)
            .forEach { mapCodecTypes += it.groupValues[1] }
        if (mapCodecRequiredOwners.isNotEmpty()) {
            Regex("""\b(?:class|record)\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(source)
                .map { it.groupValues[1] }
                .filter { it in mapCodecRequiredOwners }
                .forEach { mapCodecTypes += it }
        }
        if (mapCodecTypes.isEmpty()) return source

        var result = source
        var changed = false
        for (className in mapCodecTypes) {
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*RecordCodecBuilder\s*\.\s*(?:<\s*${Regex.escape(className)}\s*>\s*)?create\s*\("""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = RecordCodecBuilder.<$className>mapCodec("
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*simpleCodec\s*\("""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = simpleCodec("
            }

            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*((?:[A-Za-z_$][\w$]*\.)*[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*\.CODEC(?:\.codec\(\))?\.listOf\(\))\.xmap\(([^;\r\n]+)\);"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = ${match.groupValues[2]}.fieldOf(\"value\").xmap(${match.groupValues[3]});"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*((?:[A-Za-z_$][\w$]*\.)*[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*\.CODEC(?:\.codec\(\))?\.listOf\(\)\.fieldOf\("[^"]+"\)\.xmap\([^;\r\n]+?\))\.codec\(\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = ${match.groupValues[2]};"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*Codec\.unit\(\s*\(\s*\)\s*->\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = MapCodec.unit(${match.groupValues[2]});"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*Codec\.unit\(\s*([^;\r\n]+?)\s*\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = MapCodec.unit(${match.groupValues[2].trim()});"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*([^;\r\n]+?\.fieldOf\("[^"]+"\)\.xmap\([^;\r\n]+?\))\.codec\(\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = ${match.groupValues[2]};"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*([^;\r\n]+?\.(?:comapFlatMap|flatXmap|xmap)\([^;\r\n]+?\))\s*;"""
            ).replace(result) { match ->
                val codecExpression = match.groupValues[2]
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = $codecExpression.fieldOf(\"value\");"
            }
        }

        if (changed) {
            result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
            if (!Regex("""\bCodec\s*<""").containsMatchIn(result) && !Regex("""\bCodec\.""").containsMatchIn(result)) {
                result = removeImport(result, "com.mojang.serialization.Codec")
            }
        }
        if (result.contains("extends BiomeSource")) {
            result = Regex("""protected\s+Codec\s*<\s*\?\s+extends\s+BiomeSource\s*>\s+codec\s*\(""")
                .replace(result, "protected MapCodec<? extends BiomeSource> codec(")
        }
        return result
    }

    private fun migrateMapCodecRegistryFactorySignatures(source: String): String {
        if (!source.contains("Codec<")) return source
        val registryTypes = listOf(
            "PlacementModifierType",
            "StructureProcessorType",
            "StructurePlacementType",
            "StructureType",
            "TreeDecoratorType"
        )
        var result = source
        var changed = false
        registryTypes.forEach { registryType ->
            result = Regex(
                """\b(${Regex.escape(registryType)}\s*<\s*([A-Za-z_$][\w$]*)\s*>\s+[A-Za-z_$][\w$]*\s*\((?:[^()]|\([^()]*\))*?,\s*)(?:com\.mojang\.serialization\.)?Codec\s*<\s*\2\s*>\s+([A-Za-z_$][\w$]*)"""
            ).replace(result) { match ->
                changed = true
                "${match.groupValues[1]}MapCodec<${match.groupValues[2]}> ${match.groupValues[3]}"
            }
        }
        if (!changed) return source
        result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
        val withoutCodecImport = removeImport(result, "com.mojang.serialization.Codec")
        return if (!Regex("""(?<!Map)\bCodec\b""").containsMatchIn(withoutCodecImport)) withoutCodecImport else result
    }

    private data class PlacementModifierTypeRegistryField(
        val ownerSimpleName: String,
        val ownerQualifiedName: String,
        val fieldName: String
    )

    private fun collectPlacementModifierTypeRegistryFields(javaFiles: List<Path>): Set<PlacementModifierTypeRegistryField> {
        val fields = linkedSetOf<PlacementModifierTypeRegistryField>()
        javaFiles.forEach { javaFile ->
            val source = javaFile.readText()
            if (!source.contains("BuiltInRegistries.PLACEMENT_MODIFIER_TYPE") ||
                !source.contains("PlacementModifierType")) {
                return@forEach
            }
            val owner = classNameOfJavaSource(source) ?: return@forEach
            val packageName = packageNameOf(source)
            val qualifiedOwner = if (packageName.isBlank()) owner else "$packageName.$owner"
            Regex(
                """(?m)\bstatic\s+final\s+PlacementModifierType\s*<\s*[^>\r\n]+>\s+([A-Z][A-Z0-9_]*)\s*=\s*register\s*\("""
            ).findAll(source)
                .mapTo(fields) { PlacementModifierTypeRegistryField(owner, qualifiedOwner, it.groupValues[1]) }
        }
        return fields
    }

    private fun migrateBuiltInPlacementModifierTypeRegistrations(source: String): String {
        if (!source.contains("BuiltInRegistries.PLACEMENT_MODIFIER_TYPE") ||
            !source.contains("PlacementModifierType")) {
            return source
        }
        val modIdExpression = placementModifierRegistryNamespaceExpression(source) ?: return source
        var changed = false
        var result = Regex(
            """(?m)^([ \t]*(?:public|protected|private)?\s*static\s+final\s+)PlacementModifierType\s*<\s*([^>\r\n]+)\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*register\s*\(\s*(.+?)\s*,\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.CODEC)\s*\)\s*;"""
        ).replace(source) { match ->
            val pathExpression = placementModifierRegistryPathExpression(match.groupValues[4].trim())
                ?: return@replace match.value
            changed = true
            "${match.groupValues[1]}DeferredHolder<PlacementModifierType<?>, PlacementModifierType<${match.groupValues[2].trim()}>> ${match.groupValues[3]} = register($pathExpression, ${match.groupValues[5].trim()});"
        }
        if (!changed) return source

        result = ensurePlacementModifierDeferredRegister(result, modIdExpression)
        result = Regex(
            """(?ms)^([ \t]*(?:public|protected|private)?\s*static\s*<\s*P\s+extends\s+PlacementModifier\s*>\s*)PlacementModifierType\s*<\s*P\s*>\s+register\s*\(\s*ResourceLocation\s+[A-Za-z_$][\w$]*\s*,\s*MapCodec\s*<\s*P\s*>\s+[A-Za-z_$][\w$]*\s*\)\s*\{\s*return\s+Registry\.register\s*\(\s*BuiltInRegistries\.PLACEMENT_MODIFIER_TYPE\s*,\s*[A-Za-z_$][\w$]*\s*,\s*\(\)\s*->\s*[A-Za-z_$][\w$]*\s*\)\s*;\s*\}"""
        ).replace(result) { match ->
            val indent = match.groupValues[1].takeWhile { it.isWhitespace() }
            "${match.groupValues[1]}DeferredHolder<PlacementModifierType<?>, PlacementModifierType<P>> register(String name, MapCodec<P> codec) {\n${indent}    return PLACEMENT_MODIFIER_TYPES.register(name, () -> () -> codec);\n$indent}"
        }
        result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        result = addImportIfMissing(result, "net.neoforged.neoforge.registries.DeferredHolder")
        result = addImportIfMissing(result, "net.neoforged.neoforge.registries.DeferredRegister")
        if (!result.contains("Registry.")) result = removeImport(result, "net.minecraft.core.Registry")
        if (!result.contains("BuiltInRegistries.")) result = removeImport(result, "net.minecraft.core.registries.BuiltInRegistries")
        if (!Regex("""\bResourceLocation\b""").containsMatchIn(removeImport(result, "net.minecraft.resources.ResourceLocation"))) {
            result = removeImport(result, "net.minecraft.resources.ResourceLocation")
        }
        return result
    }

    private fun placementModifierRegistryNamespaceExpression(source: String): String? {
        Regex("""ResourceLocation\.fromNamespaceAndPath\s*\(\s*([^,\r\n]+?)\s*,""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?.let { return it }
        Regex("""ResourceLocation\.parse\s*\(\s*"([a-z0-9_.-]+):[a-z0-9_./-]+"\s*\)""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { return "\"$it\"" }
        return null
    }

    private fun placementModifierRegistryPathExpression(nameExpression: String): String? {
        Regex("""ResourceLocation\.fromNamespaceAndPath\s*\(\s*[^,\r\n]+?\s*,\s*([^)]+?)\s*\)""")
            .matchEntire(nameExpression)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?.let { return it }
        Regex("""ResourceLocation\.parse\s*\(\s*"[a-z0-9_.-]+:([a-z0-9_./-]+)"\s*\)""")
            .matchEntire(nameExpression)
            ?.groupValues
            ?.get(1)
            ?.let { return "\"$it\"" }
        return null
    }

    private fun ensurePlacementModifierDeferredRegister(source: String, modIdExpression: String): String {
        if (source.contains("DeferredRegister<PlacementModifierType<?>> PLACEMENT_MODIFIER_TYPES")) return source
        val classMatch = Regex("""\bclass\s+[A-Za-z_$][\w$]*[^{]*\{""").find(source) ?: return source
        val declaration = "\n    public static final DeferredRegister<PlacementModifierType<?>> PLACEMENT_MODIFIER_TYPES = DeferredRegister.create(Registries.PLACEMENT_MODIFIER_TYPE, $modIdExpression);\n"
        return source.substring(0, classMatch.range.last + 1) + declaration + source.substring(classMatch.range.last + 1)
    }

    private fun migratePlacementModifierTypeDeferredHolderReferences(
        source: String,
        fields: Set<PlacementModifierTypeRegistryField>
    ): String {
        if (fields.isEmpty()) return source
        val currentOwner = classNameOfJavaSource(source)
        var result = source
        for (field in fields) {
            result = Regex("""\breturn\s+${Regex.escape(field.ownerSimpleName)}\.${Regex.escape(field.fieldName)}\s*;""")
                .replace(result, "return ${field.ownerSimpleName}.${field.fieldName}.get();")
            result = Regex("""\breturn\s+${Regex.escape(field.ownerQualifiedName)}\.${Regex.escape(field.fieldName)}\s*;""")
                .replace(result, "return ${field.ownerQualifiedName}.${field.fieldName}.get();")
            if (currentOwner == field.ownerSimpleName) {
                result = Regex("""\breturn\s+${Regex.escape(field.fieldName)}\s*;""")
                    .replace(result, "return ${field.fieldName}.get();")
            }
        }
        return result
    }

    private fun migrateMapCodecSerializationCalls(
        source: String,
        mapCodecConstantOwners: Set<String>
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (mapCodecConstantOwners.isEmpty() || !executableCode.contains(".CODEC.")) return source
        var result = source
        for (owner in mapCodecConstantOwners) {
            result = replaceExecutableRegex(
                result,
                Regex("""\b((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(owner)}\.CODEC)\.(parse|encodeStart)\s*\(""")
            ) { match -> "${match.groupValues[1]}.codec().${match.groupValues[2]}(" }
        }
        return result
    }

    private fun migrateLegacyDataResultGetOrThrowCalls(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".getOrThrow(")) return source
        return rewriteExecutableJavaCall(source, "getOrThrow") { receiver, args ->
            if (args.size != 2 || args[0].trim() != "true") return@rewriteExecutableJavaCall null
            val onError = args[1].trim()
            "$receiver.promotePartial($onError).getOrThrow(IllegalStateException::new)"
        }
    }

    private fun migrateKnownVanillaCodecCodecCalls(
        source: String,
        mapCodecConstantOwners: Set<String>,
        codecConstantOwners: Set<String>
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".CODEC.codec()")) return source
        val knownCodecOwners = setOf(
            "BlockState",
            "BoundingBox",
            "MobSpawnSettings.SpawnerData",
            "ProcessorRule",
            "ResourceLocation",
            "TreeDecorator"
        )
        var result = source
        for (owner in knownCodecOwners + codecConstantOwners) {
            if (owner in mapCodecConstantOwners) continue
            result = replaceExecutableRegex(
                result,
                Regex("""\b((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(owner)}\.CODEC)\.codec\(\)""")
            ) { match ->
                match.groupValues[1]
            }
        }
        return result
    }

    private fun migrateMapCodecFeatureConstructorArguments(
        source: String,
        mapCodecConstantOwners: Set<String>
    ): String {
        if (mapCodecConstantOwners.isEmpty() || !source.contains("new ") || !source.contains(".CODEC")) return source
        var result = source
        var cursor = 0
        val pattern = Regex("""new\s+([A-Za-z_$][\w$]*)\s*\(""")
        while (true) {
            val match = pattern.find(result, cursor) ?: break
            val className = match.groupValues[1]
            if (!className.endsWith("Feature")) {
                cursor = match.range.last + 1
                continue
            }
            val openParen = result.indexOf('(', match.range.last)
            val closeParen = if (openParen >= 0) findMatchingParen(result, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val migratedArgs = args.map { arg -> migrateMapCodecReferenceArgument(arg, mapCodecConstantOwners) }
            if (migratedArgs != args) {
                val replacement = migratedArgs.joinToString(", ")
                result = result.substring(0, openParen + 1) + replacement + result.substring(closeParen)
                cursor = openParen + replacement.length + 1
            } else {
                cursor = closeParen + 1
            }
        }
        return result
    }

    private fun migrateMapCodecReferenceArgument(arg: String, mapCodecConstantOwners: Set<String>): String {
        val trimmed = arg.trim()
        if (trimmed.endsWith(".codec()")) return arg
        val owner = mapCodecCodecReferenceOwner(trimmed) ?: return arg
        return if (owner in mapCodecConstantOwners) "${trimmed}.codec()" else arg
    }

    private fun migrateLegacyLazyRegistryCodecs(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("ExtraCodecs.lazyInitializedCodec(") || !executableCode.contains(".byNameCodec()")) return source
        var result = replaceExecutableJavaRegex(source, Regex(
            """ExtraCodecs\.lazyInitializedCodec\(\s*\(\s*\)\s*->\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.byNameCodec\(\))\s*\)"""
        )) { match ->
            match.groupValues[1]
        }
        if (!maskJavaCommentsAndLiterals(result).contains("ExtraCodecs.")) {
            result = removeExecutableImport(result, "net.minecraft.util.ExtraCodecs")
        }
        return result
    }

    private fun migrateLegacyDeferredHolderDelegateAccessors(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".getHolder().orElseThrow()")) return source
        return replaceExecutableJavaRegex(source, Regex("""\.getHolder\(\)\.orElseThrow\(\)""")) {
            ".getDelegate()"
        }
    }

    private fun migrateLegacyRegistryObjectMethodReferences(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("RegistryObject::get")) return source
        var result = replaceExecutableJavaRegex(source, Regex("""\bRegistryObject::get\b""")) {
            "DeferredHolder::get"
        }
        result = addExecutableImportIfMissing(result, "net.neoforged.neoforge.registries.DeferredHolder")
        if (!Regex("""\bRegistryObject\b""").containsMatchIn(maskJavaCommentsAndLiterals(result))) {
            result = removeExecutableImport(result, "net.neoforged.neoforge.registries.RegistryObject")
            result = removeExecutableImport(result, "net.minecraftforge.registries.RegistryObject")
        }
        return result
    }

    private fun migrateDeferredHolderCollectionVariance(source: String): String {
        if (!source.contains("DeferredHolder::get") && !source.contains(".getEntries().stream().map(")) return source
        return Regex(
            """Collection\s*<\s*Item\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]*\.getEntries\(\)\.stream\(\)\.map\(DeferredHolder::get\)\.toList\(\)\s*;)"""
        ).replace(source) { match ->
            "Collection<? extends Item> ${match.groupValues[1]} = ${match.groupValues[2]}"
        }
    }

    private fun migrateDeferredHolderGetValueCalls(
        source: String,
        deferredHolderFields: Map<String, Set<String>>
    ): String {
        if (!source.contains(".getValue()") || deferredHolderFields.isEmpty()) return source
        var result = source
        deferredHolderFields.forEach { (owner, fields) ->
            fields.forEach { field ->
                result = Regex("""\b${Regex.escape(owner)}\.${Regex.escape(field)}\.getValue\(\)""")
                    .replace(result, "$owner.$field.get()")
            }
        }
        val localOwner = classNameOfJavaSource(source)
        val localFields = localOwner?.let { deferredHolderFields[it] }.orEmpty()
        localFields.forEach { field ->
            result = Regex("""\b${Regex.escape(field)}\.getValue\(\)""")
                .replace(result, "$field.get()")
        }
        return result
    }

    private fun migrateDeferredHolderGameEventArguments(
        source: String,
        gameEventHolderFields: Set<String>
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".gameEvent(") || !executableCode.contains(".get()") || gameEventHolderFields.isEmpty()) {
            return source
        }
        val localOwner = classNameOfJavaSource(source)
        val localGameEventFields = if (localOwner == null) {
            emptySet()
        } else {
            gameEventHolderFields.asSequence()
                .filter { it.substringBeforeLast('.', missingDelimiterValue = "") == localOwner }
                .map { it.substringAfterLast('.') }
                .toSet()
        }
        fun provenHolderExpression(expression: String): Boolean {
            val trimmed = expression.trim()
            return trimmed in gameEventHolderFields || trimmed in localGameEventFields
        }

        var anyChanged = false
        val migrated = rewriteExecutableJavaCall(source, "gameEvent") { receiver, args ->
            if (args.isEmpty()) return@rewriteExecutableJavaCall null
            var callChanged = false
            val rewrittenArgs = args.map { arg ->
                val trimmed = arg.trim()
                val getCall = Regex("""^((?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*)\.get\(\)$""")
                    .find(trimmed)
                    ?: return@map arg
                val holderExpression = getCall.groupValues[1]
                if (provenHolderExpression(holderExpression)) {
                    callChanged = true
                    anyChanged = true
                    holderExpression
                } else {
                    arg
                }
            }
            if (!callChanged) return@rewriteExecutableJavaCall null
            "$receiver.gameEvent(${rewrittenArgs.joinToString(", ") { it.trim() }})"
        }
        return if (anyChanged) migrated else source
    }

    private fun migrateLegacyCommonHooksToolChecks(source: String): String {
        if (!source.contains("CommonHooks.isCorrectToolForDrops(")) return source
        var result = Regex(
            """CommonHooks\.isCorrectToolForDrops\(\s*([^,\r\n]+)\s*,\s*([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(source) { match ->
            val state = match.groupValues[1].trim()
            val player = match.groupValues[2]
            "$player.getMainHandItem().isCorrectToolForDrops($state)"
        }
        if (!result.contains("CommonHooks.")) {
            result = removeImport(result, "net.neoforged.neoforge.common.CommonHooks")
        }
        return result
    }

    private fun migrateWeightedEntryWrapperAccessors(source: String): String {
        if (!source.contains("WeightedEntry.Wrapper") ||
            (!source.contains(".getData()") && !source.contains("WeightedEntry.Wrapper::getData"))
        ) return source
        var result = source.replace(".getData()", ".data()")
        result = result.replace("WeightedEntry.Wrapper::getData", "WeightedEntry.Wrapper::data")
        return result
    }

    private fun migrateLegacyBlockStatePropertyGetCalls(source: String): String {
        if (!source.contains(".get(") || !source.contains("BlockState")) return source
        val stateVariables = Regex("""\b(?:net\.minecraft\.world\.level\.block\.state\.)?BlockState\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (stateVariables.isEmpty()) return source

        var result = source
        for (variable in stateVariables) {
            result = Regex("""\b${Regex.escape(variable)}\.get\s*\(""")
                .replace(result) { "$variable.getValue(" }
        }
        return result
    }

    private fun migrateJavaOptionalGetValueCalls(source: String): String {
        if (!source.contains(".getValue()")) return source
        var result = replaceExecutableRegex(
            source,
            Regex("""\.getSleepingPos\s*\(\s*\)\s*\.getValue\s*\(\s*\)""")
        ) { ".getSleepingPos().get()" }
        if (!result.contains("Optional")) return result
        val optionalVariables = Regex(
            """\b(?:java\.util\.)?Optional\s*<[^;\r\n=()]+>\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(maskJavaCommentsAndLiterals(result))
            .map { it.groupValues[1] }
            .toSet()
        if (optionalVariables.isEmpty()) return result

        optionalVariables.forEach { variable ->
            result = replaceExecutableRegex(
                result,
                Regex("""\b${Regex.escape(variable)}\.getValue\(\)""")
            ) { "$variable.get()" }
        }
        return result
    }

    private fun migrateLegacyCauldronInteractionResults(source: String): String {
        if (!source.contains("CauldronInteraction") || !source.contains("InteractionResult")) return source
        var result = source
        val helperNames = linkedSetOf<String>()
        Regex(
            """CauldronInteraction\s+[A-Z0-9_$]+\s*=\s*\([^)]*\)\s*->\s*([A-Za-z_$][\w$]*)\s*\("""
        ).findAll(result).forEach { match ->
            helperNames += match.groupValues[1]
        }
        for (helper in helperNames) {
            result = Regex("""\b(private|protected|public)\s+static\s+InteractionResult\s+${Regex.escape(helper)}\s*\(""")
                .replace(result) { match -> "${match.groupValues[1]} static ItemInteractionResult $helper(" }
        }

        val hasCauldronBlockLambda = Regex(
            """CauldronInteraction\s+[A-Z0-9_$]+\s*=\s*\([^)]*\)\s*->\s*\{(?:[^{}]|\{[^{}]*})*InteractionResult\.sidedSuccess"""
        ).containsMatchIn(result)
        val migratedHelperReturn = helperNames.any { helper ->
            Regex("""\bItemInteractionResult\s+${Regex.escape(helper)}\s*\(""").containsMatchIn(result)
        }
        if (hasCauldronBlockLambda || migratedHelperReturn) {
            result = result.replace("InteractionResult.sidedSuccess(", "ItemInteractionResult.sidedSuccess(")
            result = addImportIfMissing(result, "net.minecraft.world.ItemInteractionResult")
            val withoutOldImport = removeImport(result, "net.minecraft.world.InteractionResult")
            if (!Regex("""\bInteractionResult\b""").containsMatchIn(withoutOldImport.replace("ItemInteractionResult", ""))) {
                result = withoutOldImport
            }
        }
        return result
    }

    private fun migrateLegacyRegistryBuilderAndRegistryAccessors(
        source: String,
        staticRegistryFieldHints: StaticRegistryFieldHints = StaticRegistryFieldHints(emptySet(), emptySet())
    ): String {
        if (!source.contains("RegistryBuilder") &&
            !source.contains(".getValues()") &&
            !source.contains(".getValue(") &&
            !source.contains(".getKey(") &&
            !source.contains(".allowModification()") &&
            !source.contains(".disableSync()") &&
            !source.contains(".getCodec()")
        ) {
            return source
        }
        var result = source
        val registryNamesUnwrappedFromSupplier = mutableSetOf<String>()
        result = Regex(
            """(?:java\.util\.function\.)?Supplier\s*<\s*Registry\s*<\s*([A-Za-z_$][\w$]*)\s*>\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]+?)\.makeRegistry\(\s*\(\s*\)\s*->\s*new\s+RegistryBuilder\s*<\s*\1\s*>\s*\([^)]*\)\s*((?:\s*\.[A-Za-z_$][\w$]*\s*\([^;()]*\))*)\s*\)"""
        ).replace(result) { match ->
            val type = match.groupValues[1]
            val registryName = match.groupValues[2]
            val registerExpression = match.groupValues[3].trim()
            val builderChain = match.groupValues[4]
                .replace(Regex("""\s*\.hasTags\(\)"""), "")
                .trim()
            registryNamesUnwrappedFromSupplier += registryName
            val builderConsumer = if (builderChain.isBlank()) {
                "builder -> {}"
            } else {
                "builder -> builder$builderChain"
            }
            "Registry<$type> $registryName = $registerExpression.makeRegistry($builderConsumer)"
        }
        result = Regex(
            """(?:java\.util\.function\.)?Supplier\s*<\s*Registry\s*<\s*([A-Za-z_$][\w$]*)\s*>\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]+?)\.makeRegistry\(\s*RegistryBuilder::new\s*\)"""
        ).replace(result) { match ->
            val type = match.groupValues[1]
            val registryName = match.groupValues[2]
            val registerExpression = match.groupValues[3].trim()
            registryNamesUnwrappedFromSupplier += registryName
            "Registry<$type> $registryName = $registerExpression.makeRegistry(builder -> {})"
        }
        for (registryName in registryNamesUnwrappedFromSupplier) {
            result = Regex("""\b((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(registryName)})\.get\(\)""")
                .replace(result) { match -> match.groupValues[1] }
        }
        if (registryNamesUnwrappedFromSupplier.isNotEmpty() && !Regex("""\bSupplier\s*<""").containsMatchIn(result)) {
            result = removeImport(result, "java.util.function.Supplier")
        }
        val registrySupplierNames = Regex(
            """\b(?:java\.util\.function\.)?Supplier\s*<\s*Registry\s*<[^>\r\n]+>\s*>\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(result).map { it.groupValues[1] }.toSet()
        val registryVariableNames = Regex(
            """\bRegistry\s*<[^>\r\n]+>\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(result).map { it.groupValues[1] }.toSet()
        fun isKnownRegistryExpression(expression: String): Boolean {
            val trimmed = expression.trim()
            val registryName = trimmed.substringAfterLast(".")
            val registrySupplierName = if (trimmed.endsWith(".get()")) {
                trimmed.removeSuffix(".get()").substringAfterLast(".")
            } else {
                ""
            }
            return registryName in registryVariableNames ||
                registrySupplierName in registrySupplierNames ||
                trimmed.startsWith("BuiltInRegistries.") ||
                staticRegistryFieldHints.contains(trimmed)
        }
        val registryKeysByType = Regex(
            """ResourceKey<\s*Registry<\s*([A-Za-z_$][\w$]*)\s*>\s*>\s+([A-Za-z_$][\w$]*)\s*="""
        ).findAll(result).associate { it.groupValues[1] to it.groupValues[2] }
        for ((type, key) in registryKeysByType) {
            result = result.replace("new RegistryBuilder<$type>()", "new RegistryBuilder<$type>($key)")
        }
        result = Regex("""\b([A-Za-z_$][\w$]*)\s*->\s*\1\.allowModification\(\)\.disableSync\(\)""")
            .replace(result) { match -> "${match.groupValues[1]} -> {}" }
        result = Regex("""\b([A-Za-z_$][\w$]*)\s*->\s*\1\.disableSync\(\)""")
            .replace(result) { match -> "${match.groupValues[1]} -> {}" }
        result = result.replace(".allowModification()", "")
        result = result.replace(".disableSync()", ".sync(false)")
        result = result.replace(".hasTags()", "")
        for (registryName in registryVariableNames) {
            result = Regex("""\b((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(registryName)})\.getCodec\(\)""")
                .replace(result) { match -> "${match.groupValues[1]}.byNameCodec()" }
        }
        result = Regex("""\b(BuiltInRegistries\.[A-Z_]+)\.getCodec\(\)""")
            .replace(result) { match -> "${match.groupValues[1]}.byNameCodec()" }
        result = result.replace(".getValues().toArray(", ".stream().toArray(")
        result = rewriteJavaCall(result, "size") { receiver, args ->
            if (args.isNotEmpty() || !receiver.endsWith(".getValues()")) {
                null
            } else {
                val registryReceiver = receiver.removeSuffix(".getValues()")
                if (!isKnownRegistryExpression(registryReceiver)) {
                    null
                } else {
                    "(int) $registryReceiver.stream().count()"
                }
            }
        }
        result = rewriteJavaCall(result, "forEach") { receiver, args ->
            if (args.size != 1 || !receiver.endsWith(".getValues()")) {
                null
            } else {
                val registryReceiver = receiver.removeSuffix(".getValues()")
                if (!isKnownRegistryExpression(registryReceiver)) {
                    null
                } else {
                    "$registryReceiver.stream().forEach(${args[0].trim()})"
                }
            }
        }
        result = rewriteJavaCall(result, "getKey") { receiver, args ->
            if (args.size != 1 || !receiver.trim().endsWith(".get()")) {
                null
            } else {
                val registryReceiver = receiver.trim().removeSuffix(".get()")
                if (!isKnownRegistryExpression(registryReceiver)) {
                    null
                } else {
                    "$registryReceiver.getKey(${args[0].trim()})"
                }
            }
        }
        result = rewriteJavaCall(result, "getValue") { receiver, args ->
            if (args.size != 1) {
                null
            } else {
                val trimmedReceiver = receiver.trim()
                if (isKnownRegistryExpression(trimmedReceiver)) {
                    "$trimmedReceiver.get(${args[0].trim()})"
                } else {
                    null
                }
            }
        }
        return result
    }

    private fun migrateLegacyEyeHeightOverrides(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("getStandingEyeHeight(") && !source.contains("getEyeHeight(Pose")) return source
        var result = source
        var cursor = 0
        val signaturePattern = Regex(
            """(?m)(?:[ \t]*@\w+(?:\([^)]*\))?\s*\r?\n)*[ \t]*(?:public|protected)\s+float\s+(getStandingEyeHeight|getEyeHeight)\s*\(\s*Pose\s+([A-Za-z_$][\w$]*)(?:\s*,\s*EntityDimensions\s+([A-Za-z_$][\w$]*))?\s*\)\s*\{"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val methodText = result.substring(match.range.first, closeBrace + 1)
            val returnMatch = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL).find(methodText)
            if (returnMatch == null) {
                cursor = closeBrace + 1
                continue
            }
            val poseName = match.groupValues[2]
            val dimensionsName = match.groupValues.getOrNull(3).orEmpty()
            var eyeExpression = returnMatch.groupValues[1].trim()
            val classDeclaration = enclosingJavaClassDeclaration(result, match.range.first)
            val livingEntityTarget = match.groupValues[1] == "getStandingEyeHeight" ||
                javaClassExtendsAny(classDeclaration, javaLivingEntityBaseTypes(), javaInheritanceIndex)
            val targetMethodName = if (livingEntityTarget) "getDefaultDimensions" else "getDimensions"
            val targetAccess = if (livingEntityTarget) "protected" else "public"
            val superDimensionsCall = "super.$targetMethodName($poseName)"
            if (dimensionsName.isNotBlank()) {
                eyeExpression = Regex("""\b${Regex.escape(dimensionsName)}\.height\(\)""")
                    .replace(eyeExpression, "$superDimensionsCall.height()")
            }
            eyeExpression = eyeExpression
                .replace(Regex("""super\.getStandingEyeHeight\s*\(\s*${Regex.escape(poseName)}\s*,\s*[A-Za-z_$][\w$]*\s*\)"""), "$superDimensionsCall.eyeHeight()")
                .replace(Regex("""super\.getEyeHeight\s*\(\s*${Regex.escape(poseName)}\s*\)"""), "$superDimensionsCall.eyeHeight()")
                .replace(Regex("""this\.getBbHeight\s*\(\s*\)"""), "$superDimensionsCall.height()")

            val withoutLegacyMethod = result.removeRange(match.range.first, closeBrace + 1)
            val targetExistsOutsideMethod = Regex("""\b$targetMethodName\s*\(\s*Pose\s+""")
                .containsMatchIn(withoutLegacyMethod)
            if (targetExistsOutsideMethod) {
                val merged = mergeLegacyEyeHeightIntoExistingDimensionsMethod(
                    withoutLegacyMethod,
                    classDeclaration?.name,
                    targetMethodName,
                    poseName,
                    dimensionsName,
                    returnMatch.groupValues[1].trim()
                )
                if (merged != null) {
                    result = merged
                    cursor = match.range.first.coerceAtMost(result.length)
                    continue
                }
                cursor = closeBrace + 1
                continue
            }

            val replacement = """
@Override
$targetAccess EntityDimensions $targetMethodName(Pose $poseName) {
		return $superDimensionsCall.withEyeHeight($eyeExpression);
	}
            """.trimIndent()
            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return if (result != source) addImportIfMissing(result, "net.minecraft.world.entity.EntityDimensions") else result
    }

    private fun mergeLegacyEyeHeightIntoExistingDimensionsMethod(
        source: String,
        className: String?,
        targetMethodName: String,
        legacyPoseName: String,
        legacyDimensionsName: String,
        legacyEyeExpression: String
    ): String? {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\r?\n[ \t]*)*(?:public|protected)\s+EntityDimensions\s+$targetMethodName\s*\(\s*Pose\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
        )
        for (match in methodPattern.findAll(source)) {
            val targetClass = enclosingJavaClassDeclaration(source, match.range.first)
            if (className != null && targetClass?.name != className) continue
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace <= openBrace) continue
            val methodText = source.substring(match.range.first, closeBrace + 1)
            val returnMatches = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL)
                .findAll(methodText)
                .toList()
            if (returnMatches.size != 1) {
                val rewrittenMultiReturnMethod = rewriteDimensionsMethodReturnsWithLegacyEyeHeight(
                    methodText,
                    targetPoseName = match.groupValues[1],
                    legacyPoseName = legacyPoseName,
                    legacyEyeExpression = legacyEyeExpression
                ) ?: continue
                return source.substring(0, match.range.first) +
                    rewrittenMultiReturnMethod +
                    source.substring(closeBrace + 1)
            }
            val returnMatch = returnMatches.single()
            val returnedDimensions = returnMatch.groupValues[1].trim()
            val localName = uniqueLocalNameInScope(methodText, "dimensions")
            val targetPoseName = match.groupValues[1]
            var eyeExpression = legacyEyeExpression
            if (legacyPoseName != targetPoseName) {
                eyeExpression = Regex("""\b${Regex.escape(legacyPoseName)}\b""").replace(eyeExpression, targetPoseName)
            }
            if (legacyDimensionsName.isNotBlank()) {
                eyeExpression = Regex("""\b${Regex.escape(legacyDimensionsName)}\.height\(\)""")
                    .replace(eyeExpression, "$localName.height()")
            }
            eyeExpression = eyeExpression
                .replace(Regex("""super\.getStandingEyeHeight\s*\(\s*${Regex.escape(targetPoseName)}\s*,\s*[A-Za-z_$][\w$]*\s*\)"""), "$localName.eyeHeight()")
                .replace(Regex("""super\.getEyeHeight\s*\(\s*${Regex.escape(targetPoseName)}\s*\)"""), "$localName.eyeHeight()")
                .replace(Regex("""this\.getBbHeight\s*\(\s*\)"""), "$localName.height()")

            val returnStart = returnMatch.range.first
            val lineStart = methodText.lastIndexOf('\n', returnStart).let { if (it < 0) 0 else it + 1 }
            val indent = methodText.substring(lineStart, returnStart).takeWhile { it == ' ' || it == '\t' }
            val rewrittenReturn = "${indent}EntityDimensions $localName = $returnedDimensions;\n" +
                "${indent}return $localName.withEyeHeight($eyeExpression);"
            val rewrittenMethod = methodText.replaceRange(returnMatch.range, rewrittenReturn)
            return source.substring(0, match.range.first) +
                rewrittenMethod +
                source.substring(closeBrace + 1)
        }
        return null
    }

    private fun rewriteDimensionsMethodReturnsWithLegacyEyeHeight(
        methodText: String,
        targetPoseName: String,
        legacyPoseName: String,
        legacyEyeExpression: String
    ): String? {
        var eyeExpression = legacyEyeExpression
        if (legacyPoseName != targetPoseName) {
            eyeExpression = Regex("""\b${Regex.escape(legacyPoseName)}\b""").replace(eyeExpression, targetPoseName)
        }
        if (Regex("""\bsuper\.(?:getStandingEyeHeight|getEyeHeight)\s*\(""").containsMatchIn(eyeExpression) ||
            Regex("""\b[A-Za-z_$][\w$]*\.height\(\)""").containsMatchIn(eyeExpression) ||
            eyeExpression.contains("this.getBbHeight()")) {
            return null
        }

        var changed = false
        val rewritten = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL).replace(methodText) { match ->
            val returnedDimensions = match.groupValues[1].trim()
            if (returnedDimensions.contains(".withEyeHeight(")) {
                match.value
            } else {
                changed = true
                "return ($returnedDimensions).withEyeHeight($eyeExpression);"
            }
        }
        return if (changed) rewritten else null
    }

    private fun migrateLegacyNbtUtilsBlockPosCompoundSource(source: String): String {
        if (!source.contains("NbtUtils.readBlockPos(")) return source

        val readMigrated = replaceNbtUtilsBlockPosCall(source, "readBlockPos", "modporterReadLegacyBlockPos")
        if (readMigrated == source) return source

        val writeMigrated = replaceNbtUtilsBlockPosCall(readMigrated, "writeBlockPos", "modporterWriteLegacyBlockPos")
        var result = addLegacyBlockPosNbtHelpers(writeMigrated, needsWriteHelper = writeMigrated != readMigrated)
        result = addImportIfMissing(result, "net.minecraft.core.BlockPos")
        if (!Regex("""(?m)^[ \t]*import\s+net\.minecraft\.nbt\.\*;\s*$""").containsMatchIn(result)) {
            result = addImportIfMissing(result, "net.minecraft.nbt.CompoundTag")
        }
        val withoutNbtUtilsImport = removeImport(result, "net.minecraft.nbt.NbtUtils")
        if (!Regex("""\bNbtUtils\b""").containsMatchIn(withoutNbtUtilsImport)) {
            result = withoutNbtUtilsImport
        }
        return result
    }

    private fun replaceNbtUtilsBlockPosCall(source: String, methodName: String, replacementName: String): String {
        val token = "NbtUtils.$methodName("
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + "NbtUtils.$methodName".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) {
                break
            }
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size != 1) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }
            migrated.append(source, cursor, tokenIndex)
            migrated.append("$replacementName(${args[0].trim()})")
            cursor = closeParen + 1
            changed = true
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun addLegacyBlockPosNbtHelpers(source: String, needsWriteHelper: Boolean): String {
        if (source.contains("modporterReadLegacyBlockPos(CompoundTag tag)")) return source

        val writeHelper = if (needsWriteHelper) """

    private static CompoundTag modporterWriteLegacyBlockPos(BlockPos pos) {
        CompoundTag tag = new CompoundTag();
        tag.putInt("X", pos.getX());
        tag.putInt("Y", pos.getY());
        tag.putInt("Z", pos.getZ());
        return tag;
    }
""".trimEnd() else ""
        val helpers = """

    private static BlockPos modporterReadLegacyBlockPos(CompoundTag tag) {
        return new BlockPos(tag.getInt("X"), tag.getInt("Y"), tag.getInt("Z"));
    }$writeHelper
""".trimEnd()
        return insertBeforeLastClassBrace(source, helpers)
    }

    private fun migrateLegacySavedDataApis(
        source: String,
        savedDataClassNames: Set<String>,
        javaInheritanceIndex: JavaInheritanceIndex
    ): String {
        if (!source.contains("SavedData") &&
            !source.contains("computeIfAbsent(") &&
            savedDataClassNames.none { source.contains("$it.load(") }
        ) return source

        val localSavedDataClasses = collectJavaClassDeclarations(source)
            .filter { declaration -> javaClassExtendsAny(declaration, setOf("SavedData"), javaInheritanceIndex) }
            .map { it.name }
            .toSet()
        val knownSavedDataClasses = savedDataClassNames + localSavedDataClasses
        if (knownSavedDataClasses.isEmpty()) return source

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var needsHolderLookup = false
        var needsSavedData = false

        localSavedDataClasses.forEach { className ->
            result = Regex("""public\s+static\s+${Regex.escape(className)}\s+load\s*\(\s*CompoundTag\s+($id)\s*\)""")
                .replace(result) { match ->
                    needsHolderLookup = true
                    "public static $className load(CompoundTag ${match.groupValues[1]}, HolderLookup.Provider registries)"
                }
            val constructorPattern = Regex("""public\s+${Regex.escape(className)}\s*\(\s*CompoundTag\s+($id)\s*\)\s*\{""")
            val constructorMatch = constructorPattern.find(result)
            if (constructorMatch != null &&
                !Regex("""public\s+${Regex.escape(className)}\s*\(\s*CompoundTag\s+$id\s*,\s*HolderLookup\.Provider\s+$id\s*\)""")
                    .containsMatchIn(result)
            ) {
                val openBrace = result.indexOf('{', constructorMatch.range.last - 1)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                if (openBrace >= 0 && closeBrace >= 0) {
                    val tagName = constructorMatch.groupValues[1]
                    val overload = """

    public $className(CompoundTag $tagName, HolderLookup.Provider registries) {
        this($tagName);
    }
""".trimEnd()
                    result = result.substring(0, closeBrace + 1) + overload + result.substring(closeBrace + 1)
                    needsHolderLookup = true
                }
            }
        }

        if (localSavedDataClasses.isNotEmpty()) {
            val executableBeforeSaveMigration = maskJavaCommentsAndLiterals(result)
            val typeBlocksBeforeSaveMigration = javaTypeBlocks(result, executableBeforeSaveMigration)
            result = replaceExecutableRegex(result, Regex("""public\s+CompoundTag\s+save\s*\(\s*CompoundTag\s+($id)\s*\)""")) { match ->
                val owner = typeBlocksBeforeSaveMigration
                    .lastOrNull { match.range.first in it.bodyStart..it.end }
                    ?.name
                if (owner in localSavedDataClasses) {
                    needsHolderLookup = true
                    "public CompoundTag save(CompoundTag ${match.groupValues[1]}, HolderLookup.Provider registries)"
                } else {
                    match.value
                }
            }
        }

        result = rewriteJavaCall(result, "computeIfAbsent") { receiver, args ->
            if (args.size != 3) return@rewriteJavaCall null
            val loadReference = parseSimpleMethodReference(args[0]) ?: return@rewriteJavaCall null
            val supplierReference = parseSimpleMethodReference(args[1]) ?: return@rewriteJavaCall null
            if (loadReference.owner != supplierReference.owner) return@rewriteJavaCall null
            val validLoadMember = loadReference.member == "load" ||
                (loadReference.member == "new" && supplierReference.member == "new")
            if (!validLoadMember) return@rewriteJavaCall null
            if (loadReference.owner.substringAfterLast('.') !in knownSavedDataClasses) return@rewriteJavaCall null

            needsSavedData = true
            "$receiver.computeIfAbsent(new SavedData.Factory<>(${supplierReference.source}, ${loadReference.source}), ${args[2].trim()})"
        }

        knownSavedDataClasses.forEach { savedDataClass ->
            result = rewriteExecutableJavaCallWithOffset(result, "load") { receiver, args, offset ->
                if (receiver.substringAfterLast('.') != savedDataClass || args.size != 1) {
                    return@rewriteExecutableJavaCallWithOffset null
                }
                val registries = registryAccessExpressionAt(result, offset, javaInheritanceIndex)
                    ?: return@rewriteExecutableJavaCallWithOffset null
                "$receiver.load(${args[0].trim()}, $registries)"
            }
        }

        if (needsHolderLookup) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        }
        if (needsSavedData) {
            result = addImportIfMissing(result, "net.minecraft.world.level.saveddata.SavedData")
        }
        return result
    }

    private data class SimpleMethodReference(
        val owner: String,
        val member: String,
        val source: String
    )

    private fun parseSimpleMethodReference(expression: String): SimpleMethodReference? {
        val match = Regex("""^\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*::\s*([A-Za-z_$][\w$]*|new)\s*$""")
            .find(expression)
            ?: return null
        return SimpleMethodReference(
            owner = match.groupValues[1],
            member = match.groupValues[2],
            source = "${match.groupValues[1]}::${match.groupValues[2]}"
        )
    }

    private fun migrateDefaultLootTableResourceKeys(source: String): String {
        if (!source.contains("getDefaultLootTable()") || !source.contains("ResourceLocation")) return source
        var result = Regex("""\b(public|protected)\s+ResourceLocation\s+getDefaultLootTable\s*\(\s*\)""")
            .replace(source) { match -> "${match.groupValues[1]} ResourceKey<LootTable> getDefaultLootTable()" }
        if (result != source) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.LootTable")
            val withoutResourceLocation = removeImport(result, "net.minecraft.resources.ResourceLocation")
            if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocation)) {
                result = withoutResourceLocation
            }
        }
        return result
    }

    private fun migrateRandomizableContainerLootTableCalls(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("setLootTable(")) return source
        var result = rewriteExecutableJavaCall(source, "setLootTable") { receiver, args ->
            if (receiver != "RandomizableContainerBlockEntity" || args.size != 4) return@rewriteExecutableJavaCall null
            "RandomizableContainer.setBlockEntityLootTable(${args.joinToString(", ") { it.trim() }})"
        }
        var needsResourceKey = false
        var needsRegistries = false
        var needsLootTable = false
        result = rewriteExecutableJavaCallWithOffset(result, "setLootTable") { receiver, args, offset ->
            if (args.size != 2) return@rewriteExecutableJavaCallWithOffset null
            val receiverName = receiver.trim().takeIf { Regex("""[A-Za-z_$][\w$]*""").matches(it) }
                ?: return@rewriteExecutableJavaCallWithOffset null
            val receiverTypes = javaDeclaredSimpleTypeSets(result)[receiverName].orEmpty()
            val isRandomizableContainer = receiverTypes.any { type ->
                type == "RandomizableContainerBlockEntity" ||
                    javaInheritanceIndex.inherits(type, setOf("RandomizableContainerBlockEntity"))
            }
            if (!isRandomizableContainer) return@rewriteExecutableJavaCallWithOffset null
            val lootTable = args[0].trim()
            if (lootTable.startsWith("ResourceKey.create(") || isLocalLootTableResourceKeyExpression(result, lootTable)) {
                return@rewriteExecutableJavaCallWithOffset null
            }
            val lineStart = result.lastIndexOf('\n', offset).let { if (it < 0) 0 else it + 1 }
            val indent = result.substring(lineStart, offset).takeWhile { it == ' ' || it == '\t' }
            needsResourceKey = true
            needsRegistries = true
            needsLootTable = true
            "$receiver.setLootTable(ResourceKey.create(Registries.LOOT_TABLE, $lootTable));\n$indent$receiver.setLootTableSeed(${args[1].trim()})"
        }
        if (result != source) {
            if (result.contains("RandomizableContainer.setBlockEntityLootTable(")) {
                result = addImportIfMissing(result, "net.minecraft.world.RandomizableContainer")
            }
            if (needsResourceKey) result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            if (needsRegistries) result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
            if (needsLootTable) result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.LootTable")
            val withoutBlockEntityImport = removeImport(result, "net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity")
            if (!Regex("""\bRandomizableContainerBlockEntity\b""")
                    .containsMatchIn(maskJavaCommentsAndLiterals(withoutBlockEntityImport))) {
                result = withoutBlockEntityImport
            }
        }
        return result
    }

    private fun migrateItemEntityThrowerEntitySource(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".setThrower(") || !executableCode.contains(".getUUID()")) return source
        return rewriteExecutableJavaCall(source, "setThrower") { receiver, args ->
            if (receiver.isBlank() || args.size != 1) return@rewriteExecutableJavaCall null
            val entity = Regex("""^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.getUUID\(\)$""")
                .find(args[0].trim())
                ?.groupValues
                ?.get(1)
                ?: return@rewriteExecutableJavaCall null
            "$receiver.setThrower($entity)"
        }
    }

    private fun migrateLegacyBucketPickupAndLiquidContainerCalls(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("pickupBlock(") && !executableCode.contains("canPlaceLiquid(")) return source
        var changed = false
        var result = rewriteExecutableJavaCallWithOffset(source, "pickupBlock") { receiver, args, offset ->
            if (receiver.isBlank() || args.size != 3) return@rewriteExecutableJavaCallWithOffset null
            val player = nearestPlayerExpressionBeforeOffset(source, offset)
                ?: "null"
            changed = true
            "$receiver.pickupBlock($player, ${args.joinToString(", ") { it.trim() }})"
        }
        result = rewriteExecutableJavaCallWithOffset(result, "canPlaceLiquid") { receiver, args, offset ->
            if (receiver.isBlank() || args.size != 4) return@rewriteExecutableJavaCallWithOffset null
            val player = nearestPlayerExpressionBeforeOffset(result, offset)
                ?: "null"
            changed = true
            "$receiver.canPlaceLiquid($player, ${args.joinToString(", ") { it.trim() }})"
        }
        return if (changed) result else source
    }

    private fun nearestPlayerExpressionBeforeOffset(source: String, offset: Int): String? {
        val methodRange = enclosingMethodRange(source, offset) ?: return null
        val prefix = source.substring(methodRange.first, offset)
        val playerType = """(?:net\.minecraft\.server\.level\.)?ServerPlayer|(?:net\.minecraft\.world\.entity\.player\.)?Player"""
        val parameterPlayer = javaMethodRangesIncludingDefault(source)
            .firstOrNull { offset in it.range }
            ?.header
            ?.let(::javaMethodParameterText)
            ?.let(::singlePlayerParameterName)
        val candidates = mutableListOf<Pair<Int, String>>()
        Regex("""\b(?:$playerType)\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(prefix)
            .forEach { candidates += it.range.first to it.groupValues[1] }
        Regex("""\binstanceof\s+(?:$playerType)\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(prefix)
            .forEach { candidates += it.range.first to it.groupValues[1] }
        return candidates.maxByOrNull { it.first }?.second ?: parameterPlayer
    }

    private fun migrateLegacyMobTypeTagChecks(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains(".getMobType()") || !executableCode.contains("MobType.")) return source
        var changed = false
        var result = replaceExecutableRegex(
            source,
            Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.getMobType\(\)\s*([!=]=)\s*MobType\.(UNDEAD|ARTHROPOD)""")
        ) { match ->
            changed = true
            val target = match.groupValues[1]
            val comparison = match.groupValues[2]
            val tag = when (match.groupValues[3]) {
                "UNDEAD" -> "EntityTypeTags.UNDEAD"
                "ARTHROPOD" -> "EntityTypeTags.ARTHROPOD"
                else -> return@replaceExecutableRegex match.value
            }
            val expression = "$target.getType().is($tag)"
            if (comparison == "!=") "!$expression" else expression
        }
        result = replaceExecutableRegex(
            result,
            Regex("""MobType\.(UNDEAD|ARTHROPOD)\s*([!=]=)\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.getMobType\(\)""")
        ) { match ->
            changed = true
            val tag = when (match.groupValues[1]) {
                "UNDEAD" -> "EntityTypeTags.UNDEAD"
                "ARTHROPOD" -> "EntityTypeTags.ARTHROPOD"
                else -> return@replaceExecutableRegex match.value
            }
            val comparison = match.groupValues[2]
            val target = match.groupValues[3]
            val expression = "$target.getType().is($tag)"
            if (comparison == "!=") "!$expression" else expression
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.tags.EntityTypeTags")
        val withoutMobTypeImport = removeImport(result, "net.minecraft.world.entity.MobType")
        if (!maskJavaCommentsAndLiterals(withoutMobTypeImport).contains("MobType.")) {
            result = withoutMobTypeImport
        }
        return result
    }

    private fun migrateContainerEntityLootTableResourceKeys(source: String): String {
        if (!source.contains("ContainerEntity")) return source
        var result = source
        result = Regex("""(?m)^([ \t]*(?:@Nullable\s*)?(?:private|protected|public)\s+)ResourceLocation(\s+lootTable\s*;)""")
            .replace(result, "$1ResourceKey<LootTable>$2")
        result = Regex("""void\s+setLootTable\s*\(\s*((?:@\w+(?:\.\w+)*\s+)*)ResourceLocation\s+([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result, "void setLootTable($1ResourceKey<LootTable> $2)")
        result = Regex("""\baddChestVehicleSaveData\(\s*([^,)]+)\s*\)""")
            .replace(result) { match -> "addChestVehicleSaveData(${match.groupValues[1].trim()}, this.registryAccess())" }
        result = Regex("""\breadChestVehicleSaveData\(\s*([^,)]+)\s*\)""")
            .replace(result) { match -> "readChestVehicleSaveData(${match.groupValues[1].trim()}, this.registryAccess())" }
        if (result != source) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.LootTable")
            val withoutResourceLocation = removeImport(result, "net.minecraft.resources.ResourceLocation")
            if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocation)) {
                result = withoutResourceLocation
            }
        }
        return result
    }

    private fun migrateLegacyStructureStartCustomLoads(source: String): String {
        if (!source.contains("StructureStart") &&
            !source.contains("PiecesContainer") &&
            !source.contains("loadAdditional(")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var changed = false

        if (Regex("""\bextends\s+(?:[A-Za-z_$][\w$]*\.)?StructureStart\b""").containsMatchIn(result)) {
            result = Regex(
                """(?m)^([ \t]*)(?:@Override\s*\r?\n[ \t]*)?(?:protected|public)\s+void\s+loadAdditional\s*\(\s*CompoundTag\s+($id)\s*,\s*(?:net\.minecraft\.core\.)?HolderLookup\.Provider\s+$id\s*\)"""
            ).replace(result) { match ->
                changed = true
                "${match.groupValues[1]}public void loadFromTag(CompoundTag ${match.groupValues[2]})"
            }
        }

        val structureStartVariables = Regex(
            """\b((?:[A-Za-z_$][\w$]*\.)*$id(?:StructureStart)?)\s+($id)\s*=\s*new\s+(?:[A-Za-z_$][\w$]*\.)*$id(?:StructureStart)?\s*\([^;]*\b(?:PiecesContainer|pieces)\b[^;]*\)"""
        ).findAll(result)
            .mapNotNull { match ->
                val typeName = match.groupValues[1].substringAfterLast('.')
                val variable = match.groupValues[2]
                variable.takeIf { typeName == "StructureStart" || typeName.endsWith("StructureStart") }
            }
            .toSet()
        val compoundTagVariables = Regex("""\bCompoundTag\s+($id)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()

        if (structureStartVariables.isNotEmpty() && compoundTagVariables.isNotEmpty()) {
            for (startVariable in structureStartVariables) {
                for (tagVariable in compoundTagVariables) {
                    val migrated = Regex("""\b${Regex.escape(startVariable)}\.load\(\s*${Regex.escape(tagVariable)}\s*\)""")
                        .replace(result, "$startVariable.loadFromTag($tagVariable)")
                    if (migrated != result) {
                        changed = true
                        result = migrated
                    }
                }
            }
        }

        if (changed && !Regex("""\bHolderLookup\b""").containsMatchIn(removeImport(result, "net.minecraft.core.HolderLookup"))) {
            result = removeImport(result, "net.minecraft.core.HolderLookup")
        }
        return result
    }

    private fun migrateLargeFireballVec3Constructors(source: String): String {
        if (!source.contains("LargeFireball") && !source.contains("Fireball") && !source.contains("AbstractHurtingProjectile")) return source
        var changed = false
        var result = Regex("""new\s+LargeFireball\(\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^)]+?)\s*\)""")
            .replace(source) { match ->
                changed = true
                val level = match.groupValues[1].trim()
                val owner = match.groupValues[2].trim()
                val x = match.groupValues[3].trim()
                val y = match.groupValues[4].trim()
                val z = match.groupValues[5].trim()
                val power = match.groupValues[6].trim()
                "new LargeFireball($level, $owner, new Vec3($x, $y, $z).normalize(), $power)"
        }
        if (source.contains("extends LargeFireball")) {
            result = Regex("""super\(\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^)]+?)\s*\)""")
                .replace(result) { match ->
                    changed = true
                    val level = match.groupValues[1].trim()
                    val owner = match.groupValues[2].trim()
                    val x = match.groupValues[3].trim()
                    val y = match.groupValues[4].trim()
                    val z = match.groupValues[5].trim()
                    val power = match.groupValues[6].trim()
                    "super($level, $owner, new Vec3($x, $y, $z), $power)"
                }
        }
        if (Regex("""\bextends\s+(?:Fireball|AbstractHurtingProjectile)\b""").containsMatchIn(source)) {
            val declaredTypes = javaDeclaredSimpleTypeSets(result)
            result = rewriteSuperConstructorCalls(result) { args ->
                if (args.size == 8) {
                    changed = true
                    "super(${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()}, ${args[3].trim()}, new Vec3(${args[4].trim()}, ${args[5].trim()}, ${args[6].trim()}), ${args[7].trim()})"
                } else {
                    null
                }
            }
            result = Regex("""super\(\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^)]+?)\s*\)""")
                .replace(result) { match ->
                    val type = match.groupValues[1].trim()
                    val owner = match.groupValues[2].trim()
                    val ownerTypes = declaredTypes[owner.substringBefore('.').trim()].orEmpty()
                    if (ownerTypes.none { it == "LivingEntity" || it == "Player" }) {
                        return@replace match.value
                    }
                    changed = true
                    val x = match.groupValues[3].trim()
                    val y = match.groupValues[4].trim()
                    val z = match.groupValues[5].trim()
                    val level = match.groupValues[6].trim()
                    "super($type, $owner, new Vec3($x, $y, $z), $level)"
                }
        }
        return if (changed) addImportIfMissing(result, "net.minecraft.world.phys.Vec3") else source
    }

    private fun migrateLegacySignBlockConstructors(source: String): String {
        if (!source.contains("WoodType") ||
            !(source.contains("extends StandingSignBlock") ||
                source.contains("extends WallSignBlock") ||
                source.contains("extends CeilingHangingSignBlock") ||
                source.contains("extends WallHangingSignBlock"))) {
            return source
        }
        var result = source
        Regex(
            """\b(?:public|protected|private)?\s*[A-Za-z_$][\w$]*\s*\(\s*(?:(?:BlockBehaviour\.)?Properties)\s+([A-Za-z_$][\w$]*)\s*,\s*WoodType\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).findAll(source).forEach { constructor ->
            val propertiesName = constructor.groupValues[1]
            val woodTypeName = constructor.groupValues[2]
            result = result.replace("super($propertiesName, $woodTypeName);", "super($woodTypeName, $propertiesName);")
        }
        return result
    }

    private fun migrateLegacyPacketDistributorSends(source: String): String {
        if (!source.contains("PacketDistributor.") && !source.contains(".toVanillaPacket(")) return source

        var result = source
        var needsChunkPos = false
        var needsServerLevel = false
        val nearTargets = linkedMapOf<String, LegacyNearTargetPoint>()
        result = Regex(
            """(?m)^[ \t]*PacketDistributor\.TargetPoint\s+([A-Za-z_$][\w$]*)\s*=\s*new\s+PacketDistributor\.TargetPoint\s*\((.*)\)\s*;\s*\r?\n"""
        ).replace(result) { match ->
            val args = splitTopLevelJavaArgs(match.groupValues[2])
            val target = legacyNearTargetPoint(args)
            if (target != null) {
                nearTargets[match.groupValues[1]] = target
                ""
            } else {
                match.value
            }
        }
        result = migrateSimpleChannelSendCalls(result) { distributor, target, payload ->
            when (distributor) {
                "TRACKING_ENTITY" -> "PacketDistributor.sendToPlayersTrackingEntity($target, $payload)"
                "TRACKING_ENTITY_AND_SELF" -> "PacketDistributor.sendToPlayersTrackingEntityAndSelf($target, $payload)"
                "PLAYER" -> "PacketDistributor.sendToPlayer($target, $payload)"
                "SERVER" -> "PacketDistributor.sendToServer($payload)"
                "ALL" -> "PacketDistributor.sendToAllPlayers($payload)"
                "NEAR" -> {
                    val nearTarget = nearTargets[target] ?: legacyNearTargetPointExpression(target)
                    if (nearTarget != null) {
                        needsServerLevel = needsServerLevel || nearTarget.levelNeedsCast(result)
                        "PacketDistributor.sendToPlayersNear(${nearTarget.serverLevelExpression(result)}, null, ${nearTarget.x}, ${nearTarget.y}, ${nearTarget.z}, ${nearTarget.radius}, $payload)"
                    } else {
                        null
                    }
                }
                "TRACKING_CHUNK" -> {
                    val chunkAt = Regex("""^(.+)\.getChunkAt\((.+)\)$""").find(target)
                    if (chunkAt != null) {
                        needsChunkPos = true
                        "PacketDistributor.sendToPlayersTrackingChunk(${chunkAt.groupValues[1].trim()}, new ChunkPos(${chunkAt.groupValues[2].trim()}), $payload)"
                    } else {
                        null
                    }
                }
                else -> null
            }
        }
        result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.toVanillaPacket\(\s*(new\s+[A-Za-z_$][\w$]*\([^;]+?\))\s*,\s*NetworkDirection\.PLAY_TO_CLIENT\s*\)"""
        ).replace(result) { match -> "${match.groupValues[2]}.toVanillaClientbound()" }
        result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.toVanillaPacket\(\s*(new\s+[A-Za-z_$][\w$]*\([^;]+?\))\s*,\s*NetworkDirection\.PLAY_TO_SERVER\s*\)"""
        ).replace(result) { match -> "${match.groupValues[2]}.toVanillaServerbound()" }
        if (needsChunkPos) {
            result = addImportIfMissing(result, "net.minecraft.world.level.ChunkPos")
        }
        if (needsServerLevel) {
            result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        }
        if (result.contains("toVanillaClientbound()") || result.contains("toVanillaServerbound()")) {
            result = removeImport(result, "net.neoforged.neoforge.network.NetworkDirection")
            result = removeImport(result, "net.minecraftforge.network.NetworkDirection")
        }
        return result
    }

    private data class LegacyNearTargetPoint(
        val x: String,
        val y: String,
        val z: String,
        val radius: String,
        val levelExpression: String
    ) {
        fun levelNeedsCast(source: String): Boolean =
            !Regex("""\bServerLevel\s+${Regex.escape(levelExpression)}\b""").containsMatchIn(source)

        fun serverLevelExpression(source: String): String =
            if (levelNeedsCast(source)) "(ServerLevel) $levelExpression" else levelExpression
    }

    private fun migrateSimpleChannelSendCalls(
        source: String,
        replacementFor: (distributor: String, target: String, payload: String) -> String?
    ): String {
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        val token = ".send("
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".send".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val receiverStart = findDottedReceiverStart(source, tokenIndex)
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val distributor = args.getOrNull(0)?.let(::parsePacketDistributorTarget)
            val payload = args.getOrNull(1)?.trim()
            if (receiver.isNotEmpty() && args.size == 2 && distributor != null && payload != null) {
                val replacement = replacementFor(distributor.first, distributor.second, payload)
                if (replacement != null) {
                    migrated.append(source, cursor, receiverStart)
                    migrated.append(replacement)
                    cursor = closeParen + 1
                    changed = true
                    continue
                }
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun findDottedReceiverStart(source: String, tokenIndex: Int): Int {
        var index = tokenIndex - 1
        while (index >= 0) {
            val c = source[index]
            if (c.isLetterOrDigit() || c == '_' || c == '$' || c == '.') {
                index--
            } else {
                break
            }
        }
        return index + 1
    }

    private fun parsePacketDistributorTarget(expression: String): Pair<String, String>? {
        val trimmed = expression.trim()
        Regex("""^PacketDistributor\.([A-Z_]+)\.with\(\s*\(\)\s*->\s*(.+)\s*\)$""")
            .find(trimmed)
            ?.let { return it.groupValues[1] to it.groupValues[2].trim() }
        Regex("""^PacketDistributor\.([A-Z_]+)\.noArg\(\s*\)$""")
            .find(trimmed)
            ?.let { return it.groupValues[1] to "" }
        return null
    }

    private fun legacyNearTargetPointExpression(expression: String): LegacyNearTargetPoint? {
        val trimmed = expression.trim()
        if (!trimmed.startsWith("new PacketDistributor.TargetPoint(")) return null
        val openParen = trimmed.indexOf('(')
        if (openParen < 0) return null
        val closeParen = findMatchingParen(trimmed, openParen)
        if (closeParen < 0) return null
        return legacyNearTargetPoint(splitTopLevelJavaArgs(trimmed.substring(openParen + 1, closeParen)))
    }

    private fun legacyNearTargetPoint(args: List<String>): LegacyNearTargetPoint? {
        if (args.size != 5) return null
        val dimension = args[4].trim()
        val level = Regex("""^(.+)\.dimension\(\)$""")
            .find(dimension)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: return null
        return LegacyNearTargetPoint(
            x = args[0].trim(),
            y = args[1].trim(),
            z = args[2].trim(),
            radius = args[3].trim(),
            levelExpression = level
        )
    }

    private fun migrateLegacyEventHooks121(source: String): String {
        if (!source.contains("EventHooks.")) return source

        var result = removeRemovedBucketUseHookGuard(source)
        result = result.replace("EventHooks.getMobGriefingEvent(", "EventHooks.canEntityGrief(")
        if (result.contains("EventHooks.onFinalizeSpawn(")) {
            result = result.replace("EventHooks.onFinalizeSpawn(", "EventHooks.finalizeMobSpawn(")
            result = migrateMethodCalls(result, "EventHooks.finalizeMobSpawn") { args ->
                if (args.size == 6) args.take(5) else args
            }
        }
        result = migrateEventHooksDoPlayerHarvestCheck(result)
        return result
    }

    private data class HarvestCheckBlockStateAccess(val blockGetter: String, val blockPos: String)

    private fun migrateEventHooksDoPlayerHarvestCheck(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("EventHooks.doPlayerHarvestCheck(")) return source
        val methodRanges = javaMethodRangesIncludingDefault(executableCode)
        val edits = mutableListOf<Pair<IntRange, String>>()
        val token = ".doPlayerHarvestCheck("
        var cursor = 0
        while (true) {
            val tokenIndex = executableCode.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".doPlayerHarvestCheck".length
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(executableCode, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            if (receiver != "EventHooks") {
                cursor = closeParen + 1
                continue
            }
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size != 3) {
                cursor = closeParen + 1
                continue
            }
            val method = methodRanges.firstOrNull { tokenIndex in it.range }
            if (method == null) {
                cursor = closeParen + 1
                continue
            }
            val access = resolveHarvestCheckBlockStateAccess(
                stateArgument = args[1].trim(),
                methodSource = source.substring(method.range),
                executableMethod = executableCode.substring(method.range),
                callOffsetInMethod = tokenIndex - method.range.first
            )
            if (access != null) {
                edits += receiverStart..closeParen to
                    "EventHooks.doPlayerHarvestCheck(${args[0].trim()}, ${args[1].trim()}, ${access.blockGetter}, ${access.blockPos})"
            }
            cursor = closeParen + 1
        }
        return applyStringEdits(source, edits)
    }

    private fun resolveHarvestCheckBlockStateAccess(
        stateArgument: String,
        methodSource: String,
        executableMethod: String,
        callOffsetInMethod: Int
    ): HarvestCheckBlockStateAccess? {
        harvestCheckBlockStateAccessFromExpression(stateArgument)?.let { return it }
        val stateVariable = Regex("""[A-Za-z_$][\w$]*""").matchEntire(stateArgument)?.value ?: return null
        val escapedState = Regex.escape(stateVariable)
        val candidates = (
            Regex("""(?m)\b(?:final\s+)?(?:BlockState|var)\s+$escapedState\s*=\s*""").findAll(executableMethod) +
                Regex("""(?m)(?<![.\w$])$escapedState\s*=\s*(?!=)""").findAll(executableMethod)
            )
            .filter { it.range.first < callOffsetInMethod }
            .distinctBy { it.range.last }
            .sortedBy { it.range.first }
            .toList()
        val lastAssignment = candidates.lastOrNull() ?: return null
        val expressionStart = lastAssignment.range.last + 1
        val expressionEnd = findJavaStatementSemicolon(executableMethod, expressionStart)
        if (expressionEnd < 0 || expressionEnd > callOffsetInMethod) return null
        val expression = methodSource.substring(expressionStart, expressionEnd).trim()
        return harvestCheckBlockStateAccessFromExpression(expression)
    }

    private fun harvestCheckBlockStateAccessFromExpression(expression: String): HarvestCheckBlockStateAccess? {
        val trimmed = expression.trim()
        val token = ".getBlockState("
        val tokenIndex = trimmed.indexOf(token)
        if (tokenIndex < 0) return null
        val openParen = tokenIndex + ".getBlockState".length
        val closeParen = findMatchingParen(trimmed, openParen)
        if (closeParen < 0 || trimmed.substring(closeParen + 1).isNotBlank()) return null
        val receiverStart = findExpressionReceiverStart(trimmed, tokenIndex)
        if (receiverStart < 0 || receiverStart >= tokenIndex) return null
        val args = splitTopLevelJavaArgs(trimmed.substring(openParen + 1, closeParen))
        if (args.size != 1) return null
        return HarvestCheckBlockStateAccess(
            blockGetter = trimmed.substring(receiverStart, tokenIndex).trim(),
            blockPos = args[0].trim()
        )
    }

    private fun findJavaStatementSemicolon(source: String, start: Int): Int {
        var i = start
        var parenDepth = 0
        var braceDepth = 0
        var bracketDepth = 0
        while (i < source.length) {
            when (source[i]) {
                '"' -> i = skipJavaStringLiteral(source, i)
                '\'' -> i = skipJavaCharLiteral(source, i)
                '(' -> parenDepth++
                ')' -> if (parenDepth > 0) parenDepth--
                '{' -> braceDepth++
                '}' -> if (braceDepth > 0) braceDepth--
                '[' -> bracketDepth++
                ']' -> if (bracketDepth > 0) bracketDepth--
                ';' -> if (parenDepth == 0 && braceDepth == 0 && bracketDepth == 0) return i
            }
            i++
        }
        return -1
    }

    private fun removeRemovedBucketUseHookGuard(source: String): String {
        if (!source.contains("EventHooks.onBucketUse(")) return source
        var result = source
        val inlineGuard = Regex(
            """(?m)^[ \t]*(?:(?:var|[\w.]+(?:\s*<[^=\r\n;]+>)?)\s+)([A-Za-z_$][\w$]*)\s*=\s*(?:net\.neoforged\.neoforge\.event\.)?EventHooks\.onBucketUse\s*\([^;\r\n]*\);\s*\r?\n[ \t]*if\s*\(\s*\1\s*!=\s*null\s*\)\s*return\s+\1\s*;\s*\r?\n?"""
        )
        result = inlineGuard.replace(result, "")
        val blockGuard = Regex(
            """(?m)^[ \t]*(?:(?:var|[\w.]+(?:\s*<[^=\r\n;]+>)?)\s+)([A-Za-z_$][\w$]*)\s*=\s*(?:net\.neoforged\.neoforge\.event\.)?EventHooks\.onBucketUse\s*\([^;\r\n]*\);\s*\r?\n[ \t]*if\s*\(\s*\1\s*!=\s*null\s*\)\s*\{\s*\r?\n[ \t]*return\s+\1\s*;\s*\r?\n[ \t]*\}\s*\r?\n?"""
        )
        result = blockGuard.replace(result, "")
        if (!Regex("""\bEventHooks\.""").containsMatchIn(result)) {
            result = removeImport(result, "net.neoforged.neoforge.event.EventHooks")
        }
        return cleanupRedundantBlankLines(result)
    }

    private fun migrateLegacyLootAndRegistryAccess(
        source: String,
        legacyLootTableResourceLocationReferences: Set<String>
    ): String {
        var result = source
        var needsBlocks = false
        var needsResourceKey = false
        var needsRegistries = false
        var needsLootTable = false

        if (result.contains(".getLootData()")) {
            result = result.replace(".getLootData()", ".reloadableRegistries()")
        }

        if (result.contains(".getLootTable(")) {
            result = rewriteJavaCall(result, "getLootTable") { receiver, args ->
                if (args.size != 1) return@rewriteJavaCall null
                val lootTable = args[0].trim()
                val nestedLootTableKey = unwrapLootTableResourceKeyCreate(lootTable)
                if (nestedLootTableKey != null &&
                    (isLootTableResourceKeyExpression(nestedLootTableKey, legacyLootTableResourceLocationReferences) ||
                        isLocalLootTableResourceKeyExpression(result, nestedLootTableKey))) {
                    return@rewriteJavaCall "$receiver.getLootTable($nestedLootTableKey)"
                }
                if (isLocalLootTableResourceKeyExpression(result, lootTable)) {
                    return@rewriteJavaCall null
                }
                if (isLootTableResourceKeyExpression(lootTable, legacyLootTableResourceLocationReferences)) {
                    null
                } else {
                    needsResourceKey = true
                    needsRegistries = true
                    "$receiver.getLootTable(ResourceKey.create(Registries.LOOT_TABLE, $lootTable))"
                }
            }
        }

        if (maskJavaCommentsAndLiterals(result).contains("new AdvancementRewards(")) {
            result = rewriteExecutableJavaNew(result, "AdvancementRewards") { args ->
                if (args.size != 4) return@rewriteExecutableJavaNew null
                val lootList = legacyResourceLocationArrayToList(args[1]) { entry ->
                    if (isLootTableResourceKeyExpression(entry, legacyLootTableResourceLocationReferences)) {
                        entry
                    } else {
                        needsResourceKey = true
                        needsRegistries = true
                        "ResourceKey.create(Registries.LOOT_TABLE, $entry)"
                    }
                } ?: return@rewriteExecutableJavaNew null
                val recipeList = legacyResourceLocationArrayToList(args[2]) { it } ?: return@rewriteExecutableJavaNew null
                "new AdvancementRewards(${args[0].trim()}, $lootList, $recipeList, ${args[3].trim()})"
            }
        }

        if (result.contains("LootTableIdCondition.builder(")) {
            result = rewriteJavaCall(result, "builder") { receiver, args ->
                if (receiver != "LootTableIdCondition" || args.size != 1) return@rewriteJavaCall null
                val lootTable = args[0].trim()
                if (!isLootTableResourceKeyExpression(lootTable, legacyLootTableResourceLocationReferences) || lootTable.endsWith(".location()")) {
                    null
                } else {
                    "$receiver.builder($lootTable.location())"
                }
            }
        }

        if (result.contains("LootTableSubProvider") &&
            result.contains("BiConsumer<ResourceLocation, LootTable.Builder>")) {
            result = result.replace(
                "BiConsumer<ResourceLocation, LootTable.Builder>",
                "BiConsumer<ResourceKey<LootTable>, LootTable.Builder>"
            )
            needsResourceKey = true
            needsLootTable = true
            result = rewriteExecutableJavaCall(result, "accept") { receiver, args ->
                if (receiver.isBlank() || args.size != 2) return@rewriteExecutableJavaCall null
                val key = args[0].trim()
                if (key.startsWith("ResourceKey.") ||
                    key.contains("ResourceKey.create(") ||
                    isLootTableResourceKeyExpression(key, legacyLootTableResourceLocationReferences)) {
                    null
                } else {
                    needsResourceKey = true
                    needsRegistries = true
                    "$receiver.accept(ResourceKey.create(Registries.LOOT_TABLE, $key), ${args[1].trim()})"
                }
            }
            val withoutResourceLocation = removeImport(result, "net.minecraft.resources.ResourceLocation")
            if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocation)) {
                result = withoutResourceLocation
            }
        }

        if (result.contains("NestedLootTable.lootTableReference(")) {
            result = migrateMethodCalls(result, "NestedLootTable.lootTableReference") { args ->
                if (args.size == 1 && !args[0].contains("ResourceKey.create(")) {
                    needsResourceKey = true
                    needsRegistries = true
                    listOf("ResourceKey.create(Registries.LOOT_TABLE, ${args[0].trim()})")
                } else {
                    args
                }
            }
        }

        if (result.contains("ResourceLocation") && result.contains("register(")) {
            val beforeLootKeys = result
            result = migrateLegacyLootTableResourceLocationRegistry(result, legacyLootTableResourceLocationReferences)
            if (result != beforeLootKeys) {
                needsResourceKey = true
                needsRegistries = true
                needsLootTable = true
            }
        }

        if (result.contains("ResourceLocation") &&
            (result.contains("LootTable") || result.contains("getLootLocation("))) {
            val beforeLootMethods = result
            result = Regex(
                """(?m)^([ \t]*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@\w+(?:\([^)]*\))?\s+)*)ResourceLocation(\s+[A-Za-z_$][\w$]*LootTable\s*\()"""
            ).replace(result) { match ->
                needsResourceKey = true
                needsLootTable = true
                "${match.groupValues[1]}ResourceKey<LootTable>${match.groupValues[2]}"
            }
            result = Regex(
                """(?m)^([ \t]*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@\w+(?:\([^)]*\))?\s+)*)ResourceLocation(\s+get[A-Za-z_$][\w$]*LootTable\s*\()"""
            ).replace(result) { match ->
                needsResourceKey = true
                needsLootTable = true
                "${match.groupValues[1]}ResourceKey<LootTable>${match.groupValues[2]}"
            }
            result = Regex(
                """(?m)^([ \t]*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@\w+(?:\([^)]*\))?\s+)*)ResourceLocation(\s+get[A-Za-z_$][\w$]*LootLocation\s*\()"""
            ).replace(result) { match ->
                needsResourceKey = true
                needsLootTable = true
                "${match.groupValues[1]}ResourceKey<LootTable>${match.groupValues[2]}"
            }
            result = Regex(
                """(?m)^([ \t]*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@\w+(?:\([^)]*\))?\s+)*)ResourceLocation(\s+getLootLocation\s*\()"""
            ).replace(result) { match ->
                needsResourceKey = true
                needsLootTable = true
                "${match.groupValues[1]}ResourceKey<LootTable>${match.groupValues[2]}"
            }
            if (result != beforeLootMethods) {
                val withoutResourceLocation = removeImport(result, "net.minecraft.resources.ResourceLocation")
                if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocation)) {
                    result = withoutResourceLocation
                }
            }
        }

        result = Regex(
            """BuiltInRegistries\.BLOCK\.tags\(\)\.getTag\(([^)]+)\)\.getRandomElement\(((?:[^()]|\([^()]*\))+)\)\.get\(\)\.defaultBlockState\(\)"""
        ).replace(result) { match ->
            needsBlocks = true
            "BuiltInRegistries.BLOCK.getRandomElementOf(${match.groupValues[1].trim()}, ${match.groupValues[2].trim()}).map(holder -> holder.value().defaultBlockState()).orElseGet(Blocks.AIR::defaultBlockState)"
        }
        result = result.replace("Objects.requireNonNull(BuiltInRegistries.BLOCK.tags()).getTagNames()", "BuiltInRegistries.BLOCK.getTagNames()")
        result = Regex("""Objects\.requireNonNull\(BuiltInRegistries\.BLOCK\.tags\(\)\)\.getTag\(([^)]+)\)""")
            .replace(result) { match -> "BuiltInRegistries.BLOCK.getOrCreateTag(${match.groupValues[1].trim()})" }
        result = Regex("""BuiltInRegistries\.BLOCK\.tags\(\)\.getTag\(([^)]+)\)""")
            .replace(result) { match -> "BuiltInRegistries.BLOCK.getOrCreateTag(${match.groupValues[1].trim()})" }

        if (needsBlocks) result = addImportIfMissing(result, "net.minecraft.world.level.block.Blocks")
        if (needsResourceKey) result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
        if (needsRegistries) result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        if (needsLootTable || (needsResourceKey && result.contains("ResourceKey<LootTable>"))) {
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.LootTable")
        }
        return result
    }

    private fun collectLegacyLootTableResourceLocationReferences(javaFiles: List<Path>): Set<String> {
        val references = linkedSetOf<String>()
        fun addReference(expression: String) {
            val normalized = expression
                .trim()
                .removeSuffix(".location()")
                .removeSurrounding("(", ")")
                .trim()
            if (Regex("""(?:[A-Za-z_$][\w$]*\.)?(?:[A-Z][A-Z0-9_]*|[A-Za-z_$][\w$]*\(\))""").matches(normalized)) {
                references += normalized
            }
        }

        javaFiles.forEach { javaFile ->
            val source = javaFile.readText()
            if (!source.contains("LootTable")) return@forEach
            var cursor = 0
            while (true) {
                val match = Regex("""new\s+LootTableProvider\s*\(""").find(source, cursor) ?: break
                val openParen = source.indexOf('(', match.range.last)
                val closeParen = findMatchingParen(source, openParen)
                if (closeParen < 0) {
                    cursor = match.range.last + 1
                    continue
                }
                val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
                if (args.size >= 2) addReference(args[1])
                cursor = closeParen + 1
            }
            Regex("""register\.accept\s*\(\s*([^,]+?)\s*,\s*LootTable\.lootTable\s*\(""")
                .findAll(source)
                .forEach { addReference(it.groupValues[1]) }
            Regex("""NestedLootTable\.lootTableReference\s*\(\s*([^)]+?)\s*\)""")
                .findAll(source)
                .forEach { addReference(it.groupValues[1]) }
            Regex("""LootTableIdCondition\.builder\s*\(\s*([^)]+?)\s*\)""")
                .findAll(source)
                .forEach { addReference(it.groupValues[1]) }
            Regex("""new\s+ResourceLocation\s*\[\s*]\s*\{([^}]*)}""")
                .findAll(source)
                .forEach { match ->
                    splitTopLevelJavaArgs(match.groupValues[1]).forEach(::addReference)
                }
        }
        return references
    }

    private fun migrateLegacyLootTableResourceLocationRegistry(
        source: String,
        legacyLootTableResourceLocationReferences: Set<String>
    ): String {
        if (!Regex("""(?m)^\s*private\s+static\s+ResourceLocation\s+register\s*\(""").containsMatchIn(source) &&
            !Regex("""(?m)^\s*(?:public|protected|private)?\s*static\s+final\s+Set\s*<\s*ResourceLocation\s*>""").containsMatchIn(source)) {
            return source
        }

        var result = source
        val ownerClass = classNameOfJavaSource(source) ?: return source
        val ownerPackage = packageNameOf(source)
        fun isProvenLootReference(fieldName: String): Boolean {
            if (fieldName in legacyLootTableResourceLocationReferences) return true
            if (ownerClass.isNotBlank() && "$ownerClass.$fieldName" in legacyLootTableResourceLocationReferences) return true
            if (ownerClass.isNotBlank() && ownerPackage.isNotBlank() &&
                "$ownerPackage.$ownerClass.$fieldName" in legacyLootTableResourceLocationReferences) {
                return true
            }
            return false
        }
        val staticResourceLocationSetPattern = Regex(
            """(?m)^([ \t]*(?:public|protected|private)?\s*static\s+final\s+)Set\s*<\s*ResourceLocation\s*>(\s+([A-Za-z_$][\w$]*)\s*=)"""
        )
        val resourceLocationSetNames = staticResourceLocationSetPattern.findAll(result)
            .map { it.groupValues[3] }
            .toSet()
        val registerSetNames = legacyResourceLocationRegisterSets(result, resourceLocationSetNames)
        val setAliases = legacyResourceLocationSetAliases(result, resourceLocationSetNames)
        val setReturnMethods = legacyResourceLocationSetReturnMethods(result, resourceLocationSetNames)
        fun isProvenLootSetReference(fieldName: String): Boolean {
            if (isProvenLootReference(fieldName)) return true
            return setReturnMethods
                .filterValues { returnedField -> returnedField == fieldName }
                .keys
                .any { methodName ->
                    "$methodName()" in legacyLootTableResourceLocationReferences ||
                        "$ownerClass.$methodName()" in legacyLootTableResourceLocationReferences ||
                        (ownerPackage.isNotBlank() &&
                            "$ownerPackage.$ownerClass.$methodName()" in legacyLootTableResourceLocationReferences)
                }
        }
        fun expandSetAliases(seed: Set<String>): Set<String> {
            val expanded = seed.toCollection(linkedSetOf())
            var changed: Boolean
            do {
                changed = false
                setAliases.forEach { (alias, target) ->
                    if (target in expanded && expanded.add(alias)) changed = true
                    if (alias in expanded && expanded.add(target)) changed = true
                }
            } while (changed)
            return expanded
        }
        val directlyProvenSetNames = resourceLocationSetNames.filterTo(linkedSetOf(), ::isProvenLootReference)
        val provenSetNames = registerSetNames.filterTo(linkedSetOf(), ::isProvenLootSetReference) + directlyProvenSetNames
        val provenRegisteredFieldNames = Regex(
            """(?m)^\s*public\s+static\s+final\s+ResourceLocation\s+([A-Z0-9_]+)\s*=\s*register\("""
        ).findAll(result)
            .map { it.groupValues[1] }
            .filterTo(linkedSetOf(), ::isProvenLootReference)
        val baseLootSetNames = when {
            provenSetNames.isNotEmpty() -> provenSetNames
            provenRegisteredFieldNames.isNotEmpty() -> registerSetNames
            else -> emptySet()
        }
        val lootSetNames = expandSetAliases(baseLootSetNames)
        if (lootSetNames.isEmpty()) return source
        if (!Regex("""(?m)^\s*public\s+static\s+final\s+ResourceLocation\s+[A-Z0-9_]+\s*=\s*register\(""").containsMatchIn(result) &&
            staticResourceLocationSetPattern.findAll(result).none { it.groupValues[3] in lootSetNames }) {
            return source
        }

        result = staticResourceLocationSetPattern.replace(result) { match ->
            if (match.groupValues[3].contains("loot", ignoreCase = true)) {
                "${match.groupValues[1]}Set<ResourceKey<LootTable>>${match.groupValues[2]}"
            } else {
                match.value
            }
        }
        result = Regex(
            """(?m)^([ \t]*public\s+static\s+final\s+)ResourceLocation(\s+[A-Z0-9_]+\s*=\s*register\()"""
        ).replace(result, "$1ResourceKey<LootTable>$2")
        result = Regex(
            """(?m)^([ \t]*(?:public|protected|private)?\s*(?:final\s+)?)ResourceLocation(\s+[A-Za-z_$][\w$]*(?:Loot|loot)[A-Za-z_$][\w$]*\s*;)"""
        ).replace(result, "$1ResourceKey<LootTable>$2")
        result = Regex(
            """(?m)^([ \t]*(?:public|protected|private)?\s*(?:static\s+)?)Set\s*<\s*ResourceLocation\s*>(\s+[A-Za-z_$][\w$]*Builtin\s*\()"""
        ).replace(result, "$1Set<ResourceKey<LootTable>>$2")
        result = Regex(
            """this\.([A-Za-z_$][\w$]*)\s*=\s*((?:[^;]|\([^;]*\))+);"""
        ).replace(result) { match ->
            if (!match.groupValues[1].contains("loot", ignoreCase = true)) return@replace match.value
            val expression = match.groupValues[2].trim()
            if (expression.startsWith("ResourceKey.create(")) {
                match.value
            } else {
                "this.${match.groupValues[1]} = ResourceKey.create(Registries.LOOT_TABLE, $expression);"
            }
        }
        result = Regex(
            """private\s+static\s+ResourceLocation\s+register\s*\(\s*String\s+([A-Za-z_$][\w$]*)\s*\)\s*\{\s*return\s+register\(\s*((?:[^;]|\([^;]*\))+?)\s*\);\s*\}""",
            RegexOption.DOT_MATCHES_ALL
        ).replace(result) { match ->
            val idVar = match.groupValues[1]
            val expression = match.groupValues[2].trim()
            val keyExpression = if (expression.startsWith("ResourceKey.create(")) {
                expression
            } else {
                "ResourceKey.create(Registries.LOOT_TABLE, $expression)"
            }
            "private static ResourceKey<LootTable> register(String $idVar) {\n\t\treturn register($keyExpression);\n\t}"
        }
        result = Regex("""private\s+static\s+ResourceLocation\s+register\s*\(\s*ResourceLocation\s+([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result) { match -> "private static ResourceKey<LootTable> register(ResourceKey<LootTable> ${match.groupValues[1]})" }
        val withoutResourceLocation = removeImport(result, "net.minecraft.resources.ResourceLocation")
        if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocation)) {
            result = withoutResourceLocation
        }
        return result
    }

    private fun legacyResourceLocationSetAliases(source: String, setNames: Set<String>): Map<String, String> {
        val result = linkedMapOf<String, String>()
        val pattern = Regex(
            """(?ms)^[ \t]*(?:public|protected|private)?\s*static\s+final\s+Set\s*<\s*ResourceLocation\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;]+);"""
        )
        pattern.findAll(source).forEach { match ->
            val alias = match.groupValues[1]
            val initializer = match.groupValues[2]
            setNames
                .firstOrNull { target -> target != alias && Regex("""\b${Regex.escape(target)}\b""").containsMatchIn(initializer) }
                ?.let { target -> result[alias] = target }
        }
        return result
    }

    private fun legacyResourceLocationSetReturnMethods(source: String, setNames: Set<String>): Map<String, String> {
        val result = linkedMapOf<String, String>()
        val pattern = Regex(
            """(?ms)\b(?:public|protected|private)?\s*static\s+Set\s*<\s*ResourceLocation\s*>\s+([A-Za-z_$][\w$]*)\s*\(\s*\)\s*\{\s*return\s+([A-Za-z_$][\w$]*)\s*;\s*}"""
        )
        pattern.findAll(source).forEach { match ->
            val methodName = match.groupValues[1]
            val fieldName = match.groupValues[2]
            if (fieldName in setNames) {
                result[methodName] = fieldName
            }
        }
        return result
    }

    private fun legacyResourceLocationRegisterSets(source: String, setNames: Set<String>): Set<String> {
        val result = linkedSetOf<String>()
        val registerPattern = Regex(
            """private\s+static\s+ResourceLocation\s+register\s*\(\s*ResourceLocation\s+([A-Za-z_$][\w$]*)\s*\)\s*\{""",
            RegexOption.DOT_MATCHES_ALL
        )
        registerPattern.findAll(source).forEach { match ->
            val parameter = match.groupValues[1]
            val openBrace = source.indexOf('{', match.range.last)
            if (openBrace < 0) return@forEach
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) return@forEach
            val body = source.substring(openBrace + 1, closeBrace)
            Regex("""\b([A-Za-z_$][\w$]*)\.add\s*\(\s*${Regex.escape(parameter)}\s*\)""")
                .findAll(body)
                .map { it.groupValues[1] }
                .filterTo(result) { it in setNames }
        }
        return result
    }

    private fun legacyResourceLocationArrayToList(
        expression: String,
        migrateEntry: (String) -> String
    ): String? {
        val trimmed = expression.trim()
        if (Regex("""new\s+ResourceLocation\s*\[\s*0\s*]\s*""").matches(trimmed)) {
            return "java.util.List.of()"
        }
        val arrayMatch = Regex("""new\s+ResourceLocation\s*\[\s*]\s*\{(.*)}""", RegexOption.DOT_MATCHES_ALL)
            .matchEntire(trimmed)
            ?: return null
        val entries = splitTopLevelJavaArgs(arrayMatch.groupValues[1])
            .map { it.trim() }
            .filter { it.isNotEmpty() }
        if (entries.isEmpty()) return "java.util.List.of()"
        return entries.joinToString(prefix = "java.util.List.of(", postfix = ")") { migrateEntry(it) }
    }

    private fun isLootTableResourceKeyExpression(
        expression: String,
        legacyLootTableResourceLocationReferences: Set<String> = emptySet()
    ): Boolean {
        val trimmed = expression.trim()
        return trimmed.contains("ResourceKey.create(") ||
            trimmed.startsWith("BuiltInLootTables.") ||
            trimmed.endsWith(".getDefaultLootTable()") ||
            trimmed.endsWith(".getLootTable()") ||
            trimmed.endsWith(".getLootLocation()") ||
            trimmed.removeSuffix(".location()") in legacyLootTableResourceLocationReferences
    }

    private fun unwrapLootTableResourceKeyCreate(expression: String): String? {
        val trimmed = expression.trim()
        val prefix = "ResourceKey.create("
        if (!trimmed.startsWith(prefix) || !trimmed.endsWith(")")) return null
        val args = splitTopLevelJavaArgs(trimmed.substring(prefix.length, trimmed.length - 1))
        if (args.size != 2) return null
        if (args[0].trim() != "Registries.LOOT_TABLE") return null
        return args[1].trim()
    }

    private fun isLocalLootTableResourceKeyExpression(source: String, expression: String): Boolean {
        val trimmed = expression.trim()
        val memberCall = Regex("""^(?:this\.)?([A-Za-z_$][\w$]*)\s*\(\s*\)$""")
            .matchEntire(trimmed)
        if (memberCall != null) {
            val methodName = memberCall.groupValues[1]
            val resourceKeyMethodPattern = Regex(
                """\b(?:@[A-Za-z0-9_.]+(?:\([^)]*\))?\s+)*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@[A-Za-z0-9_.]+(?:\([^)]*\))?\s+)*(?:net\.minecraft\.resources\.)?ResourceKey\s*<\s*(?:net\.minecraft\.world\.level\.storage\.loot\.)?LootTable\s*>\s+${Regex.escape(methodName)}\s*\("""
            )
            if (resourceKeyMethodPattern.containsMatchIn(source)) return true
            val legacyResourceLocationMethodPattern = Regex(
                """\b(?:@[A-Za-z0-9_.]+(?:\([^)]*\))?\s+)*(?:public|protected|private)?\s*(?:abstract\s+)?(?:@[A-Za-z0-9_.]+(?:\([^)]*\))?\s+)*(?:net\.minecraft\.resources\.)?ResourceLocation\s+${Regex.escape(methodName)}\s*\("""
            )
            if (methodName.contains("LootTable") && legacyResourceLocationMethodPattern.containsMatchIn(source)) return true
        }

        val simpleName = trimmed.substringAfterLast('.')
        if (!Regex("""[A-Za-z_$][\w$]*""").matches(simpleName)) return false
        val resourceKeyFieldPattern = Regex(
            """\b(?:net\.minecraft\.resources\.)?ResourceKey\s*<\s*(?:net\.minecraft\.world\.level\.storage\.loot\.)?LootTable\s*>\s+${Regex.escape(simpleName)}\b"""
        )
        if (resourceKeyFieldPattern.containsMatchIn(source)) return true
        val legacyResourceLocationFieldPattern = Regex(
            """\b(?:net\.minecraft\.resources\.)?ResourceLocation\s+${Regex.escape(simpleName)}\b"""
        )
        return simpleName.contains("LootTable") && legacyResourceLocationFieldPattern.containsMatchIn(source)
    }

    private fun migrateLegacySpawnEggItemTypeCalls(source: String): String {
        if (!source.contains("SpawnEggItem") || !source.contains(".getType(")) return source
        var result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.getType\(\s*([A-Za-z_$][\w$]*)\.getOrDefault\(\s*net\.minecraft\.core\.component\.DataComponents\.CUSTOM_DATA\s*,\s*net\.minecraft\.world\.item\.component\.CustomData\.EMPTY\s*\)\.copyTag\(\)\s*\)"""
        ).replace(source) { match -> "${match.groupValues[1]}.getType(${match.groupValues[2]})" }
        result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.getType\(\s*([A-Za-z_$][\w$]*)\.getTag\(\)\s*\)"""
        ).replace(result) { match -> "${match.groupValues[1]}.getType(${match.groupValues[2]})" }
        return result
    }

    private fun migrateLegacyTriStateEventResults(source: String): String {
        if (!source.contains("Event.Result.")) return source
        var result = source
            .replace("Event.Result.DENY", "TriState.FALSE")
            .replace("Event.Result.ALLOW", "TriState.TRUE")
            .replace("Event.Result.DEFAULT", "TriState.DEFAULT")
        if (result != source) {
            result = addImportIfMissing(result, "net.neoforged.neoforge.common.util.TriState")
            val withoutEventImport = removeImport(result, "net.neoforged.bus.api.Event")
            if (!Regex("""\bEvent\b""").containsMatchIn(withoutEventImport)) {
                result = withoutEventImport
            }
        }
        return result
    }

    private fun migrateRightClickBlockTriStateResults(source: String): String {
        if (!source.contains("RightClickBlock") || !source.contains(".setResult(") || !source.contains("TriState.")) {
            return source
        }
        var result = source
        var changed = false
        var cursor = 0
        val id = """[A-Za-z_$][\w$]*"""
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@\w+(?:\([^)]*\))?\s*\r?\n[ \t]*)*(?:(?:public|protected|private|static|final|synchronized)\s+)*(?:<[^>{};]+>\s*)?(?:[\w<>\[\].?,]+\s+)+$id\s*\([^;{}()]*\b(?:(?:[A-Za-z_$][\w$]*\.)*PlayerInteractEvent\.)?RightClickBlock\s+($id)\b[^;{}()]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val eventVar = match.groupValues[1]
            val openBrace = result.indexOf('{', match.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            var migratedBody = body
            migratedBody = replaceExecutableRegex(
                migratedBody,
                Regex("""(?m)^([ \t]*)\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.TRUE\s*\)\s*;""")
            ) { bodyMatch ->
                val indent = bodyMatch.groupValues[1]
                "${indent}$eventVar.setCancellationResult(InteractionResult.SUCCESS);\n${indent}$eventVar.setCanceled(true);"
            }
            migratedBody = replaceExecutableRegex(
                migratedBody,
                Regex("""(?m)^([ \t]*)\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.FALSE\s*\)\s*;""")
            ) { bodyMatch ->
                val indent = bodyMatch.groupValues[1]
                "${indent}$eventVar.setCancellationResult(InteractionResult.FAIL);\n${indent}$eventVar.setCanceled(true);"
            }
            migratedBody = replaceExecutableRegex(
                migratedBody,
                Regex("""(?m)^([ \t]*)\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.DEFAULT\s*\)\s*;""")
            ) { bodyMatch ->
                val indent = bodyMatch.groupValues[1]
                "${indent}$eventVar.setCanceled(false);"
            }
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                changed = true
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.world.InteractionResult")
        result = removeUnusedSimpleImports(
            result,
            listOf(
                "net.neoforged.neoforge.common.util.TriState",
                "net.neoforged.bus.api.Event"
            )
        )
        return result
    }

    private fun migrateLegacyCancellableEventBaseClasses(source: String): String {
        if (!source.contains("extends Event") || !source.contains("ICancellableEvent")) return source
        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var changed = false
        val classHeader = Regex("""\b(public\s+(?:abstract\s+)?class\s+($id)\s+extends\s+Event)(\s+implements\s+([^({}\r\n]+))?\s*\{""")
        result = classHeader.replace(result) { match ->
            val className = match.groupValues[2]
            val implementsClause = match.groupValues[4]
            if (implementsClause.contains("ICancellableEvent")) return@replace match.value
            val childImplementsCancellation = Regex("""\bclass\s+$id\s+extends\s+${Regex.escape(className)}\s+implements\s+[^{}\r\n]*\bICancellableEvent\b""")
                .containsMatchIn(source)
            if (!childImplementsCancellation) return@replace match.value

            changed = true
            val header = match.groupValues[1]
            if (implementsClause.isBlank()) {
                "$header implements ICancellableEvent {"
            } else {
                "$header implements $implementsClause, ICancellableEvent {"
            }
        }
        return if (changed) addImportIfMissing(result, "net.neoforged.bus.api.ICancellableEvent") else result
    }

    private fun migrateLegacyFillBucketEventSource(source: String): String {
        if (!source.contains("FillBucketEvent") &&
            !(source.contains("PlayerInteractEvent.RightClickBlock") && source.contains(".setResult("))) return source
        val originalExecutable = maskJavaCommentsAndLiterals(source)
        val fillBucketEventVars = Regex("""\bFillBucketEvent\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(originalExecutable)
            .map { it.groupValues[1] }
            .toSet()
        val rightClickBlockEventVars = Regex("""\bPlayerInteractEvent\.RightClickBlock\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(originalExecutable)
            .map { it.groupValues[1] }
            .toSet()
        if (fillBucketEventVars.isEmpty() && rightClickBlockEventVars.isEmpty()) return source
        var result = source
            .replace(
                "import net.minecraftforge.event.entity.player.FillBucketEvent;",
                "import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;"
            )
            .replace(
                "import net.neoforged.neoforge.event.entity.player.FillBucketEvent;",
                "import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;"
            )
        result = replaceExecutableRegex(result, Regex("""\bFillBucketEvent\b""")) {
            "PlayerInteractEvent.RightClickBlock"
        }
        var changed = false
        var cursor = 0
        val methodPattern = Regex(
            """\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^;{}()]*\bPlayerInteractEvent\.RightClickBlock\s+([A-Za-z_$][\w$]*)[^;{}()]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val eventVar = match.groupValues[1]
            val isLegacyFillBucketEvent = eventVar in fillBucketEventVars
            val isRightClickBlockEvent = eventVar in rightClickBlockEventVars || isLegacyFillBucketEvent
            if (!isRightClickBlockEvent) {
                cursor = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', match.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            var migratedBody = body
            if (isLegacyFillBucketEvent) {
                migratedBody = Regex("""\b${Regex.escape(eventVar)}\.getTarget\(\)""")
                    .replace(migratedBody, "$eventVar.getHitVec()")
                migratedBody = Regex("""\b${Regex.escape(eventVar)}\.getEmptyBucket\(\)""")
                    .replace(migratedBody, "$eventVar.getItemStack()")
                migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setFilledBucket\(\s*([^;\r\n]+?)\s*\)\s*;""")
                    .replace(migratedBody) { setMatch ->
                        "$eventVar.getEntity().setItemInHand($eventVar.getHand(), ${setMatch.groupValues[1].trim()});"
                    }
            }
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.TRUE\s*\)\s*;""")
                .replace(
                    migratedBody,
                    "$eventVar.setCancellationResult(InteractionResult.SUCCESS);\n        $eventVar.setCanceled(true);"
                )
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.FALSE\s*\)\s*;""")
                .replace(
                    migratedBody,
                    "$eventVar.setCancellationResult(InteractionResult.FAIL);\n        $eventVar.setCanceled(true);"
                )
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.DEFAULT\s*\)\s*;""")
                .replace(migratedBody, "$eventVar.setCanceled(false);")
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                changed = true
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        if (!changed) return result
        result = addImportIfMissing(result, "net.minecraft.world.InteractionResult")
        result = removeUnusedSimpleImports(
            result,
            listOf(
                "net.neoforged.neoforge.common.util.TriState",
                "net.neoforged.bus.api.Event"
            )
        )
        return result
    }

    private fun migrateLegacySleepingTimeCheckEventSource(source: String): String {
        if (!source.contains("SleepingTimeCheckEvent") &&
            !source.contains("SleepingLocationCheckEvent") &&
            !source.contains("CanPlayerSleepEvent")) return source
        val directLocationEventVars = Regex(
            """\bSleepingLocationCheckEvent\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(maskJavaCommentsAndLiterals(source))
            .map { it.groupValues[1] }
            .toSet()
        var result = source
            .replace(
                "net.minecraftforge.event.entity.player.SleepingTimeCheckEvent",
                "net.neoforged.neoforge.event.entity.player.CanPlayerSleepEvent"
            )
            .replace(
                "net.neoforged.neoforge.event.entity.player.SleepingTimeCheckEvent",
                "net.neoforged.neoforge.event.entity.player.CanPlayerSleepEvent"
            )
            .replace(
                "net.minecraftforge.event.entity.player.SleepingLocationCheckEvent",
                "net.neoforged.neoforge.event.entity.player.CanPlayerSleepEvent"
            )
            .replace(
                "net.neoforged.neoforge.event.entity.player.SleepingLocationCheckEvent",
                "net.neoforged.neoforge.event.entity.player.CanPlayerSleepEvent"
            )
            .replace("SleepingTimeCheckEvent", "CanPlayerSleepEvent")
            .replace("SleepingLocationCheckEvent", "CanPlayerSleepEvent")

        var changed = false
        var cursor = 0
        val methodPattern = Regex(
            """\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^;{}()]*\bCanPlayerSleepEvent\s+([A-Za-z_$][\w$]*)[^;{}()]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val eventVar = match.groupValues[1]
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            var migratedBody = body
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.FALSE\s*\)""")
                .replace(migratedBody, "$eventVar.setProblem(net.minecraft.world.entity.player.Player.BedSleepingProblem.NOT_POSSIBLE_NOW)")
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.TRUE\s*\)""")
                .replace(migratedBody, "$eventVar.setProblem(null)")
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.setResult\(\s*TriState\.DEFAULT\s*\)""")
                .replace(migratedBody, "$eventVar.setProblem($eventVar.getVanillaProblem())")
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.getSleepingLocation\(\)""")
                .replace(
                    migratedBody,
                    if (eventVar in directLocationEventVars) "$eventVar.getPos()" else "java.util.Optional.of($eventVar.getPos())"
                )
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.getPos\(\)\.isPresent\(\)\s*&&\s*""")
                .replace(migratedBody, "")
            migratedBody = Regex("""\b${Regex.escape(eventVar)}\.getPos\(\)\.getValue\(\)""")
                .replace(migratedBody, "$eventVar.getPos()")
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                changed = true
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }

        if (changed) {
            result = removeUnusedSimpleImports(
                result,
                listOf(
                    "net.neoforged.neoforge.common.util.TriState",
                    "net.neoforged.bus.api.Event"
                )
            )
        }
        return result
    }

    private fun migrateLegacyCancellableEventHelperParameters(source: String): String {
        if (!source.contains(".isCanceled()") && !source.contains(".setCanceled(")) {
            return source
        }
        var result = source
        var cursor = 0
        var changed = false
        val supportedBroadEventTypes = setOf(
            "Event",
            "EntityEvent",
            "LivingEvent",
            "PlayerEvent",
            "PlayerInteractEvent"
        )
        val signaturePattern = Regex(
            """\b(private|public|protected)\s+(static\s+)?void\s+([A-Za-z_$][\w$]*)\(\s*((?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s+([A-Za-z_$][\w$]*)\s*([,)])"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last + 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val annotationStart = annotationStartBefore(result, match.range.first)
            if (result.substring(annotationStart, match.range.first).contains("@SubscribeEvent")) {
                cursor = closeBrace + 1
                continue
            }
            val parameterType = match.groupValues[4]
            val simpleParameterType = parameterType.substringAfterLast('.')
            if (simpleParameterType == "ICancellableEvent" || simpleParameterType !in supportedBroadEventTypes) {
                cursor = closeBrace + 1
                continue
            }
            val parameter = match.groupValues[5]
            val methodText = result.substring(match.range.first, closeBrace + 1)
            if (Regex("""\b${Regex.escape(parameter)}\.(?:isCanceled\(\)|setCanceled\()""").containsMatchIn(methodText) &&
                !Regex("""\b${Regex.escape(parameter)}\.(?!isCanceled\(\)|setCanceled\()""").containsMatchIn(methodText)
            ) {
                val replacement = "${match.groupValues[1]} ${match.groupValues[2]}void ${match.groupValues[3]}(ICancellableEvent $parameter${match.groupValues[6]}"
                result = result.substring(0, match.range.first) + replacement + result.substring(match.range.last + 1)
                cursor = match.range.first + replacement.length
                changed = true
            } else {
                cursor = closeBrace + 1
            }
        }
        if (changed) {
            result = addImportIfMissing(result, "net.neoforged.bus.api.ICancellableEvent")
        }
        return result
    }

    private fun migrateLegacyCancellableEventHelperCallSites(source: String): String {
        if (!source.contains("ICancellableEvent") || !source.contains("instanceof PlayerInteractEvent.")) return source
        val helperNames = Regex(
            """\b(?:private|public|protected)\s+(?:static\s+)?void\s+([A-Za-z_$][\w$]*)\s*\(\s*ICancellableEvent\s+[A-Za-z_$][\w$]*\s*(?:,|\))"""
        ).findAll(source).map { it.groupValues[1] }.toSet()
        if (helperNames.isEmpty()) return source

        var result = source
        var cursor = 0
        val branchPattern = Regex(
            """\bif\s*\(\s*([A-Za-z_$][\w$]*)\s+instanceof\s+PlayerInteractEvent(?:\.[A-Za-z_$][\w$]*)+\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
        )
        while (true) {
            val match = branchPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val baseEvent = match.groupValues[1]
            val narrowedEvent = match.groupValues[2]
            var body = result.substring(openBrace + 1, closeBrace)
            val originalBody = body
            for (helperName in helperNames) {
                body = Regex("""\b${Regex.escape(helperName)}\s*\(\s*${Regex.escape(baseEvent)}\s*([,)])""")
                    .replace(body) { helperMatch -> "$helperName($narrowedEvent${helperMatch.groupValues[1]}" }
            }
            if (body != originalBody) {
                result = result.substring(0, openBrace + 1) + body + result.substring(closeBrace)
                cursor = openBrace + body.length + 1
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private data class PlayerInteractBranch(
        val subclass: String,
        val variable: String,
        val body: String
    )

    private fun splitLegacyAbstractPlayerInteractSubscribers(source: String): String {
        if (!source.contains("@SubscribeEvent") ||
            !source.contains("PlayerInteractEvent ") ||
            !source.contains("instanceof PlayerInteractEvent.")) {
            return source
        }

        var result = source
        var cursor = 0
        val signaturePattern = Regex(
            """(?m)^([ \t]*)@SubscribeEvent\s*\r?\n\1((?:(?:public|protected|private|static|final)\s+)*)void\s+([A-Za-z_$][\w$]*)\s*\(\s*PlayerInteractEvent\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }

            val indent = match.groupValues[1]
            val modifiers = match.groupValues[2]
            val methodName = match.groupValues[3]
            val eventVariable = match.groupValues[4]
            val body = result.substring(openBrace + 1, closeBrace)
            val branches = playerInteractInstanceofBranches(body, eventVariable)
            if (branches == null || branches.isEmpty()) {
                cursor = closeBrace + 1
                continue
            }

            val replacement = branches.joinToString(System.lineSeparator() + System.lineSeparator()) { branch ->
                val branchBody = Regex("""\b${Regex.escape(eventVariable)}\b""")
                    .replace(branch.body.trim('\r', '\n'), branch.variable)
                buildString {
                    append(indent).append("@SubscribeEvent").append(System.lineSeparator())
                    append(indent)
                    append(modifiers)
                    append("void ")
                    append(methodName)
                    append("(PlayerInteractEvent.")
                    append(branch.subclass)
                    append(" ")
                    append(branch.variable)
                    append(") {")
                    append(branchBody.trimEnd().prependIndent(System.lineSeparator()).trimEnd())
                    append(System.lineSeparator())
                    append(indent).append("}")
                }
            }

            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private fun playerInteractInstanceofBranches(body: String, eventVariable: String): List<PlayerInteractBranch>? {
        val branches = mutableListOf<PlayerInteractBranch>()
        var cursor = 0
        var firstBranch = true
        while (true) {
            cursor = skipWhitespace(body, cursor)
            if (cursor >= body.length) break
            val branchStart = Regex(
                if (firstBranch) {
                    """\Gif\s*\(\s*${Regex.escape(eventVariable)}\s+instanceof\s+PlayerInteractEvent\.([A-Za-z_$][\w$]*)\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
                } else {
                    """\Gelse\s+if\s*\(\s*${Regex.escape(eventVariable)}\s+instanceof\s+PlayerInteractEvent\.([A-Za-z_$][\w$]*)\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
                }
            ).find(body, cursor) ?: return null
            val openBrace = body.indexOf('{', branchStart.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(body, openBrace) else -1
            if (closeBrace <= openBrace) return null
            branches.add(PlayerInteractBranch(
                subclass = branchStart.groupValues[1],
                variable = branchStart.groupValues[2],
                body = body.substring(openBrace + 1, closeBrace)
            ))
            cursor = closeBrace + 1
            firstBranch = false
        }
        return branches
    }

    private fun migrateAbstractRenderLivingSubscribers(source: String): String {
        if (!source.contains("@SubscribeEvent") ||
            (!source.contains("RenderLivingEvent") &&
                !source.contains("RenderPlayerEvent") &&
                !source.contains("RenderGuiLayerEvent"))) {
            return source
        }

        var result = source
        val renderEventSpecs = listOf(
            Triple("""RenderLivingEvent\s*(?:<\s*\?\s*,\s*\?\s*>)?""", "RenderLivingEvent.Pre<?, ?>", true),
            Triple("""RenderPlayerEvent""", "RenderPlayerEvent.Pre", false),
            Triple("""RenderGuiLayerEvent""", "RenderGuiLayerEvent.Pre", false)
        )
        for ((eventTypePattern, preEventType, useLivingHeuristic) in renderEventSpecs) {
            var cursor = 0
            val signaturePattern = Regex(
                """(?m)^([ \t]*)@SubscribeEvent(?:\([^)]*\))?\s*\r?\n\1((?:(?:public|protected|private|static|final)\s+)*)void\s+([A-Za-z_$][\w$]*)\s*\(\s*($eventTypePattern)\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
            )
            while (true) {
                val match = signaturePattern.find(result, cursor) ?: break
                if (match.groupValues[4].contains(".Pre")) {
                    cursor = match.range.last + 1
                    continue
                }
                val openBrace = result.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                if (closeBrace <= openBrace) {
                    cursor = match.range.last + 1
                    continue
                }

                val eventVariable = match.groupValues[5]
                val body = result.substring(openBrace + 1, closeBrace)
                val usesCancellationApi = Regex("""\b${Regex.escape(eventVariable)}\.(?:setCanceled|isCanceled)\s*\(""")
                    .containsMatchIn(body)
                val requiresPre = usesCancellationApi ||
                    (useLivingHeuristic && isRenderLivingPreSubscriberBody(body, eventVariable))
                if (!requiresPre) {
                    cursor = closeBrace + 1
                    continue
                }

                val typeRange = match.groups[4]?.range
                if (typeRange == null) {
                    cursor = closeBrace + 1
                    continue
                }
                result = result.substring(0, typeRange.first) +
                    preEventType +
                    result.substring(typeRange.last + 1)
                cursor = typeRange.first + preEventType.length
            }
        }
        return result
    }

    private fun isRenderLivingPreSubscriberBody(body: String, eventVariable: String): Boolean {
        if (Regex("""\b${Regex.escape(eventVariable)}\.setCanceled\s*\(""").containsMatchIn(body)) return true
        val usesRendererModel = Regex("""\b${Regex.escape(eventVariable)}\.getRenderer\s*\(\s*\)\.getModel\s*\(""")
            .containsMatchIn(body)
        val mutatesModelVisibility = Regex("""\.(?:visible|xRot|yRot|zRot)\s*=""").containsMatchIn(body)
        return usesRendererModel && mutatesModelVisibility
    }

    private fun skipWhitespace(source: String, start: Int): Int {
        var index = start
        while (index < source.length && source[index].isWhitespace()) {
            index++
        }
        return index
    }

    private fun migrateLegacyCreativeTabEnchantmentInstances(source: String): String {
        val executableSource = maskJavaCommentsAndLiterals(source)
        if (!executableSource.contains("EnchantmentInstance(") &&
            !executableSource.contains(".ENCHANTMENTS.getEntries()") &&
            !executableSource.contains("Enchantments.")
        ) {
            return source
        }

        var result = migrateLegacyEnchantmentConstantNames(source)
        var changed = false

        val initialExecutableCode = maskJavaCommentsAndLiterals(result)
        val displayParametersName = Regex("""displayItems\s*\(\s*\(\s*([A-Za-z_$][\w$]*)\s*,""")
            .find(initialExecutableCode)
            ?.groupValues
            ?.get(1)
            ?: Regex("""CreativeModeTab\.ItemDisplayParameters\s+([A-Za-z_$][\w$]*)""")
                .find(initialExecutableCode)
                ?.groupValues
                ?.get(1)
            ?: "parameters"

        if (maskJavaCommentsAndLiterals(result).contains("new EnchantmentInstance(Enchantments.")) {
            result = rewriteExecutableJavaNew(result, "EnchantmentInstance") { args ->
                if (args.size < 2) return@rewriteExecutableJavaNew null
                val enchantment = args[0].trim()
                if (!Regex("""^Enchantments\.[A-Z0-9_]+$""").matches(enchantment)) return@rewriteExecutableJavaNew null
                val migratedArgs = args.toMutableList()
                migratedArgs[0] = "$displayParametersName.holders().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow($enchantment)"
                changed = true
                "new EnchantmentInstance(${migratedArgs.joinToString(", ")})"
            }
        }

        val helperNames = mutableSetOf<String>()
        val helperPattern = Regex(
            """\b(private|public|protected)\s+(static\s+)?void\s+([A-Za-z_$][\w$]*)\s*\(\s*CreativeModeTab\.Output\s+([A-Za-z_$][\w$]*)\s*,\s*CreativeModeTab\.TabVisibility\s+([A-Za-z_$][\w$]*)\s*\)"""
        )
        var cursor = 0
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val match = helperPattern.find(executableCode, cursor) ?: break
            val openBrace = executableCode.indexOf('{', match.range.last + 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(executableCode, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val methodBody = executableCode.substring(openBrace + 1, closeBrace)
            if (methodBody.contains(".ENCHANTMENTS.getEntries()")) {
                val replacement = "${match.groupValues[1]} ${match.groupValues[2]}void ${match.groupValues[3]}(CreativeModeTab.ItemDisplayParameters parameters, CreativeModeTab.Output ${match.groupValues[4]}, CreativeModeTab.TabVisibility ${match.groupValues[5]})"
                result = result.substring(0, match.range.first) + replacement + result.substring(match.range.last + 1)
                helperNames += match.groupValues[3]
                changed = true
                cursor = match.range.first + replacement.length
            } else {
                cursor = closeBrace + 1
            }
        }

        for (helperName in helperNames) {
            result = rewriteExecutableJavaInvocationArguments(result, helperName) { args ->
                if (args.size != 2) return@rewriteExecutableJavaInvocationArguments null
                if (args[0].contains("ItemDisplayParameters") || args[0] == displayParametersName) {
                    return@rewriteExecutableJavaInvocationArguments null
                }
                changed = true
                listOf(displayParametersName, args[0], args[1])
            }
        }

        if (maskJavaCommentsAndLiterals(result).contains(".ENCHANTMENTS.getEntries()")) {
            val loopVariables = mutableSetOf<String>()
            val loopPattern = Regex(
                """(?m)^([ \t]*)for\s*\(\s*[^:\r\n]+?\s+([A-Za-z_$][\w$]*)\s*:\s*((?:[A-Za-z_$][\w$]*\.)*ENCHANTMENTS)\.getEntries\(\)\s*\)\s*\{"""
            )
            result = replaceExecutableJavaRegex(result, loopPattern) { match ->
                val indent = match.groupValues[1]
                val variable = match.groupValues[2]
                val entriesOwner = match.groupValues[3]
                val keyVariable = "${variable}Key"
                loopVariables += variable
                changed = true
                "${indent}for (ResourceKey<Enchantment> $keyVariable : $entriesOwner) {\n" +
                    "${indent}    Holder<Enchantment> $variable = parameters.holders().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow($keyVariable);"
            }
            for (variable in loopVariables) {
                result = replaceExecutableJavaRegex(result, Regex("""\b${Regex.escape(variable)}\.get\(\)\.(get(?:Max|Min)Level)\(\)""")) { match ->
                    "$variable.value().${match.groupValues[1]}()"
                }
                result = replaceExecutableJavaRegex(result, Regex("""new\s+EnchantmentInstance\(\s*${Regex.escape(variable)}\.get\(\)\s*,""")) {
                    "new EnchantmentInstance($variable,"
                }
                result = replaceExecutableJavaRegex(result, Regex("""\b${Regex.escape(variable)}\.get\(\)""")) {
                    variable
                }
            }
        }

        if (!changed && result == source) return source
        if (result.contains("lookupOrThrow(Registries.ENCHANTMENT)")) {
            result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        }
        if (result.contains("Holder<Enchantment>")) {
            result = addImportIfMissing(result, "net.minecraft.core.Holder")
            result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.Enchantment")
        }
        if (result.contains("ResourceKey<Enchantment>")) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.Enchantment")
        }
        return result
    }

    private fun migrateLegacyHolderAccessors(source: String): String {
        val executableSource = maskJavaCommentsAndLiterals(source)
        if (!executableSource.contains("Holder") &&
            !executableSource.contains(".getHolder().get()") &&
            !executableSource.contains(".getHolder().orElseThrow()") &&
            !executableSource.contains(".getEffect().") &&
            !executableSource.contains(".getBiome(")
        ) {
            return source
        }
        var result = replaceExecutableJavaRegex(source, Regex("""\.getHolder\(\)\.orElseThrow\(\)""")) {
            ".getDelegate()"
        }
        result = replaceExecutableJavaRegex(result, Regex("""\.getHolder\(\)\.get\(\)""")) {
            ".getDelegate()"
        }

        val holderVariables = Regex("""\bHolder\s*<[^>\r\n]+>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(maskJavaCommentsAndLiterals(result))
            .map { it.groupValues[1] }
            .toSet()
        for (variable in holderVariables) {
            result = replaceExecutableJavaRegex(
                result,
                Regex("""\bthis\.${Regex.escape(variable)}\.get\(\)""")
            ) {
                "this.$variable.value()"
            }
            result = replaceExecutableJavaRegex(
                result,
                Regex("""(?<![\w$.\]])\b${Regex.escape(variable)}\.get\(\)""")
            ) {
                "$variable.value()"
            }
        }

        val holderBlockVariables = Regex("""\bHolder\s*<\s*Block\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(maskJavaCommentsAndLiterals(result))
            .map { it.groupValues[1] }
            .toMutableSet()
        Regex("""BuiltInRegistries\.BLOCK\.getOrCreateTag\([^;\r\n]*?\)\.forEach\(\s*([A-Za-z_$][\w$]*)\s*->""")
            .findAll(maskJavaCommentsAndLiterals(result))
            .forEach { holderBlockVariables += it.groupValues[1] }
        for (variable in holderBlockVariables) {
            result = replaceExecutableJavaRegex(
                result,
                Regex("""(?<![\w$.\]])\b${Regex.escape(variable)}\.defaultBlockState\(\)""")
            ) {
                "$variable.value().defaultBlockState()"
            }
        }
        val blockMapVariables = Regex("""\b(?:Map|HashMap|LinkedHashMap|ConcurrentHashMap)\s*<\s*Block\s*,\s*Block\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(maskJavaCommentsAndLiterals(result))
            .map { it.groupValues[1] }
            .toSet()
        for (mapVariable in blockMapVariables) {
            result = rewriteExecutableJavaInvocationArguments(result, "$mapVariable.put") { args ->
                if (args.size != 2) return@rewriteExecutableJavaInvocationArguments null
                args.map { arg ->
                    val trimmed = arg.trim()
                    if (trimmed in holderBlockVariables) "$trimmed.value()" else arg
                }.takeIf { it != args }
            }
        }

        result = replaceExecutableJavaRegex(
            result,
            Regex("""(\.getBiome\((?:[^()]|\([^()]*\))*\))\.get\(\)""")
        ) { match ->
            "${match.groupValues[1]}.value()"
        }
        result = replaceExecutableJavaRegex(result, Regex("""\.getEffect\(\)\.isInstantenous\(""")) {
            ".getEffect().value().isInstantenous("
        }
        result = replaceExecutableJavaRegex(result, Regex("""\.getEffect\(\)\.applyInstantenousEffect\(""")) {
            ".getEffect().value().applyInstantenousEffect("
        }
        return result
    }

    private fun migrateLegacyItemConstructorsAndProperties(source: String): String {
        val executableSource = maskJavaCommentsAndLiterals(source)
        if (!executableSource.contains("new SwordItem(") &&
            !executableSource.contains("super(") &&
            !executableSource.contains("new RecordItem(") &&
            !executableSource.contains(".meat()") &&
            !executableSource.contains("new BowlFoodItem(")
        ) {
            return source
        }
        var result = replaceExecutableJavaRegex(source, Regex("""\.meat\(\)""")) { "" }
        if (maskJavaCommentsAndLiterals(result).contains("new BowlFoodItem(")) {
            result = replaceExecutableJavaRegex(result, Regex("""\bnew\s+BowlFoodItem\s*\(""")) {
                "new Item("
            }
            if (!maskJavaCommentsAndLiterals(result).contains("BowlFoodItem")) {
                result = removeImport(result, "net.minecraft.world.item.BowlFoodItem")
            }
            result = addImportIfMissing(result, "net.minecraft.world.item.Item")
        }
        result = rewriteExecutableJavaNew(result, "SwordItem") { args ->
            if (args.size != 4) return@rewriteExecutableJavaNew null
            val tier = args[0].trim()
            val damage = args[1].trim()
            val speed = args[2].trim()
            val properties = args[3].trim()
            "new SwordItem($tier, $properties.attributes(SwordItem.createAttributes($tier, $damage, $speed)))"
        }
        result = migrateLegacyRecordItemRegistrations(result)
        if (Regex("""\bextends\s+SwordItem\b""").containsMatchIn(maskJavaCommentsAndLiterals(result))) {
            result = rewriteExecutableSuperConstructorCalls(result) { args ->
                if (args.size != 4) return@rewriteExecutableSuperConstructorCalls null
                val tier = args[0].trim()
                val damage = args[1].trim()
                val speed = args[2].trim()
                val properties = args[3].trim()
                "super($tier, $properties.attributes(SwordItem.createAttributes($tier, $damage, $speed)))"
            }
        }
        if (Regex("""\bextends\s+(?:PickaxeItem|AxeItem|HoeItem|ShovelItem)\b""").containsMatchIn(maskJavaCommentsAndLiterals(result))) {
            result = rewriteExecutableSuperConstructorCalls(result) { args ->
                if (args.size != 4) return@rewriteExecutableSuperConstructorCalls null
                val tier = args[0].trim()
                val damage = args[1].trim()
                val speed = args[2].trim()
                val properties = args[3].trim()
                "super($tier, $properties.attributes(net.minecraft.world.item.DiggerItem.createAttributes($tier, $damage, $speed)))"
            }
        }
        return result
    }

    private fun migrateLegacyTierLevelSource(source: String): String {
        if (!source.contains("implements Tier") || !source.contains("getLevel()")) return source
        val enumName = Regex("""\benum\s+([A-Za-z_$][\w$]*)\s+implements\s+[^{};]*\bTier\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        val levelMethodRegex = Regex(
            """(?s)([ \t]*@Override\s*\r?\n)?[ \t]*public\s+int\s+getLevel\s*\(\s*\)\s*\{\s*return\s+(?:this\.)?([A-Za-z_$][\w$]*)\s*;\s*\}\s*"""
        )
        val levelMethod = levelMethodRegex.find(source) ?: return source
        val legacyLevelField = levelMethod.groupValues[2]
        val fieldRegex = Regex("""(?m)^([ \t]*)private\s+final\s+int\s+${Regex.escape(legacyLevelField)}\s*;\s*$""")
        if (!fieldRegex.containsMatchIn(source)) return source

        val constructorRegex = Regex("""\b${Regex.escape(enumName)}\s*\(([^)]*)\)""")
        val constructorMatch = constructorRegex.find(source) ?: return source
        val constructorArgs = splitTopLevelJavaArgs(constructorMatch.groupValues[1])
        val legacyLevelArgIndex = constructorArgs.indexOfFirst { Regex("""\bint\s+${Regex.escape(legacyLevelField)}\b""").containsMatchIn(it) }
        if (legacyLevelArgIndex < 0) return source

        val assignmentRegex = Regex("""this\.${Regex.escape(legacyLevelField)}\s*=\s*${Regex.escape(legacyLevelField)}\s*;""")
        if (!assignmentRegex.containsMatchIn(source)) return source

        val constantsRewrite = rewriteLegacyTierEnumConstants(source, enumName, legacyLevelArgIndex) ?: return source
        var result = constantsRewrite
        result = fieldRegex.replace(result) { match ->
            "${match.groupValues[1]}private final TagKey<Block> incorrectBlocksForDrops;"
        }
        val migratedConstructor = constructorRegex.find(result) ?: return source
        val migratedConstructorArgs = splitTopLevelJavaArgs(migratedConstructor.groupValues[1]).toMutableList()
        if (legacyLevelArgIndex !in migratedConstructorArgs.indices) return source
        migratedConstructorArgs[legacyLevelArgIndex] = Regex("""\bint\s+${Regex.escape(legacyLevelField)}\b""")
            .replace(migratedConstructorArgs[legacyLevelArgIndex], "TagKey<Block> incorrectBlocksForDrops")
        val constructorReplacement = "$enumName(${migratedConstructorArgs.joinToString(", ")})"
        result = result.substring(0, migratedConstructor.range.first) +
            constructorReplacement +
            result.substring(migratedConstructor.range.last + 1)
        result = assignmentRegex.replace(result, "this.incorrectBlocksForDrops = incorrectBlocksForDrops;")
        val migratedLevelMethod = levelMethodRegex.find(result) ?: return source
        result = result.substring(0, migratedLevelMethod.range.first) +
            """
	@Override
	public TagKey<Block> getIncorrectBlocksForDrops() {
		return this.incorrectBlocksForDrops;
	}
""".trimIndent() + "\n\n" +
            result.substring(migratedLevelMethod.range.last + 1)
        result = addImportIfMissing(result, "net.minecraft.tags.BlockTags")
        result = addImportIfMissing(result, "net.minecraft.tags.TagKey")
        result = addImportIfMissing(result, "net.minecraft.world.level.block.Block")
        return result
    }

    private fun migrateLegacyTierClassLevelSource(source: String): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        if (!executableCode.contains("implements Tier") ||
            !executableCode.contains("getLevel()") ||
            executableCode.contains("getIncorrectBlocksForDrops()")) {
            return source
        }
        if (!Regex("""\bclass\s+[A-Za-z_$][\w$]*\s+implements\s+[^{};]*\bTier\b""").containsMatchIn(executableCode)) {
            return source
        }

        val levelMethodPattern = Regex(
            """(?s)\n([ \t]*)(@Override\s*\r?\n[ \t]*)?public\s+int\s+getLevel\s*\(\s*\)\s*\{\s*return\s+([^;]+?)\s*;\s*\}\s*"""
        )
        val levelMethod = levelMethodPattern.find(executableCode) ?: return source
        val legacyLevelExpression = levelMethod.groupValues[3].trim()
        val tagMethodPattern = Regex(
            """(?s)\n[ \t]*(@Override\s*\r?\n[ \t]*)?public\s+(?:@Nullable\s+)?TagKey\s*<\s*Block\s*>\s+getTag\s*\(\s*\)\s*\{\s*return\s+([^;]+?)\s*;\s*\}\s*"""
        )
        val tagMethod = tagMethodPattern.find(executableCode)
        val incorrectBlocksExpression = tagMethod
            ?.groupValues
            ?.get(2)
            ?.trim()
            ?.takeIf { it != "null" }
            ?: legacyTierMiningLevelTag(legacyLevelExpression)
            ?: return source

        var result = source
        if (tagMethod != null) {
            result = result.removeRange(tagMethod.range)
        }
        val migratedLevelMethod = levelMethodPattern.find(maskJavaCommentsAndLiterals(result)) ?: return source
        val indent = migratedLevelMethod.groupValues[1]
        val replacement = """

${indent}@Override
${indent}public TagKey<Block> getIncorrectBlocksForDrops() {
${indent}    return $incorrectBlocksExpression;
${indent}}
""".trimEnd()
        result = result.replaceRange(migratedLevelMethod.range, replacement)
        result = addImportIfMissing(result, "net.minecraft.tags.BlockTags")
        result = addImportIfMissing(result, "net.minecraft.tags.TagKey")
        result = addImportIfMissing(result, "net.minecraft.world.level.block.Block")
        val withoutNullable = removeImport(result, "org.jetbrains.annotations.Nullable")
        if (!maskJavaCommentsAndLiterals(withoutNullable).contains("@Nullable")) {
            result = withoutNullable
        }
        return result
    }

    private fun rewriteLegacyTierEnumConstants(source: String, enumName: String, levelArgIndex: Int): String? {
        val enumMatch = Regex("""\benum\s+${Regex.escape(enumName)}\b""").find(source) ?: return null
        val bodyStart = source.indexOf('{', enumMatch.range.last)
        if (bodyStart < 0) return null
        val bodyEnd = findMatchingBrace(source, bodyStart)
        if (bodyEnd < 0) return null
        var cursor = bodyStart + 1
        var constantsEnd = -1
        var parenDepth = 0
        var braceDepth = 0
        var bracketDepth = 0
        var angleDepth = 0
        var inString = false
        var escaped = false
        while (cursor < bodyEnd) {
            val ch = source[cursor]
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                cursor++
                continue
            }
            when (ch) {
                '"' -> inString = true
                '(' -> parenDepth++
                ')' -> if (parenDepth > 0) parenDepth--
                '{' -> braceDepth++
                '}' -> if (braceDepth > 0) braceDepth--
                '[' -> bracketDepth++
                ']' -> if (bracketDepth > 0) bracketDepth--
                '<' -> angleDepth++
                '>' -> if (angleDepth > 0) angleDepth--
                ';' -> if (parenDepth == 0 && braceDepth == 0 && bracketDepth == 0 && angleDepth == 0) {
                    constantsEnd = cursor
                    break
                }
            }
            cursor++
        }
        if (constantsEnd < 0) return null
        val constants = source.substring(bodyStart + 1, constantsEnd)
        var changed = false
        val rebuilt = StringBuilder()
        var segmentStart = 0
        parenDepth = 0
        braceDepth = 0
        bracketDepth = 0
        angleDepth = 0
        inString = false
        escaped = false
        for (i in constants.indices) {
            val ch = constants[i]
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                continue
            }
            when (ch) {
                '"' -> inString = true
                '(' -> parenDepth++
                ')' -> if (parenDepth > 0) parenDepth--
                '{' -> braceDepth++
                '}' -> if (braceDepth > 0) braceDepth--
                '[' -> bracketDepth++
                ']' -> if (bracketDepth > 0) bracketDepth--
                '<' -> angleDepth++
                '>' -> if (angleDepth > 0) angleDepth--
                ',' -> if (parenDepth == 0 && braceDepth == 0 && bracketDepth == 0 && angleDepth == 0) {
                    val (rewritten, didChange) = rewriteLegacyTierEnumConstantSegment(constants.substring(segmentStart, i), levelArgIndex)
                    rebuilt.append(rewritten).append(',')
                    changed = changed || didChange
                    segmentStart = i + 1
                }
            }
        }
        val (lastSegment, lastChanged) = rewriteLegacyTierEnumConstantSegment(constants.substring(segmentStart), levelArgIndex)
        rebuilt.append(lastSegment)
        changed = changed || lastChanged
        if (!changed) return null
        return source.substring(0, bodyStart + 1) + rebuilt + source.substring(constantsEnd)
    }

    private fun rewriteLegacyTierEnumConstantSegment(segment: String, levelArgIndex: Int): Pair<String, Boolean> {
        val match = Regex("""^(\s*)([A-Z][A-Z0-9_]*)\s*\(""").find(segment) ?: return segment to false
        val openParen = match.range.last
        val closeParen = findMatchingParen(segment, openParen)
        if (closeParen < 0) return segment to false
        val args = splitTopLevelJavaArgs(segment.substring(openParen + 1, closeParen)).toMutableList()
        if (levelArgIndex !in args.indices) return segment to false
        val replacement = legacyTierMiningLevelTag(args[levelArgIndex].trim()) ?: return segment to false
        args[levelArgIndex] = replacement
        val rewritten = segment.substring(0, openParen + 1) +
            args.joinToString(", ") +
            segment.substring(closeParen)
        return rewritten to true
    }

    private fun legacyTierMiningLevelTag(levelText: String): String? =
        when (levelText.toIntOrNull()) {
            0 -> "BlockTags.INCORRECT_FOR_WOODEN_TOOL"
            1 -> "BlockTags.INCORRECT_FOR_STONE_TOOL"
            2 -> "BlockTags.INCORRECT_FOR_IRON_TOOL"
            3 -> "BlockTags.INCORRECT_FOR_DIAMOND_TOOL"
            null -> null
            else -> "BlockTags.INCORRECT_FOR_NETHERITE_TOOL"
        }

    private fun migrateLegacyRecordItemRegistrations(source: String): String {
        if (!source.contains("new RecordItem(") && !source.contains(".jukeboxPlayable(")) return source
        val modIdExpression = Regex(
            """DeferredRegister\s*<\s*Item\s*>\s+[A-Z][A-Z0-9_]*\s*=\s*DeferredRegister\.create\([^,\r\n]+,\s*([^)]+?)\s*\)"""
        ).find(source)?.groupValues?.get(1)?.trim()
            ?: Regex("""\b([A-Za-z_$][\w$]*\.(?:MODID|MOD_ID|ID))\b""").find(source)?.groupValues?.get(1)
            ?: return source
        var changed = false
        val result = Regex(
            """ITEMS\.register\(\s*"([^"]+)"\s*,\s*\(\s*\)\s*->\s*new\s+RecordItem\(\s*[^,]+,\s*[^,]+,\s*(new\s+Item\.Properties\(\)(?:\.[A-Za-z_$][\w$]*\([^)]*\))*)\s*,\s*[^)]+\)\s*\)"""
        ).replace(source) { match ->
            val name = match.groupValues[1]
            val properties = match.groupValues[2]
            changed = true
            "ITEMS.register(\"$name\", () -> new Item($properties.jukeboxPlayable(ResourceKey.create(Registries.JUKEBOX_SONG, ResourceLocation.fromNamespaceAndPath($modIdExpression, \"$name\")))))"
        }
        if (!changed) return source
        var migrated = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
        migrated = addImportIfMissing(migrated, "net.minecraft.core.registries.Registries")
        migrated = addImportIfMissing(migrated, "net.minecraft.resources.ResourceLocation")
        migrated = addImportIfMissing(migrated, "net.minecraft.world.item.Item")
        return migrated
    }

    private fun migrateLegacyCustomRecipeSource(source: String): String {
        if (!source.contains("extends CustomRecipe")) return source
        var result = source
        result = result.replace("super(id, category);", "super(category);")
        result = removeImport(result, "net.minecraft.world.inventory.CraftingInput")
        if (result.contains("CraftingContainer")) {
            result = result.replace("CraftingContainer", "CraftingInput")
            result = removeImport(result, "net.minecraft.world.inventory.CraftingInput")
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.CraftingInput")
            if (!result.contains("CraftingContainer")) {
                result = removeImport(result, "net.minecraft.world.inventory.CraftingContainer")
            }
        }
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getContainerSize\(\)""")
            .replace(result) { match -> "${match.groupValues[1]}.size()" }
        return result
    }

    private fun migrateLegacyMenuScreensRegistration(source: String): String {
        if (!source.contains("MenuScreens.register(") &&
            !source.contains(".renderScreens();") &&
            !(source.contains("FMLClientSetupEvent") && source.contains("event.register("))) {
            return source
        }
        var result = source
        val convertedHelpers = linkedSetOf<String>()
        if (result.contains("MenuScreens.register(")) {
            result = Regex("""(?m)^([ \t]*)public\s+static\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*\)\s*\{""")
                .replace(result) { match ->
                    val methodStart = match.range.first
                    val openBrace = result.indexOf('{', match.range.last)
                    val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                    if (closeBrace >= 0 && result.substring(openBrace + 1, closeBrace).contains("MenuScreens.register(")) {
                        val indent = match.groupValues[1]
                        val methodName = match.groupValues[2]
                        val annotationStart = annotationStartBefore(result, methodStart)
                        val hasSubscribeEvent = result.substring(annotationStart, methodStart).contains("@SubscribeEvent")
                        convertedHelpers += methodName
                        val annotation = if (hasSubscribeEvent) "" else "${indent}@SubscribeEvent\n"
                        "${annotation}${indent}public static void $methodName(RegisterMenuScreensEvent event) {"
                    } else {
                        result.substring(methodStart, match.range.last + 1)
                    }
            }
            result = result.replace("MenuScreens.register(", "event.register(")
        }
        for (helper in convertedHelpers) {
            result = Regex("""(?m)^[ \t]*(?:this\.)?${Regex.escape(helper)}\(\);\s*\r?\n""")
                .replace(result, "")
        }
        if (result.contains("FMLClientSetupEvent") && result.contains("event.register(")) {
            result = migrateFmlClientSetupMenuRegistrationMethods(result)
        }
        if (result.contains(".renderScreens();") && result.contains("FMLClientSetupEvent")) {
            val helpers = Regex("""(?m)^([ \t]*)([A-Za-z_$][\w$]*)\.renderScreens\(\);\s*$""")
                .findAll(result)
                .map { it.groupValues[2] }
                .toList()
            if (helpers.isNotEmpty()) {
                result = Regex("""(?m)^[ \t]*[A-Za-z_$][\w$]*\.renderScreens\(\);\s*\r?\n""").replace(result, "")
                if (!result.contains("RegisterMenuScreensEvent event") && !result.contains("registerMenuScreens(RegisterMenuScreensEvent")) {
                    val methodBody = helpers.distinct().joinToString("\n") { helper ->
                        "        $helper.renderScreens(event);"
                    }
                    val insertion = """

    @SubscribeEvent
    public static void registerMenuScreens(RegisterMenuScreensEvent event) {
$methodBody
    }
""".trimEnd()
                    result = insertBeforeLastClassBrace(result, insertion)
                }
            }
        }
        if (result.contains("RegisterMenuScreensEvent")) {
            result = addImportIfMissing(result, "net.neoforged.neoforge.client.event.RegisterMenuScreensEvent")
        }
        if (Regex("""(?m)^[ \t]*@SubscribeEvent\b""").containsMatchIn(result)) {
            result = addImportIfMissing(result, "net.neoforged.bus.api.SubscribeEvent")
        }
        if (!result.contains("MenuScreens.")) {
            result = removeImport(result, "net.minecraft.client.gui.screens.MenuScreens")
        }
        return result
    }

    private fun migrateFmlClientSetupMenuRegistrationMethods(source: String): String {
        var result = source
        var cursor = 0
        var changed = false
        val signaturePattern = Regex(
            """(?m)^([ \t]*(?:(?:@\w+(?:\([^)]*\))?)\s*)*public\s+static\s+void\s+[A-Za-z_$][\w$]*\s*\(\s*(?:final\s+)?FMLClientSetupEvent\s+event\s*\)\s*\{)"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            if (!body.contains("event.register(")) {
                cursor = closeBrace + 1
                continue
            }
            var migratedBody = Regex("""(?m)^([ \t]*)event\.enqueueWork\(\(\)\s*->\s*\{\s*\r?\n""")
                .replace(body, "")
            migratedBody = Regex("""(?m)^[ \t]*\}\);\s*\r?\n""").replaceFirst(migratedBody, "")
            val migratedSignature = match.value.replace("FMLClientSetupEvent", "RegisterMenuScreensEvent")
            result = result.substring(0, match.range.first) + migratedSignature + migratedBody + result.substring(closeBrace)
            cursor = match.range.first + migratedSignature.length + migratedBody.length + 1
            changed = true
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.neoforged.neoforge.client.event.RegisterMenuScreensEvent")
        if (!Regex("""\bFMLClientSetupEvent\b""").containsMatchIn(removeImport(result, "net.neoforged.fml.event.lifecycle.FMLClientSetupEvent"))) {
            result = removeImport(result, "net.neoforged.fml.event.lifecycle.FMLClientSetupEvent")
        }
        return result
    }

    private fun migrateLegacyEnchantmentIterationSource(source: String): String {
        if (!source.contains("EnchantmentHelper.getEnchantments(") &&
            !source.contains("EnchantmentHelper.enchantItem(") &&
            !source.contains(".canApplyAtEnchantingTable(") &&
            !source.contains(".getAllEnchantments()") &&
            !source.contains(".category.canEnchant(") &&
            !source.contains(".get().equals(enchantment)") &&
            !source.contains("Objects.equals(") &&
            !source.contains("server.registryAccess().lookup(net.minecraft.core.registries.Registries.ENCHANTMENT)")
        ) {
            return source
        }
        var result = source.replace("EnchantmentHelper.getEnchantments(", "EnchantmentHelper.getEnchantmentsForCrafting(")
        result = migrateLegacyItemStackAllEnchantments(result)
        result = rewriteLegacyRandomEnchantItemCalls(result)
        result = Regex(
            """EnchantmentHelper\.setEnchantments\(\s*EnchantmentHelper\.getEnchantmentsForCrafting\(([^()\r\n;]+)\)\s*,\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\)"""
        ).replace(result) { match ->
            "EnchantmentHelper.setEnchantments(${match.groupValues[2]}, EnchantmentHelper.getEnchantmentsForCrafting(${match.groupValues[1].trim()}))"
        }
        result = rewriteJavaInvocationArguments(result, "EnchantmentHelper.setEnchantments") { args ->
            if (args.size != 2) return@rewriteJavaInvocationArguments null
            val enchantments = args[0].trim()
            if (!enchantments.startsWith("EnchantmentHelper.getEnchantmentsForCrafting(")) {
                return@rewriteJavaInvocationArguments null
            }
            val openParen = enchantments.indexOf('(')
            val closeParen = if (openParen >= 0) findMatchingParen(enchantments, openParen) else -1
            if (closeParen != enchantments.length - 1) return@rewriteJavaInvocationArguments null
            listOf(args[1].trim(), enchantments)
        }
        result = Regex(
            """EnchantmentHelper\.getEnchantmentsForCrafting\(([^)]+)\)\.forEach\(\s*\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)\s*->\s*\{"""
        ).replace(result) { match ->
            "EnchantmentHelper.getEnchantmentsForCrafting(${match.groupValues[1]}).entrySet().forEach(entry -> {\n" +
                "\t\t\tnet.minecraft.core.Holder<net.minecraft.world.item.enchantment.Enchantment> ${match.groupValues[2]} = entry.getKey();\n" +
                "\t\t\tint ${match.groupValues[3]} = entry.getIntValue();"
        }
        result = Regex(
            """EnchantmentHelper\.getEnchantmentsForCrafting\(([^)]+)\)\.containsKey\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)\s*\)"""
        ).replace(result) { match ->
            "EnchantmentHelper.getEnchantmentsForCrafting(${match.groupValues[1]}).keySet().stream().anyMatch(holder -> holder.is(${match.groupValues[2]}))"
        }
        val holderVariables = collectEnchantmentHolderVariables(result)
        result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)\.get\(\)\.equals\(\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result) { match ->
                val holder = match.groupValues[2]
                if (holder in holderVariables) {
                    "$holder.is(${match.groupValues[1]})"
                } else {
                    match.value
                }
            }
        result = Regex("""Objects\.equals\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)(?:\.get\(\))?\s*,\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result) { match ->
                val holder = match.groupValues[2]
                if (holder in holderVariables) {
                    "$holder.is(${match.groupValues[1]})"
                } else {
                    match.value
                }
            }
        result = Regex("""super\.canApplyAtEnchantingTable\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result) { match -> "super.supportsEnchantment(${match.groupValues[1]}, ${match.groupValues[2]})" }
        result = rewriteLegacyHolderEnchantmentSupportChecks(result)
        result = rewriteLegacyEnchantmentHolderComparisons(result)
        result = Regex(
            """server\.registryAccess\(\)\.lookup\(net\.minecraft\.core\.registries\.Registries\.ENCHANTMENT\)\s*\.\s*flatMap\(registry\s*->\s*registry\.get\(([^)]+)\)\)\s*\.\s*map\(holder\s*->\s*EnchantmentHelper\.get(Tag|Item)EnchantmentLevel\(holder,\s*([A-Za-z_$][\w$]*)\)\)\s*\.\s*orElse\(0\)""",
            RegexOption.DOT_MATCHES_ALL
        ).replace(result) { match ->
            val key = match.groupValues[1].trim()
            val kind = match.groupValues[2]
            val stack = match.groupValues[3]
            "EnchantmentHelper.get${kind}EnchantmentLevel(net.neoforged.neoforge.common.CommonHooks.resolveLookup(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow($key), $stack)"
        }
        return result
    }

    private fun migrateLegacyItemStackAllEnchantments(source: String): String {
        if (!source.contains(".getAllEnchantments()")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val lootContextVars = Regex("""\bLootContext\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        if (lootContextVars.size != 1) return source
        val lookup = "${lootContextVars.single()}.getLevel().registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT)"
        var result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.getAllEnchantments\(\)""")
            .replace(source) { match -> "${match.groupValues[1]}.getAllEnchantments($lookup)" }
        var convertedMapEntries = false
        val convertedEntryVars = linkedSetOf<String>()
        result = Regex(
            """for\s*\(\s*Map\.Entry\s*<\s*Enchantment\s*,\s*Integer\s*>\s+($id)\s*:\s*([^\r\n]+?\.entrySet\(\))\s*\)\s*\{"""
        ).replace(result) { match ->
            convertedMapEntries = true
            convertedEntryVars += match.groupValues[1]
            "for (Object2IntMap.Entry<Holder<Enchantment>> ${match.groupValues[1]} : ${match.groupValues[2]}) {"
        }
        result = Regex("""\bEnchantment\s+($id)\s*=\s*($id)\.getKey\(\)\s*;""")
            .replace(result) { match ->
                if (match.groupValues[2] in convertedEntryVars) {
                    "Holder<Enchantment> ${match.groupValues[1]} = ${match.groupValues[2]}.getKey();"
                } else {
                    match.value
                }
            }
        result = Regex("""\bint\s+($id)\s*=\s*($id)\.getValue\(\)\s*;""")
            .replace(result) { match ->
                if (match.groupValues[2] in convertedEntryVars) {
                    "int ${match.groupValues[1]} = ${match.groupValues[2]}.getIntValue();"
                } else {
                    match.value
                }
            }
        result = Regex("""\b($id)\.getMinCost\(""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (receiver in collectEnchantmentHolderVariables(result)) "$receiver.value().getMinCost(" else match.value
            }
        result = Regex("""\b($id)\.isTreasureOnly\(\)""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (receiver in collectEnchantmentHolderVariables(result)) "$receiver.is(net.minecraft.tags.EnchantmentTags.TREASURE)" else match.value
            }
        result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.canApplyAtEnchantingTable\(\s*($id)\s*\)""")
            .replace(result) { match ->
                val enchantment = match.groupValues[2]
                if (enchantment in collectEnchantmentHolderVariables(result)) {
                    "${match.groupValues[1]}.isPrimaryItemFor($enchantment)"
                } else {
                    match.value
                }
            }
        result = Regex("""\.enchant\(\s*($id)\s*,\s*($id)\.getValue\(\)\s*\)""")
            .replace(result) { match ->
                val enchantment = match.groupValues[1]
                val entry = match.groupValues[2]
                if (enchantment in collectEnchantmentHolderVariables(result) && entry in convertedEntryVars) {
                    ".enchant($enchantment, ${match.groupValues[2]}.getIntValue())"
                } else {
                    match.value
                }
            }
        if (convertedMapEntries) {
            result = addImportIfMissing(result, "it.unimi.dsi.fastutil.objects.Object2IntMap")
            result = addImportIfMissing(result, "net.minecraft.core.Holder")
            if (!Regex("""\bMap\s*[.<]""").containsMatchIn(removeImport(result, "java.util.Map"))) {
                result = removeImport(result, "java.util.Map")
            }
        }
        return result
    }

    private fun rewriteLegacyRandomEnchantItemCalls(source: String): String {
        if (!source.contains("EnchantmentHelper.enchantItem(")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val lootContextVars = Regex("""\bLootContext\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        val mobVars = Regex("""\bMob\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        return rewriteJavaInvocationArguments(source, "EnchantmentHelper.enchantItem") { args ->
            if (args.size != 4) return@rewriteJavaInvocationArguments null
            val filterArg = args[3].trim()
            val registryAccess = when {
                lootContextVars.size == 1 -> "${lootContextVars.single()}.getLevel().registryAccess()"
                mobVars.size == 1 -> "${mobVars.single()}.registryAccess()"
                else -> return@rewriteJavaInvocationArguments null
            }
            val tag = when {
                lootContextVars.size == 1 -> "ON_RANDOM_LOOT"
                mobVars.size == 1 && filterArg == "false" -> "ON_MOB_SPAWN_EQUIPMENT"
                else -> return@rewriteJavaInvocationArguments null
            }
            val lookup = "$registryAccess.lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT)"
            listOf(
                args[0],
                args[1],
                args[2],
                registryAccess,
                "java.util.Optional.of($lookup.getOrThrow(net.minecraft.tags.EnchantmentTags.$tag))"
            )
        }
    }

    private fun rewriteLegacyHolderEnchantmentSupportChecks(source: String): String {
        if (!source.contains(".category.canEnchant(")) return source
        var result = source
        val id = """[A-Za-z_$][\w$]*"""
        val methodPattern = Regex(
            """(?m)(public\s+boolean\s+(supportsEnchantment|isPrimaryItemFor)\s*\([^)]*\bItemStack\s+($id)[^)]*\bHolder\s*<\s*Enchantment\s*>\s+($id)[^)]*\)\s*\{)"""
        )
        var cursor = 0
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val methodName = match.groupValues[2]
            val stack = match.groupValues[3]
            val enchantment = match.groupValues[4]
            val body = result.substring(openBrace + 1, closeBrace)
            val migratedBody = body.replace(
                Regex("""\b${Regex.escape(enchantment)}\.category\.canEnchant\(\s*${Regex.escape(stack)}\.getItem\(\)\s*\)"""),
                "super.$methodName($stack, $enchantment)"
            )
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun rewriteLegacyEnchantmentHolderComparisons(source: String): String {
        if (!source.contains("Enchantments.")) return source
        val holderVariables = collectEnchantmentHolderVariables(source)
        if (holderVariables.isEmpty()) return source
        var result = source
        val key = """[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+"""
        for (holder in holderVariables) {
            result = Regex("""\b${Regex.escape(holder)}\s*!=\s*($key)""")
                .replace(result) { match -> "!$holder.is(${match.groupValues[1]})" }
            result = Regex("""($key)\s*!=\s*${Regex.escape(holder)}\b""")
                .replace(result) { match -> "!$holder.is(${match.groupValues[1]})" }
            result = Regex("""\b${Regex.escape(holder)}\s*==\s*($key)""")
                .replace(result) { match -> "$holder.is(${match.groupValues[1]})" }
            result = Regex("""($key)\s*==\s*${Regex.escape(holder)}\b""")
                .replace(result) { match -> "$holder.is(${match.groupValues[1]})" }
        }
        return result
    }

    private fun collectEnchantmentHolderVariables(source: String): Set<String> {
        val id = """[A-Za-z_$][\w$]*"""
        val holderType = """(?:net\.minecraft\.core\.)?Holder\s*<\s*(?:net\.minecraft\.world\.item\.enchantment\.)?Enchantment\s*>"""
        return Regex("""\b(?:final\s+)?$holderType\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
    }

    private fun migrateStringRepresentableEnumCodecs(source: String): String {
        if (!source.contains("implements StringRepresentable") || source.contains("StringRepresentable.EnumCodec<")) {
            return source
        }
        val enumMatch = Regex("""(?m)\bpublic\s+enum\s+([A-Za-z_$][\w$]*)\s+implements\s+StringRepresentable\b[^{]*\{""")
            .find(source)
            ?: return source
        val enumName = enumMatch.groupValues[1]
        if (Regex("""\bCODEC\b""").containsMatchIn(source.substring(enumMatch.range.last + 1))) {
            return source
        }
        val openBrace = source.indexOf('{', enumMatch.range.first)
        if (openBrace < 0) return source
        val constantsEnd = findEnumConstantsTerminator(source, openBrace) ?: return source
        val insert = """

	public static final StringRepresentable.EnumCodec<$enumName> CODEC = StringRepresentable.fromEnum($enumName::values);
""".trimEnd()
        return source.substring(0, constantsEnd + 1) + insert + source.substring(constantsEnd + 1)
    }

    private fun findEnumConstantsTerminator(source: String, openBrace: Int): Int? {
        var parenDepth = 0
        var braceDepth = 0
        var inString = false
        var escaped = false
        var inLineComment = false
        var inBlockComment = false
        var i = openBrace + 1
        while (i < source.length) {
            val ch = source[i]
            val next = source.getOrNull(i + 1)
            if (inLineComment) {
                if (ch == '\n') inLineComment = false
                i++
                continue
            }
            if (inBlockComment) {
                if (ch == '*' && next == '/') {
                    inBlockComment = false
                    i += 2
                } else {
                    i++
                }
                continue
            }
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                i++
                continue
            }
            when {
                ch == '/' && next == '/' -> {
                    inLineComment = true
                    i += 2
                    continue
                }
                ch == '/' && next == '*' -> {
                    inBlockComment = true
                    i += 2
                    continue
                }
                ch == '"' -> inString = true
                ch == '(' -> parenDepth++
                ch == ')' && parenDepth > 0 -> parenDepth--
                ch == '{' -> braceDepth++
                ch == '}' -> {
                    if (braceDepth == 0) return null
                    braceDepth--
                }
                ch == ';' && parenDepth == 0 && braceDepth == 0 -> return i
            }
            i++
        }
        return null
    }

    private fun migrateLegacyLootEnchantmentHolderCalls(source: String): String {
        val needsFortuneHolder = source.contains("Enchantments.FORTUNE") &&
            Regex("""(?:ApplyBonusCount\.add(?:Ore|Uniform|BonusBinomialDistribution)BonusCount|BonusLevelTableCondition\.bonusLevelFlatChance)\(\s*Enchantments\.FORTUNE""")
                .containsMatchIn(source)
        val needsRandomProvider = source.contains("EnchantRandomlyFunction.randomApplicableEnchantment()")
        if (!needsFortuneHolder && !needsRandomProvider) {
            return source
        }

        var result = migrateLootTableSubProviderHolderLookupState(source)
        val providerExpression = inferHolderLookupProviderInstanceExpression(result) ?: return source
        if (needsFortuneHolder) {
            val fortuneHolder = "$providerExpression.holderOrThrow(Enchantments.FORTUNE)"
            result = Regex(
                """((?:ApplyBonusCount\.add(?:Ore|Uniform|BonusBinomialDistribution)BonusCount|BonusLevelTableCondition\.bonusLevelFlatChance)\(\s*)Enchantments\.FORTUNE"""
            ).replace(result, "$1$fortuneHolder")
        }
        if (needsRandomProvider) {
            result = result.replace(
                "EnchantRandomlyFunction.randomApplicableEnchantment()",
                "EnchantRandomlyFunction.randomApplicableEnchantment($providerExpression)"
            )
        }
        return result
    }

    private fun migrateLootTableSubProviderHolderLookupState(source: String): String {
        if (!source.contains("HolderLookup.Provider") ||
            !source.contains("implements LootTableSubProvider") ||
            source.contains("record ") ||
            source.contains("this.registries") ||
            Regex("""\bHolderLookup\.Provider\s+registries\s*[;=]""").containsMatchIn(source)) {
            return source
        }
        val classMatch = Regex("""(?s)\bclass\s+([A-Za-z_$][\w$]*)\b[^{;]*\bimplements\s+[^{};]*LootTableSubProvider\b[^{]*\{""")
            .find(source)
            ?: return source
        if (source.substring(classMatch.range.first, classMatch.range.last + 1).contains("extends")) return source
        val className = classMatch.groupValues[1]
        val constructorMatch = Regex(
            """(?s)\b(?:public|protected|private)?\s*${Regex.escape(className)}\s*\((.*?)\)\s*\{"""
        ).find(source, classMatch.range.last)
            ?: return source
        val providerParam = splitTopLevelJavaArgs(constructorMatch.groupValues[1])
            .mapNotNull(::parseJavaParameter)
            .firstOrNull { (type, _) -> type.endsWith("HolderLookup.Provider") || type == "HolderLookup.Provider" }
            ?: return source
        val paramName = providerParam.second
        if (Regex("""\bHolderLookup\.Provider\s+${Regex.escape(paramName)}\s*[;=]""").containsMatchIn(source)) {
            return source
        }

        var result = source
        val classOpenBrace = result.indexOf('{', classMatch.range.last)
        if (classOpenBrace < 0) return source
        val fieldLine = "\n    private final HolderLookup.Provider $paramName;\n"
        result = result.substring(0, classOpenBrace + 1) + fieldLine + result.substring(classOpenBrace + 1)
        val constructorOpenBrace = result.indexOf('{', constructorMatch.range.last + fieldLine.length)
        if (constructorOpenBrace < 0) return source
        val assignment = "\n        this.$paramName = $paramName;"
        result = result.substring(0, constructorOpenBrace + 1) + assignment + result.substring(constructorOpenBrace + 1)
        return result
    }

    private fun inferHolderLookupProviderInstanceExpression(source: String): String? {
        if (Regex("""extends\s+(?:[A-Za-z_$][\w$]*\.)?(?:[A-Za-z_$][\w$]*)?BlockLootSubProvider\b""").containsMatchIn(source) ||
            Regex("""extends\s+(?:[A-Za-z_$][\w$]*\.)?(?:[A-Za-z_$][\w$]*)?EntityLootSubProvider\b""").containsMatchIn(source)) {
            return "this.registries"
        }
        Regex("""\brecord\s+[A-Za-z_$][\w$]*\s*\([^)]*\bHolderLookup\.Provider\s+([A-Za-z_$][\w$]*)""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { return "this.$it" }
        Regex("""\b(?:private|protected|public)?\s*(?:final\s+)?HolderLookup\.Provider\s+([A-Za-z_$][\w$]*)\s*[;=]""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { return "this.$it" }
        return null
    }

    private fun migrateLegacyBlockLootSubProviderSource(source: String): String {
        if (!source.contains("BlockLootSubProvider")) return source
        val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+(?:[A-Za-z_$][\w$]*\.)?(?:[A-Za-z_$][\w$]*)?BlockLootSubProvider\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        var result = source
        val constructorPattern = Regex("""(?s)((?:public|protected)\s+)${Regex.escape(className)}\s*\((.*?)\)\s*\{\s*super\s*\((.*?)\)\s*;\s*\}""")
        result = constructorPattern.replace(result) { match ->
            val params = splitTopLevelJavaArgs(match.groupValues[2])
            if (params.any { it.contains("HolderLookup.Provider") }) return@replace match.value
            val args = splitTopLevelJavaArgs(match.groupValues[3])
            if (args.size == 2) {
                val newParams = (params + "HolderLookup.Provider registries").joinToString(", ")
                "${match.groupValues[1]}$className($newParams) {\n\t\tsuper(${args[0]}, ${args[1]}, registries);\n\t}"
            } else {
                match.value
            }
        }
        if (result.contains("HolderLookup.Provider registries")) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        }
        result = result.replace("HAS_SHEARS.or(HAS_SILK_TOUCH)", "HAS_SHEARS.or(this.hasSilkTouch())")
        result = result.replace("HAS_SILK_TOUCH", "this.hasSilkTouch()")
        result = Regex("""protected\s+static\s+LootTable\.Builder\s+(create(?:SilkTouchOr)?Shears(?:DispatchTable|OnlyDrop)\w*)\(""")
            .replace(result) { match ->
                if (match.groupValues[1].contains("DispatchTable")) {
                    return@replace "protected LootTable.Builder ${match.groupValues[1]}("
                }
                val openBrace = result.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                val body = if (openBrace >= 0 && closeBrace > openBrace) result.substring(openBrace + 1, closeBrace) else ""
                if (body.contains("this.")) {
                    "protected LootTable.Builder ${match.groupValues[1]}("
                } else {
                    match.value
                }
            }
        result = Regex("""protected\s+LootTable\.Builder\s+createShearsOnlyDrop\(""")
            .replace(result) { match ->
                val openBrace = result.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                val body = if (openBrace >= 0 && closeBrace > openBrace) result.substring(openBrace + 1, closeBrace) else ""
                if (body.contains("this.")) match.value else "protected static LootTable.Builder createShearsOnlyDrop("
            }
        return result
    }

    private fun migrateLegacySpriteSourceProviderSource(
        source: String,
        spriteSourceProviderClasses: Set<String>
    ): String {
        if (!source.contains("SpriteSourceProvider") && spriteSourceProviderClasses.none { source.contains("new $it(") }) {
            return source
        }

        var result = source
        var changed = false
        val localProviderClasses = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+(?:[A-Za-z_$][\w$]*\.)?SpriteSourceProvider\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()

        localProviderClasses.forEach { className ->
            val constructorPattern = Regex(
                """(?s)public\s+${Regex.escape(className)}\s*\((.*?)\)\s*\{\s*super\s*\((.*?)\)\s*;\s*\}"""
            )
            result = constructorPattern.replace(result) { match ->
                val params = splitTopLevelJavaArgs(match.groupValues[1])
                val superArgs = splitTopLevelJavaArgs(match.groupValues[2])
                if (params.size != 2 || superArgs.size != 3) return@replace match.value
                val outputParam = parseJavaParameter(params[0]) ?: return@replace match.value
                val helperParam = parseJavaParameter(params[1]) ?: return@replace match.value
                if (!outputParam.first.endsWith("PackOutput") || !helperParam.first.endsWith("ExistingFileHelper")) {
                    return@replace match.value
                }
                if (superArgs[0].trim() != outputParam.second || superArgs[1].trim() != helperParam.second) {
                    return@replace match.value
                }
                changed = true
                "public $className(${outputParam.first} ${outputParam.second}, CompletableFuture<HolderLookup.Provider> provider, ${helperParam.first} ${helperParam.second}) {\n\t\tsuper(${outputParam.second}, provider, ${superArgs[2].trim()}, ${helperParam.second});\n\t}"
            }
            result = Regex("""(?m)^([ \t]*(?:protected|public)\s+)void\s+addSources\s*\(""")
                .replace(result) { match ->
                    changed = true
                    "${match.groupValues[1]}void gather("
                }
        }

        val providerExpression = inferHolderLookupProviderExpression(result)
        if (providerExpression != null && spriteSourceProviderClasses.isNotEmpty()) {
            spriteSourceProviderClasses.forEach { className ->
                val token = "new $className("
                var cursor = 0
                while (cursor < result.length) {
                    val tokenIndex = result.indexOf(token, cursor)
                    if (tokenIndex < 0) break
                    val openParen = tokenIndex + "new $className".length
                    val closeParen = findMatchingParen(result, openParen)
                    if (closeParen < 0) break
                    val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
                    if (args.size == 2) {
                        val replacement = "new $className(${args[0].trim()}, $providerExpression, ${args[1].trim()})"
                        result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
                        cursor = tokenIndex + replacement.length
                        changed = true
                    } else {
                        cursor = closeParen + 1
                    }
                }
            }
        }

        if (!changed) return source
        if (result.contains("CompletableFuture<HolderLookup.Provider>")) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
            result = addImportIfMissing(result, "java.util.concurrent.CompletableFuture")
        }
        return result
    }

    private fun parseJavaParameter(parameter: String): Pair<String, String>? {
        val clean = parameter.trim().removePrefix("final ").trim()
        val match = Regex("""(.+?)\s+([A-Za-z_$][\w$]*)$""").find(clean) ?: return null
        return match.groupValues[1].trim() to match.groupValues[2]
    }

    private fun inferHolderLookupProviderExpression(source: String): String? {
        Regex(
            """(?:java\.util\.concurrent\.)?CompletableFuture\s*<\s*HolderLookup\.Provider\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*[^;]*getLookupProvider\s*\("""
        ).find(source)?.groupValues?.get(1)?.let { return it }
        Regex(
            """(?:java\.util\.concurrent\.)?CompletableFuture\s*<\s*HolderLookup\.Provider\s*>\s+([A-Za-z_$][\w$]*)\b"""
        ).find(source)?.groupValues?.get(1)?.let { return it }
        Regex("""\bGatherDataEvent\s+([A-Za-z_$][\w$]*)\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { return "$it.getLookupProvider()" }
        return null
    }

    private fun migrateLegacyRecipeProviderSource(
        source: String,
        recipeProviderClasses: RecipeProviderClassHints,
        projectModIdExpression: String? = null
    ): String {
        if (recipeProviderClasses.all.isEmpty() ||
            (!source.contains("RecipeProvider") &&
                recipeProviderClasses.all.none {
                    source.contains("new $it(") ||
                        source.contains("$it::new") ||
                        Regex("""\bclass\s+${Regex.escape(it)}\b""").containsMatchIn(source)
                })) {
            return source
        }

        var result = source
        var changed = false
        val localRecipeProviderClasses = recipeProviderClasses.all.filter { className ->
            Regex("""\bclass\s+${Regex.escape(className)}\b""").containsMatchIn(result)
        }

        for (className in localRecipeProviderClasses) {
            val constructorPattern = Regex(
                """(?s)public\s+${Regex.escape(className)}\s*\((.*?)\)\s*\{\s*super\s*\((.*?)\)\s*;\s*\}"""
            )
            result = constructorPattern.replace(result) { match ->
                val params = splitTopLevelJavaArgs(match.groupValues[1])
                val parsedParams = params.mapNotNull(::parseJavaParameter)
                val outputParam = parsedParams.firstOrNull { (type, _) -> type.substringAfterLast('.') == "PackOutput" }
                    ?: return@replace match.value
                val lookupParam = parsedParams.firstOrNull { (type, _) ->
                    type.contains("CompletableFuture") && type.contains("HolderLookup.Provider")
                }
                val keptParams = params.filter { param ->
                    val name = parseJavaParameter(param)?.second
                    name != outputParam.second && name != lookupParam?.second
                }
                val lookupName = lookupParam?.second ?: "lookupProvider"
                val newParams = (listOf("${outputParam.first} ${outputParam.second}", "CompletableFuture<HolderLookup.Provider> $lookupName") + keptParams)
                    .joinToString(", ")
                val superArgs = splitTopLevelJavaArgs(match.groupValues[2]).map { it.trim() }
                val keptSuperArgs = superArgs.filter { it != outputParam.second && it != lookupParam?.second }
                val parentClass = Regex("""\bclass\s+${Regex.escape(className)}\s+extends\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)""")
                    .find(result)
                    ?.groupValues
                    ?.get(1)
                    ?.substringAfterLast('.')
                val modIdArg = if (parentClass == "AbstractRecipeProvider" && keptSuperArgs.isEmpty()) {
                    singleProjectModIdExpression(result, projectModIdExpression)?.let(::listOf).orEmpty()
                } else {
                    emptyList()
                }
                val newSuperArgs = (listOf(outputParam.second) + modIdArg + listOf(lookupName) + keptSuperArgs).joinToString(", ")
                changed = true
                "public $className($newParams) {\n\t\tsuper($newSuperArgs);\n\t}"
            }

            result = removeLegacyRecipeProviderStaticHasOverride(result)
        }

        val providerExpression = inferHolderLookupProviderExpression(result)
        if (providerExpression != null && (result.contains("DataGenerator") || result.contains("GatherDataEvent"))) {
            for (className in recipeProviderClasses.concrete) {
                val token = "new $className("
                var cursor = 0
                while (cursor < result.length) {
                    val tokenIndex = result.indexOf(token, cursor)
                    if (tokenIndex < 0) break
                    val openParen = tokenIndex + "new $className".length
                    val closeParen = findMatchingParen(result, openParen)
                    if (closeParen < 0) break
                    val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
                    if (args.none { it.trim() == providerExpression } && args.isNotEmpty()) {
                        val outputArg = args.first().trim()
                        val replacementArgs = (listOf(outputArg, providerExpression) + args.drop(1).map { it.trim() }).joinToString(", ")
                        val replacement = "new $className($replacementArgs)"
                        result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
                        cursor = tokenIndex + replacement.length
                        changed = true
                    } else {
                        cursor = closeParen + 1
                    }
                }
                result = Regex(
                    """\(\s*DataProvider\.Factory\s*<\s*${Regex.escape(className)}\s*>\s*\)\s*${Regex.escape(className)}::new"""
                ).replace(result) {
                    changed = true
                    "(DataProvider.Factory<$className>) output -> new $className(output, $providerExpression)"
                }
            }
        }

        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        if (result.contains("CompletableFuture<HolderLookup.Provider>")) {
            result = addImportIfMissing(result, "java.util.concurrent.CompletableFuture")
        }
        return result
    }

    private fun singleProjectModIdExpression(source: String, projectModIdExpression: String?): String? {
        projectModIdExpression?.takeIf { it.isNotBlank() }?.let { return it }
        val executableCode = maskJavaCommentsAndLiterals(source)
        val expressions = Regex("""\b([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.(?:MODID|MOD_ID))\b""")
            .findAll(executableCode)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        return expressions.singleOrNull()
    }

    private fun removeLegacyRecipeProviderStaticHasOverride(source: String): String {
        if (!source.contains("InventoryChangeTrigger.TriggerInstance has(") ||
            !source.contains("extends RecipeProvider")) {
            return source
        }
        return Regex(
            """(?s)\n[ \t]*protected\s+static\s+InventoryChangeTrigger\.TriggerInstance\s+has\s*\(\s*TagKey\s*<\s*Item\s*>\s+[A-Za-z_$][\w$]*\s*\)\s*\{\s*return\s+inventoryTrigger\s*\(.*?\);\s*\}\s*"""
        ).replace(source, "\n")
    }

    private fun migrateLegacyRecipeBuilderSource(
        source: String,
        recipeSerializerFactoryHints: RecipeSerializerFactoryHints
    ): String {
        if (!source.contains("RecipeBuilder") &&
            !source.contains("SpecialRecipeBuilder.special(") &&
            !source.contains("SimpleCookingRecipeBuilder.generic(") &&
            !source.contains("consumer.accept(new Result(") &&
            !source.contains("output.accept(new Result(") &&
            !source.contains(".toJson()")) {
            return source
        }

        var result = source
        var changed = false

        if (result.contains("SpecialRecipeBuilder.special(") && recipeSerializerFactoryHints.fieldToFactory.isNotEmpty()) {
            result = rewriteJavaCall(result, "special") { receiver, args ->
                if (receiver != "SpecialRecipeBuilder" || args.size != 1) return@rewriteJavaCall null
                val expression = args[0].trim().removeSuffix(".get()")
                val factory = recipeSerializerFactoryHints.fieldToFactory[expression] ?: return@rewriteJavaCall null
                changed = true
                "SpecialRecipeBuilder.special($factory)"
            }
        }

        val cookingFactories = mapOf(
            "RecipeSerializer.SMELTING_RECIPE" to "SmeltingRecipe::new",
            "RecipeSerializer.SMOKING_RECIPE" to "SmokingRecipe::new",
            "RecipeSerializer.BLASTING_RECIPE" to "BlastingRecipe::new",
            "RecipeSerializer.CAMPFIRE_COOKING_RECIPE" to "CampfireCookingRecipe::new"
        )
        for ((serializer, factory) in cookingFactories) {
            result = result.replace("$serializer,", "$serializer, $factory,")
        }
        if (result != source) changed = true

        if (result.contains("SimpleCookingRecipeBuilder.generic(")) {
            result = rewriteJavaCall(result, "generic") { receiver, args ->
                if (receiver != "SimpleCookingRecipeBuilder" || args.size != 6) return@rewriteJavaCall null
                val serializer = args[5].trim()
                val factory = cookingFactories[serializer] ?: return@rewriteJavaCall null
                changed = true
                "SimpleCookingRecipeBuilder.generic(${args.take(6).joinToString(", ") { it.trim() }}, $factory)"
            }
        }

        val cookingMethodPattern = Regex(
            """(?m)^([ \t]*private\s+)void\s+([A-Za-z_$][\w$]*)\s*\(([^)]*RecipeSerializer\s*<\s*\?\s+extends\s+AbstractCookingRecipe\s*>\s+([A-Za-z_$][\w$]*)[^)]*)\)"""
        )
        val genericCookingMethods = linkedMapOf<String, String>()
        result = cookingMethodPattern.replace(result) { match ->
            val methodName = match.groupValues[2]
            val serializerParam = match.groupValues[4]
            genericCookingMethods[methodName] = serializerParam
            changed = true
            val params = match.groupValues[3]
                .replace(
                    Regex("""RecipeSerializer\s*<\s*\?\s+extends\s+AbstractCookingRecipe\s*>\s+${Regex.escape(serializerParam)}"""),
                    "RecipeSerializer<T> $serializerParam, AbstractCookingRecipe.Factory<T> ${serializerParam}Factory"
                )
            "${match.groupValues[1]}<T extends AbstractCookingRecipe> void $methodName($params)"
        }
        for ((methodName, serializerParam) in genericCookingMethods) {
            result = rewriteJavaCall(result, "generic") { receiver, args ->
                if (receiver != "SimpleCookingRecipeBuilder" || args.size != 6 || args[5].trim() != serializerParam) {
                    return@rewriteJavaCall null
                }
                changed = true
                "SimpleCookingRecipeBuilder.generic(${args.joinToString(", ") { it.trim() }}, ${serializerParam}Factory)"
            }
            for ((serializer, factory) in cookingFactories) {
                result = rewriteJavaCall(result, methodName) { receiver, args ->
                    if (receiver.isNotBlank() || serializer !in args.map { it.trim() }) return@rewriteJavaCall null
                    val serializerIndex = args.indexOfFirst { it.trim() == serializer }
                    if (serializerIndex < 0) return@rewriteJavaCall null
                    val migratedArgs = args.toMutableList()
                    migratedArgs.add(serializerIndex + 1, factory)
                    changed = true
                    "$methodName(${migratedArgs.joinToString(", ") { it.trim() }})"
                }
            }
        }

        if (result.contains("implements RecipeBuilder")) {
            result = Regex("""CriterionTriggerInstance\s+([A-Za-z_$][\w$]*)""")
                .replace(result) {
                    changed = true
                    "Criterion<?> ${it.groupValues[1]}"
                }
            result = result.replace("this.getDefaultRecipeId(this.getResult()).getPath()", "RecipeBuilder.getDefaultRecipeId(this.getResult()).getPath()")
        }

        migrateLegacyRecipeBuilderAdvancementCriteriaSource(result)?.let { migrated ->
            result = migrated
            changed = true
        }

        migrateLegacyFinishedRecipeBuilderOutputSource(result, recipeSerializerFactoryHints)?.let { migrated ->
            result = migrated
            changed = true
        }

        if (result.contains(".toJson()")) {
            result = Regex("""((?:this\.)?[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.toJson\(\)""")
                .replace(result) { match ->
                    changed = true
                    "Ingredient.CODEC.encodeStart(JsonOps.INSTANCE, ${match.groupValues[1]}).getOrThrow()"
                }
        }

        if (!changed) return source
        if (result.contains("Criterion<?>")) {
            result = addImportIfMissing(result, "net.minecraft.advancements.Criterion")
            result = removeImport(result, "net.minecraft.advancements.CriterionTriggerInstance")
        }
        if (result.contains("new LinkedHashMap<>()")) {
            result = addImportIfMissing(result, "java.util.LinkedHashMap")
            result = addImportIfMissing(result, "java.util.Map")
        }
        if (result.contains("JsonOps.INSTANCE")) {
            result = addImportIfMissing(result, "com.mojang.serialization.JsonOps")
        }
        if (result.contains("ShapedRecipePattern.of(")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.ShapedRecipePattern")
        }
        if (result.contains("SmeltingRecipe::new")) result = addImportIfMissing(result, "net.minecraft.world.item.crafting.SmeltingRecipe")
        if (result.contains("SmokingRecipe::new")) result = addImportIfMissing(result, "net.minecraft.world.item.crafting.SmokingRecipe")
        if (result.contains("BlastingRecipe::new")) result = addImportIfMissing(result, "net.minecraft.world.item.crafting.BlastingRecipe")
        if (result.contains("CampfireCookingRecipe::new")) result = addImportIfMissing(result, "net.minecraft.world.item.crafting.CampfireCookingRecipe")
        return result
    }

    private fun migrateLegacyRecipeBuilderAdvancementCriteriaSource(source: String): String? {
        if (!source.contains("implements RecipeBuilder") ||
            !source.contains("Advancement.Builder") ||
            !source.contains(".getCriteria()")) {
            return null
        }
        val advancementField = Regex(
            """private\s+final\s+Advancement\.Builder\s+([A-Za-z_$][\w$]*)\s*=\s*Advancement\.Builder\.advancement\(\)\s*;"""
        ).find(source)?.groupValues?.get(1) ?: return null
        val saveOutput = Regex(
            """void\s+save\s*\(\s*RecipeOutput\s+([A-Za-z_$][\w$]*)\s*,"""
        ).find(source)?.groupValues?.get(1) ?: return null

        var result = source
        result = Regex(
            """private\s+final\s+Advancement\.Builder\s+${Regex.escape(advancementField)}\s*=\s*Advancement\.Builder\.advancement\(\)\s*;"""
        ).replace(result, "private final Map<String, Criterion<?>> criteria = new LinkedHashMap<>();")
        result = Regex("""this\.${Regex.escape(advancementField)}\.addCriterion\(([^;\r\n]+)\);""")
            .replace(result) { match -> "this.criteria.put(${match.groupValues[1]});" }
        result = result.replace("this.$advancementField.getCriteria().isEmpty()", "this.criteria.isEmpty()")

        val advancementLine = Regex(
            """(?m)^([ \t]*)this\.${Regex.escape(advancementField)}\.parent\(([^;\r\n]+)\)\.addCriterion\(([^;\r\n]+)\)\.rewards\(([^;\r\n]+)\)\.requirements\(([^;\r\n]+)\);\s*$"""
        )
        result = advancementLine.replace(result) { match ->
            val indent = match.groupValues[1]
            "${indent}Advancement.Builder advancementBuilder = $saveOutput.advancement().addCriterion(${match.groupValues[3]}).rewards(${match.groupValues[4]}).requirements(${match.groupValues[5]});\n" +
                "${indent}this.criteria.forEach(advancementBuilder::addCriterion);"
        }
        result = replaceLegacyResultAdvancementArgument(result, advancementField)

        return if (result != source) result else null
    }

    private fun replaceLegacyResultAdvancementArgument(source: String, advancementField: String): String {
        var result = source
        var cursor = 0
        val constructorPattern = Regex("""new\s+((?:[A-Za-z_$][\w$]*\.)*Result)\s*\(""")
        while (true) {
            val match = constructorPattern.find(result, cursor) ?: break
            val openParen = result.indexOf('(', match.range.last - 1)
            val closeParen = if (openParen >= 0) findMatchingParen(result, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.none { it.trim() == "this.$advancementField" }) {
                cursor = closeParen + 1
                continue
            }
            val migratedArgs = args.joinToString(", ") { arg ->
                if (arg.trim() == "this.$advancementField") "advancementBuilder" else arg.trim()
            }
            val replacement = "new ${match.groupValues[1]}($migratedArgs)"
            result = result.substring(0, match.range.first) + replacement + result.substring(closeParen + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private fun migrateLegacyFinishedRecipeBuilderOutputSource(
        source: String,
        recipeSerializerFactoryHints: RecipeSerializerFactoryHints
    ): String? {
        if (!source.contains("implements RecipeBuilder") || !source.contains("new Result(")) return null
        val serializerExpression = Regex(
            """(?s)public\s+RecipeSerializer\s*<\s*\?\s*>\s+getType\s*\(\s*\)\s*\{\s*return\s+((?:[A-Za-z_$][\w$]*\.)+[A-Z][A-Z0-9_]*)\.get\s*\(\s*\)\s*;\s*\}"""
        ).find(source)?.groupValues?.get(1) ?: return null
        val recipeClass = recipeSerializerFactoryHints.fieldToRecipeClass[serializerExpression] ?: return null
        var changed = false
        val result = Regex(
            """(?m)^([ \t]*)([A-Za-z_$][\w$]*)\.accept\(\s*new\s+Result\s*\(([^;\r\n]+)\)\s*\)\s*;"""
        ).replace(source) { match ->
            val args = splitTopLevelJavaArgs(match.groupValues[3]).map { it.trim() }
            if (args.size < 6) return@replace match.value
            val output = match.groupValues[2]
            val id = args[0]
            val input = args[1]
            val count = args[2]
            val cost = args[3]
            val rows = args[4]
            val key = args[5]
            changed = true
            "${match.groupValues[1]}ShapedRecipePattern pattern = ShapedRecipePattern.of($key, $rows);\n" +
                "${match.groupValues[1]}$output.accept($id, new $recipeClass($cost, $input, $count, pattern), null);"
        }
        return if (changed) result else null
    }

    private fun migrateDataPackRegistryMapCodecSource(
        source: String,
        mapCodecConstantOwners: Set<String>
    ): String {
        if (mapCodecConstantOwners.isEmpty() || !source.contains(".dataPackRegistry(")) return source

        var result = source
        var changed = false
        var cursor = 0
        val token = ".dataPackRegistry"
        while (cursor < result.length) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = result.indexOf('(', tokenIndex + token.length)
            if (openParen < 0) break
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val migratedArgs = args.map { arg ->
                val trimmed = arg.trim()
                val owner = mapCodecCodecReferenceOwner(trimmed)
                if (owner != null && owner in mapCodecConstantOwners) {
                    changed = true
                    "${trimmed}.codec()"
                } else {
                    arg
                }
            }
            if (migratedArgs != args) {
                val replacement = migratedArgs.joinToString(", ")
                result = result.substring(0, openParen + 1) + replacement + result.substring(closeParen)
                cursor = openParen + replacement.length + 1
            } else {
                cursor = closeParen + 1
            }
        }
        return if (changed) result else source
    }

    private fun migrateRegistrySetBuilderBuildPatchSource(source: String): String {
        if (!source.contains(".buildPatch(") ||
            !source.contains("DatapackBuiltinEntriesProvider") ||
            !source.contains("extends DatapackBuiltinEntriesProvider")) {
            return source
        }
        val builderFields = Regex(
            """\b(?:public|protected|private)?\s*static\s+final\s+RegistrySetBuilder\s+([A-Za-z_$][\w$]*)\s*="""
        ).findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (builderFields.isEmpty()) return source

        var result = source
        var changed = false
        builderFields.forEach { builderField ->
            val methodPattern = Regex(
                """(?s)\n[ \t]*public\s+static\s+HolderLookup\.Provider\s+createLookup\s*\(\s*\)\s*\{\s*return\s+${Regex.escape(builderField)}\.buildPatch\s*\(\s*RegistryAccess\.fromRegistryOfRegistries\s*\(\s*BuiltInRegistries\.REGISTRY\s*\)\s*,\s*VanillaRegistries\.createLookup\s*\(\s*\)\s*\)\s*;\s*\}\s*"""
            )
            val migrated = methodPattern.replace(result, "\n")
            if (migrated != result) {
                changed = true
                result = migrated
            }
        }
        if (!changed) return source
        listOf(
            "net.minecraft.core.RegistryAccess",
            "net.minecraft.core.registries.BuiltInRegistries",
            "net.minecraft.data.registries.VanillaRegistries"
        ).forEach { importName ->
            val candidate = removeImport(result, importName)
            val simpleName = importName.substringAfterLast('.')
            if (!Regex("""\b${Regex.escape(simpleName)}\b""").containsMatchIn(candidate)) {
                result = candidate
            }
        }
        return result
    }

    private fun mapCodecCodecReferenceOwner(expression: String): String? {
        if (expression.endsWith(".codec()")) return null
        val match = Regex("""^(?:[A-Za-z_$][\w$]*\.)*([A-Z][A-Za-z0-9_$]*)\.CODEC$""").find(expression)
        return match?.groupValues?.get(1)
    }

    private fun migrateRegistryFileCodecMapCodecSource(
        source: String,
        mapCodecConstantOwners: Set<String>
    ): String {
        if (mapCodecConstantOwners.isEmpty() || !source.contains("RegistryFileCodec.create(")) return source
        val localClass = Regex("""\b(?:class|record|enum)\s+([A-Za-z_$][\w$]*)\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
        var changed = false
        val result = rewriteJavaInvocationArguments(source, "RegistryFileCodec.create") { args ->
            if (args.size < 2) return@rewriteJavaInvocationArguments null
            val codec = args[1].trim()
            val owner = mapCodecCodecReferenceOwner(codec)
            val isLocalCodec = codec == "CODEC" && localClass != null && localClass in mapCodecConstantOwners
            if ((owner == null || owner !in mapCodecConstantOwners) && !isLocalCodec) {
                return@rewriteJavaInvocationArguments null
            }
            val migrated = args.toMutableList()
            migrated[1] = "$codec.codec()"
            changed = true
            migrated
        }
        return if (changed) result else source
    }

    private fun migrateLegacyFunctionalInterfaceMapCodecSource(source: String): String {
        if (!source.contains("@FunctionalInterface") ||
            !source.contains("Codec<? extends") ||
            !source.contains("getCodec()")
        ) {
            return source
        }
        var result = Regex("""\bCodec\s*<\s*\?\s+extends\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*>\s+getCodec\s*\(\s*\)\s*;""")
            .replace(source) { match ->
                "MapCodec<? extends ${match.groupValues[1]}> getCodec();"
            }
        if (result == source) return source
        result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
        val withoutCodecImport = removeImport(result, "com.mojang.serialization.Codec")
        if (!Regex("""\bCodec\b""").containsMatchIn(withoutCodecImport)) {
            result = withoutCodecImport
        }
        return result
    }

    private fun migrateLegacyForgeBusBindingCalls(source: String): String {
