    private fun replaceExecutableJavaRegex(
        source: String,
        pattern: Regex,
        transform: (MatchResult) -> String
    ): String {
        val executableCode = maskJavaCommentsAndLiterals(source)
        var result = source
        pattern.findAll(executableCode).toList().asReversed().forEach { match ->
            result = result.substring(0, match.range.first) + transform(match) + result.substring(match.range.last + 1)
        }
        return result
    }

    private fun rewriteSuperConstructorCalls(
        source: String,
        transform: (args: List<String>) -> String?
    ): String =
        rewriteExecutableSuperConstructorCalls(source, transform)

    private fun rewriteExecutableSuperConstructorCalls(
        source: String,
        transform: (args: List<String>) -> String?
    ): String {
        var result = source
        var cursor = 0
        val token = "super("
        while (true) {
            val executableCode = maskJavaCommentsAndLiterals(result)
            val tokenIndex = executableCode.indexOf(token, cursor)
            if (tokenIndex < 0) break
            if (tokenIndex > 0 && (executableCode[tokenIndex - 1].isLetterOrDigit() || executableCode[tokenIndex - 1] == '_' || executableCode[tokenIndex - 1] == '.')) {
                cursor = tokenIndex + token.length
                continue
            }
            val openParen = tokenIndex + token.length - 1
            val closeParen = findMatchingParen(executableCode, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val replacement = transform(args)
            if (replacement == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
        }
        return result
    }

    private fun splitTopLevelJavaArgs(args: String): List<String> {
        val result = mutableListOf<String>()
        var start = 0
        var parenDepth = 0
        var braceDepth = 0
        var bracketDepth = 0
        var angleDepth = 0
        var inString = false
        var escaped = false
        for (i in args.indices) {
            val ch = args[i]
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                continue
            }
            when (ch) {
                '"' -> inString = true
                '(' -> parenDepth++
                ')' -> parenDepth--
                '{' -> braceDepth++
                '}' -> braceDepth--
                '[' -> bracketDepth++
                ']' -> bracketDepth--
                '<' -> angleDepth++
                '>' -> if (angleDepth > 0) angleDepth--
                ',' -> if (parenDepth == 0 && braceDepth == 0 && bracketDepth == 0 && angleDepth == 0) {
                    result.add(args.substring(start, i))
                    start = i + 1
                }
            }
        }
        result.add(args.substring(start))
        return result.map { it.trim() }.filter { it.isNotEmpty() }
    }

